function seedSales(){
  let r=11;const rnd=()=>{r=(r*16807)%2147483647;return r/2147483647};
  const now=new Date(),d0=today(),list=[];
  for(let i=0;i<18;i++){
    const h=10+Math.floor(rnd()*8),m=Math.floor(rnd()*60);
    const ts=new Date(now.getFullYear(),now.getMonth(),now.getDate(),h,m).getTime();
    const q1=1+Math.floor(rnd()*4);
    const lines=[{pid:['p1','p1','p2','p3'][Math.floor(rnd()*4)],qty:q1}];
    if(rnd()<.5)lines.push({pid:'p4',qty:1});
    if(rnd()<.6)lines.push({pid:['s1','s2','s3','s4','s5','s6'][Math.floor(rnd()*6)],qty:1+Math.floor(rnd()*3)});
    if(rnd()<.4)lines.push({pid:'b1',qty:Math.min(q1,3)});
    const c={lines,disc:{t:'pct',v:0},clientId:rnd()<.25?S.clients[Math.floor(rnd()*S.clients.length)].id:null,slotDate:d0,slotM:h*60};
    const T=totals(c);const x=rnd();
    const pays=x<.6?[{m:'card',amt:T.total}]:x<.85?[{m:'cash',amt:T.total,given:T.total}]:[{m:'ancv',amt:T.total}];
    list.push(finalize(c,pays,ts,true));
  }
  list.sort((a,b)=>a.ts-b.ts);
  return list;
}
function init(){
  let st=null,raw=msBoot();try{st=JSON.parse(raw||'null')}catch(e){msCorrupt(raw)}
  if(st&&st.products){S=st;S.settings=Object.assign(defaultSettings(),S.settings);if(S.seedDay!==today()&&!cloudOn()&&!S.noDemo&&S.sales.every(s=>s.demo)){S.sales=seedSales();S.events=seedEvents();S.seedDay=today();S.closures=[];save()}}
  else{S={products:seedProducts(),clients:seedClients(),sales:[],closures:[],settings:defaultSettings(),seedDay:today()};
    S.sales=seedSales();number();save()}
  number();
  if(!S.staff){S.events=seedEvents();S.mails=[];S.staff=seedStaff();S.leaves=seedLeaves();S.shifts={};S.checks=seedChecks();seedShifts();save()}
  S.shifts=S.shifts||{};S.events=S.events||[];S.mails=S.mails||[];
  if(!S.plans){S.staff=seedStaff();S.plans=seedPlans();save()}
  S.monthly=S.monthly||{};S.maint=S.maint||[];S.incidents=S.incidents||[];
  S.profiles=S.profiles||defaultProfiles();
}
function number(){let k=0;S.sales.forEach(s=>{if(s.h||s.qw)return;s.no=(s.demo?'D-':'T-')+String(++k).padStart(4,'0')})}
function newCart(){const n=new Date(),h=n.getHours();return{lines:[],disc:{t:'pct',v:0},clientId:null,rewardPal:null,event:null,slotDate:today(),slotM:nextQ()}}

/* ---------- calculs ---------- */
const prod=id=>S.products.find(p=>p.id===id);
function totalsBase(c){
  let sub=0,items=0,jumpers=0,dur=0;
  const L=c.lines.map(l=>{const p=prod(l.pid);const t=p.price*l.qty;sub+=t;items+=l.qty;if(p.jumper){jumpers+=l.qty;dur=Math.max(dur,p.dur||60)}return{...l,p,t}});
  const promo=c.disc.t==='pct'?Math.round(sub*c.disc.v/100):Math.min(sub,c.disc.v*100);
  const rw=rewardOf(c),rwAmt=rw?Math.min(rw.amt,sub-promo):0;
  const disc=promo+rwAmt;
  return{L,sub,items,jumpers,dur,disc,promo,rwAmt,total:sub-disc};
}
function finalizeBase(c,pays,ts,demo){
  const T=totals(c);const vat={};
  const lines=T.L.map(l=>{
    const sh=T.sub?Math.round(l.t*T.total/T.sub):0;
    const v=sh-Math.round(sh/(1+l.p.tva/100));
    (vat[l.p.tva]=vat[l.p.tva]||{ttc:0,tva:0});vat[l.p.tva].ttc+=sh;vat[l.p.tva].tva+=v;
    return{pid:l.pid,name:l.p.name,qty:l.qty,price:l.p.price,rate:l.p.tva,cat:l.p.cat,jumper:!!l.p.jumper,ttc:sh};
  });
  const slot=T.jumpers>0&&c.slotM!=null?c.slotDate+'|'+c.slotM:null;
  return{id:uid(),ts,lines,sub:T.sub,disc:T.disc,discLabel:discLabel(c),total:T.total,vat,pay:pays,clientId:c.clientId,rewardPal:c.rewardPal||null,event:c.event||null,slot,dur:T.dur,jumpers:T.jumpers,demo:!!demo};
}
function baseBooked(date,h){if(S.noDemo)return 0;
  const d=new Date(date+'T12:00'),we=d.getDay()===0||d.getDay()===6;
  const prof=[.15,.35,.6,.8,.95,.9,.7,.45,.25][Math.max(0,Math.min(8,Math.round((h-S.settings.open)/Math.max(1,S.settings.close-S.settings.open)*8)))];
  const j=Math.abs(Math.sin(h*12.9898+d.getDate()*78.233+d.getMonth()*3.1)*43758.5453)%1;
  return Math.min(S.settings.cap,Math.round(S.settings.cap*prof*(we?1:.55)*(.75+.35*j)));
}
function bookedOld(date,h){
  const key=date+'|'+h;
  return Math.min(S.settings.cap,baseBooked(date,h)+S.sales.filter(s=>s.slot===key).reduce((a,s)=>a+s.jumpers,0));
}
