/* ---------- caisse ---------- */
function vCaisse(m){
  m.innerHTML=head('Caisse',ctrlPill())+`<div class="pos"><section>
    <div class="search">${ic('search')}<input id="q" type="search" placeholder="Rechercher un produit" autocomplete="off" value="${esc(q)}"></div>
    <div class="chips" id="chips"></div><div class="chips sub" id="subchips" hidden></div><div class="grid" id="grid"></div><div class="cbar" id="cbar"></div></section>
    <aside class="cart" id="cart" aria-label="Ticket en cours"></aside></div>`;
  drawChips();drawGrid();drawCart();
}
function drawChipsOld(){
  const all=[...CATS];
  $('#chips').innerHTML=all.map(c=>`<button class="chip ${fcat===c.id?'on':''}" data-act="fcat" data-id="${c.id}">${c.name}</button>`).join('');
}
function drawGrid(){
  const nq=norm(q);
  const list=S.products.filter(p=>p.active&&(nq||fcat==='all'||p.cat===fcat)&&(nq||!fsub||p.scat===fsub)&&(!nq||norm(p.name).includes(nq)));
  $('#grid').innerHTML=list.length?list.map(p=>{
    const c=cat(p.cat),n=(cart.lines.find(l=>l.pid===p.id)||{}).qty||0;
    return `<button class="tile" data-act="add" data-id="${p.id}" style="--cat:var(${c.v})">${n?`<span class="badge">${n}</span>`:''}
      ${art(p)}<span class="n">${esc(p.name)}</span><span class="p num">${eur(p.price)}</span></button>`}).join(''):`<div class="empty" style="grid-column:1/-1">Aucun produit trouvé.</div>`;
}
function slotCheck(T){
  if(T.jumpers>0&&cart.slotM!=null){const left=leftFor(cart.slotDate,cart.slotM,T.dur);if(T.jumpers>left)return left}
  return null;
}
function drawCartOld(){
  const T=totals(cart),left=slotCheck(T);
  const cl=cart.clientId?clientName(cart.clientId):'';
  let slotHtml='';
  if(T.jumpers>0){
    const opts=HOURS.map(h=>{const r=S.settings.cap-booked(cart.slotDate,h);
      return `<option value="${h}" ${cart.slotH===h?'selected':''} ${r<=0?'disabled':''}>${pad(h)}:00 – ${pad(h+1)}:00 · ${r<=0?'complet':r+' places'}</option>`}).join('');
    slotHtml=`<div class="slotrow"><span class="lbl">Créneau (${T.jumpers} ${NOUN()}${T.jumpers>1?'s':''})</span>
      <button class="ix" data-act="cday" data-d="-1" aria-label="Jour précédent" ${cart.slotDate<=today()?'disabled':''}>${ic('left')}</button>
      <select id="slotsel" aria-label="Créneau"><option value="" ${cart.slotH==null?'selected':''}>Entrée immédiate, sans créneau</option>${opts}</select>
      <button class="ix" data-act="cday" data-d="1" aria-label="Jour suivant">${ic('right')}</button>
      <span class="muted" style="grid-column:1/-1;font-size:13px">${cart.slotDate===today()?'Aujourd’hui':dshort(cart.slotDate)}</span></div>
      ${left!=null?`<p class="warn-t">Créneau presque plein : il reste ${left} place${left>1?'s':''}. Choisissez un autre créneau.</p>`:''}`;
  }
  const discs=[['pct',0,'Aucune'],...S.settings.discPct.map(v=>['pct',v,v+' %']),['eur',5,'5 €']];
  $('#cart').innerHTML=`<div class="cart-h"><h2>Ticket en cours</h2><div style="display:flex;gap:6px">
      ${cart.lines.length?`<button class="btn" data-act="clear" style="min-height:40px;padding:6px 12px">Vider</button>`:''}
      <button class="ix only-m" data-act="closecart" aria-label="Fermer le ticket">${ic('x')}</button></div></div>
    <div class="sec"><button class="pick ${cl?'set':''}" data-act="pickclient">${ic('user')}<span class="grow">${cl?esc(cl):'Ajouter un client'}</span>${cl?`<span data-act="noclient" role="button" aria-label="Retirer le client" style="display:grid;place-items:center;width:28px;height:28px">${ic('x')}</span>`:''}</button>${slotHtml}</div>
    <div class="lines">${T.L.length?T.L.map(l=>`<div class="ln"><div><div class="nm">${esc(l.p.name)}</div><div class="u num">${eur(l.p.price)}</div></div>
      <div class="step"><button data-act="qty" data-id="${l.pid}" data-d="-1" aria-label="Retirer un">${ic('minus')}</button><b class="num">${l.qty}</b><button data-act="qty" data-id="${l.pid}" data-d="1" aria-label="Ajouter un">${ic('plus')}</button></div>
      <div class="t num">${eur(l.t)}</div></div>`).join(''):`<div class="cart-empty">Touchez un produit pour l’ajouter au ticket.</div>`}</div>
    <div class="tot">${T.L.length?`<button class="linkbtn" data-act="tdisc">${showDisc||cart.disc.v?'Masquer les remises':'Ajouter une remise'}</button>`:''}${T.L.length&&(showDisc||cart.disc.v)?`<div class="disc" role="group" aria-label="Remise">${discs.map(([t,v,l])=>`<button class="chip ${cart.disc.t===t&&cart.disc.v===v?'on':''}" data-act="disc" data-t="${t}" data-v="${v}">${l}</button>`).join('')}</div>`:''}
      ${T.disc?`<div class="r"><span>Sous-total</span><span class="num">${eur(T.sub)}</span></div><div class="r"><span>Remise</span><span class="num">− ${eur(T.disc)}</span></div>`:''}
      <div class="r big"><span>Total</span><span class="num">${eur(T.total)}</span></div>
      ${T.jumpers>0&&!slotOk(T)?'<p class="warn-t">Choisissez un créneau valide pour encaisser.</p>':''}<button class="btn-pay" data-act="pay" ${(!T.total&&!(T.L.length&&(T.pInfo||T.pcInfo)))||!slotOk(T)?'disabled':''}>${T.total?'Encaisser '+eur(T.total):(T.pInfo||T.pcInfo)?'Valider · 0,00 €':'Encaisser'}</button></div>`;
  const bar=$('#cartbar');
  bar.innerHTML=T.items?`<span>${T.items} article${T.items>1?'s':''} · Voir le ticket</span><strong class="num">${eur(T.total)}</strong>`:`<span>Ticket vide</span><strong>${eur(0)}</strong>`;
}
function addToCart(id){
  const l=cart.lines.find(l=>l.pid===id);if(l)l.qty++;else cart.lines.push({pid:id,qty:1});
  drawCart();drawGrid();
}

/* ---------- encaissement ---------- */
function openPayBase(){
  const T=totals(cart);if(!T.total||!slotOk(T))return;
  pay={list:[]};document.body.classList.remove('cart-open');renderPay();
}
const paid=()=>pay.list.reduce((a,p)=>a+p.amt,0);
function renderPayOld(){
  const T=totals(cart);
  const row=(p,i)=>`<div class="prow"><span class="pm">${METHODS[p.m]}</span>
    <input inputmode="decimal" data-pay="${i}" value="${inEur(p.amt)}" aria-label="Montant ${METHODS[p.m]}">
    <button class="ix" data-act="rmpay" data-i="${i}" aria-label="Retirer">${ic('x')}</button>
    ${p.m==='cash'?`<div class="given"><span>Reçu :</span><button class="chip ${p.given==null?'on':''}" data-act="given" data-i="${i}" data-v="">Exact</button>
      ${[10,20,50,100].map(v=>`<button class="chip ${p.given===v*100?'on':''}" data-act="given" data-i="${i}" data-v="${v}">${v} €</button>`).join('')}</div>`:''}</div>`;
  showModal(`${mh('Encaisser')}<div class="due"><span>Total à payer</span><strong class="num">${eur(T.total)}</strong></div>
    <div class="methods">${Object.entries(METHODS).map(([k,v])=>`<button class="meth" data-act="addpay" data-m="${k}">${ic(k==='cash'?'cash':k==='card'?'card':'ticket')}<span>${v}</span></button>`).join('')}</div>
    <div>${pay.list.length?pay.list.map(row).join(''):'<p class="muted">Choisissez un moyen de paiement. Vous pouvez en cumuler plusieurs.</p>'}</div>
    <div class="sum" id="paysum"></div><button class="btn-pay" id="payok" data-act="confirm" disabled>Valider l’encaissement</button>`);
  updatePay();
}
function payState(){
  const T=totals(cart),rem=T.total-paid();
  const change=pay.list.reduce((a,p)=>a+(p.m==='cash'?Math.max(0,(p.given??p.amt)-p.amt):0),0);
  const bad=pay.list.some(p=>p.amt<=0||(p.m==='cash'&&p.given!=null&&p.given<p.amt));
  return{T,rem,change,ok:rem===0&&!bad&&pay.list.length>0};
}
function updatePayOld(){
  const s=payState();
  $('#paysum').innerHTML=`<div class="r"><span>Déjà réglé</span><span class="num">${eur(paid())}</span></div>
    <div class="r k"><span>${s.rem>=0?'Reste à payer':'Trop perçu'}</span><span class="num">${eur(Math.abs(s.rem))}</span></div>
    ${s.change?`<div class="r k" style="color:var(--ok)"><span>Rendu monnaie</span><span class="num">${eur(s.change)}</span></div>`:''}`;
  $('#payok').disabled=!s.ok;
}
function confirmPay(){
  const s=payState();if(!s.ok)return;
  const pays=pay.list.map(p=>({m:p.m,amt:p.amt,...(p.m==='cash'?{given:p.given??p.amt}:{}),...(p.code?{code:p.code}:{})}));
  const sale=finalize(cart,pays,Date.now(),false);sale.change=s.change;
  S.sales.push(cfSeal(sale));number();giftUse(sale);afterSale(sale,cart);save();cart=newCart();
  showReceipt(sale,true);
  if(view==='caisse'){drawCart();drawGrid()}
}
function showReceiptBase(s,isNew){
  const cn=clientName(s.clientId);
  showModal(`${mh(isNew?'Vente enregistrée':'Ticket '+s.no)}
    ${isNew?`<div class="success">${ic('check')}<span>${eur(s.total)} encaissés${s.change?' · rendu '+eur(s.change):''}${s.pts?' · +'+s.pts+' points':''}</span></div>`:''}
    <div class="receipt">${S.settings.logo?`<img class="logo-r" src="${S.settings.logo}" alt="">`:''}<div class="c"><b>${esc(S.settings.name)}</b></div><div class="c">${s.no} · ${new Date(s.ts).toLocaleDateString('fr-FR')} ${hm(s.ts)}</div>
    ${cn?`<div class="c">Client : ${esc(cn)}</div>`:''}${slotLine(s)}<hr>
    ${s.lines.map(l=>`<div class="r"><span>${l.qty} × ${esc(l.name)}</span><span>${eur(l.price*l.qty)}</span></div>`).join('')}<hr>
    ${s.disc?`<div class="r"><span>Remise ${s.discLabel}</span><span>− ${eur(s.disc)}</span></div>`:''}
    <div class="r"><b>TOTAL TTC</b><b>${eur(s.total)}</b></div>
    ${Object.entries(s.vat).map(([r,v])=>`<div class="r"><span>dont TVA ${r} %</span><span>${eur(v.tva)}</span></div>`).join('')}<hr>
    ${s.pay.map(p=>`<div class="r"><span>${METHODS[p.m]}</span><span>${eur(p.amt)}</span></div>`).join('')}${S.settings.ticketMsg?`<hr><div class="c">${esc(S.settings.ticketMsg)}</div>`:''}</div>
    <button class="btn primary" data-act="close">${isNew?'Nouvelle vente':'Fermer'}</button>`);
}

