/* ---------- planning clients façon Qweekle : grille horaire par colonnes ---------- */
const RH=26;
const wdS=d=>new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short'}).replace('.','');
function layoutBlocks(items){
  items.sort((a,b)=>a.s-b.s||b.e-a.e);
  let cl=[],cend=0;
  const flush=()=>{const ls=[];cl.forEach(it=>{let i=ls.findIndex(e=>e<=it.s);if(i<0){i=ls.length;ls.push(0)}ls[i]=it.e;it.lane=i});cl.forEach(it=>it.n=ls.length);cl=[]};
  items.forEach(it=>{if(cl.length&&it.s>=cend){flush();cend=0}cl.push(it);cend=Math.max(cend,it.e)});
  flush();return items;
}
function drawChips(){
  const all=[...CATS];
  $('#chips').innerHTML=all.map(c=>`<button class="cat ${fcat===c.id?'on':''}" style="--cat:var(${c.v||'--ink'})" data-act="fcat" data-id="${c.id}">${c.name}</button>`).join('');
  drawSubs();
}
/* ---------- planning staff façon feuille « Vacances de la Toussaint » ---------- */
const DAYN=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
const PSL=['10h-12h','12h-14h','14h-16h','16h-18h','18h-20h','20h-22h','22h-00h'];
const PCOL=['#FF2D2D','#FFE600','#18E018','#FF9A00','#4A86E8','#FF00FF','#351C75','#46BDC6'];
const scolBase=s=>s.color||PCOL[Math.max(0,S.staff.indexOf(s))%PCOL.length];
const inkOn=c=>{const n=parseInt(String(c).slice(1),16);if(!isFinite(n))return '#FFFFFF';const f=v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)},l=.2126*f(n>>16)+.7152*f(n>>8&255)+.0722*f(n&255);return (l+.05)/(.0147+.05)>1.05/(l+.05)?'#0A1F4D':'#FFFFFF'};
const fname=s=>s.name.split(' ')[0];
function seedStaff(){
  const P=(id,n,r,c)=>({id,name:n,role:r,color:c});
  return [P('e1','Hugo','resp',PCOL[0]),P('e2','Sarah','mon',PCOL[1]),P('e3','Johan','mon',PCOL[2]),P('e4','Louis','mon',PCOL[3]),P('e5','Lilou','mon',PCOL[4]),P('e6','Nana','mon',PCOL[5]),P('e7','Brice','mon',PCOL[6]),P('e8','Matteo','mon',PCOL[7])];
}
const TOUS=[
  ['1,5','1,5','0,1,3,5,6','0,1,3,5,6','0,1,6'],
  ['1,5','1,5','0,1,4,5,6','0,1,4,5,6','0,6'],
  ['g0,2,5','g0,2,5','0,2,4,5,7','0,2,4,5,7','0,4,7'],
  ['g0,2,4','g0,2,4','0,2,3,4,5','0,2,3,4,5','0,3,5'],
  ['2,7','2,7','0,2,3,6,7','0,2,3,6,7','0,2,3,6','3,6','3,6'],
  ['1,2','1,2','1,2,3,4,5,6','1,2,3,4,5,6','2,3,4','3,4,7','3,4,7'],
  ['1,6','1,6','1,3,4,6,7','1,3,4,6,7','1,4,7']];
function buildPlan(id,name,from,to,base){
  const ids=S.staff.map(s=>s.id),cells={},rows={};
  TOUS.forEach((day,d)=>{cells[d]={};rows[d]=day.length;day.forEach((r,i)=>{cells[d][i]={};r.split(',').forEach(t=>{const g=t[0]==='g',k=ids[+(g?t.slice(1):t)];if(k)cells[d][i][k]=g?'g':'w'})})});
  return{id,name,from,to,base:!!base,rows,cells};
}
function seedPlans(){return[buildPlan('p1','Vacances de la Toussaint 2026','2026-10-19','2026-11-02',false),buildPlan('p0','Semaine type','','',true)]}
const planFor=ds=>S.plans.find(p=>p.from&&ds>=p.from&&ds<=p.to)||S.plans.find(p=>p.base)||S.plans[0];
const dowOf=ds=>(new Date(ds+'T12:00').getDay()+6)%7;
const nrows=(p,d)=>p.rows[d]||5;
function cellsOfBase(p,ds,id){const d=p.cells[dowOf(ds)]||{},n=nrows(p,dowOf(ds)),o=[];Object.keys(d).forEach(i=>{if(+i<n&&d[i][id])o.push([+i,d[i][id]])});return o}
function shiftOf(ds,id){if(onLeave(id,ds))return'L';return cellsOf(planFor(ds),ds,id).length?'J':'R'}
function staffAtBase(ds,h){const p=planFor(ds),d=dowOf(ds),c=(p.cells[d]||{})[Math.floor((h-10)/2)]||{};return Math.floor((h-10)/2)<nrows(p,d)?S.staff.filter(s=>c[s.id]==='w'&&!onLeave(s.id,ds)):[]}
function shiftLabel(ds,id){const c=cellsOf(planFor(ds),ds,id);if(!c.length)return'';const a=Math.min(...c.map(x=>x[0])),b=Math.max(...c.map(x=>x[0])),e=12+2*b;return(10+2*a)+'h–'+(e>=24?'00':e)+'h'}
function planHours(p,id){let w=0,g=0;Object.entries(p.cells).forEach(([d,rows])=>Object.entries(rows).forEach(([i,c])=>{if(+i<nrows(p,d)){if(c[id]==='w')w+=2;else if(c[id]==='g')g+=2}}));return{w,g}}
const prange=p=>p.from?'Du '+new Date(p.from+'T12:00').toLocaleDateString('fr-FR',{day:'numeric',month:'long'})+' au '+new Date(p.to+'T12:00').toLocaleDateString('fr-FR',{day:'numeric',month:'long'}):'Appliquée en dehors des périodes spéciales';
let planSel=null;
function curPlan(){let p=S.plans.find(x=>x.id===planSel);if(!p){p=S.plans.find(x=>x.base)||planFor(today());planSel=p.id}return p}
function dayCard(p,d,ds){
  const n=nrows(p,d),dc=ds?swDayCells(p,d,ds):(p.cells[d]||{}),ro=!isAdmin();
  const head=visStaff().map(s=>`<th class="${ds&&onLeave(s.id,ds)?'lv':''}"><span>${esc(fname(s))}</span><i style="background:${scol(s)}"></i></th>`).join('');
  const body=Array.from({length:n},(_,i)=>{const c=dc[i]||{},cnt=S.staff.filter(s=>c[s.id]==='w'&&!(ds&&onLeave(s.id,ds))).length;
    return `<tr><th class="slc">${PSL[i]}</th>${visStaff().map(s=>{const v=c[s.id]||'',lv=ds&&onLeave(s.id,ds);
      return `<td><button class="pc ${v} ${lv?'off':''} ${ro?'ro':''}" style="--c:${scol(s)}${plFill(p,d,ds,i,s.id,v)}" data-act="pcell" data-d="${d}" data-i="${i}" data-s="${s.id}" ${lv?'disabled':''} ${ro?'tabindex="-1"':''} aria-label="${esc(fname(s))}, ${DAYN[d]} ${PSL[i]} : ${v==='w'?'présent':v==='g'?'gestion':'libre'}">${plTxt(p,d,ds,i,s.id,v)}</button></td>`}).join('')}<td class="cv"><span class="pill ${cnt<MIN_STAFF?'bad':cnt===MIN_STAFF?'warn':'ok'}">${cnt}</span></td></tr>`}).join('');
  return `<div class="card dcard"><div class="dch"><h3>${DAYN[d]}</h3><span class="plbar">${plBtn(p,d,ro)}${ro?(n>5?'<span class="late">Nocturne jusqu’à minuit</span>':''):`<label class="late"><input type="checkbox" data-plate="${d}" ${n>5?'checked':''}> Nocturne jusqu’à minuit</label>`}</span></div>
    <div class="dtw"><table class="dt"><thead><tr><th></th>${head}<th class="cv">Équipe</th></tr></thead><tbody>${body}</tbody></table></div>${plNotes(p,d,ds,dc)}</div>`;
}
function vTeam(m){
  const p=curPlan();
  const chips=plOrder().map(x=>`<button class="chip ${x.id===p.id?'on':''}" data-act="planset" data-id="${x.id}">${esc(x.name)}</button>`).join('');
  const tot=visStaff().map(s=>{const h=planHours(p,s.id),c=scol(s);return `<div class="tt" style="background:${c};color:${inkOn(c)}"><small>${esc(fname(s))}</small><b class="num">${plHF(h.w)}</b>${h.g?`<em>+ ${plHF(h.g)} gestion</em>`:''}</div>`}).join('');
  const low=[];for(let d=0;d<7;d++)for(let i=0;i<nrows(p,d);i++){const c=(p.cells[d]||{})[i]||{};if(S.staff.filter(s=>c[s.id]==='w').length<MIN_STAFF)low.push(DAYN[d].slice(0,3)+' '+PSL[i])}
  m.innerHTML=`<div class="plan-h"><div><h2 class="plan-t">${esc(p.name)}</h2><p class="muted">${prange(p)}</p></div>
     <div class="plact"><button class="btn" data-act="planpdf">PDF</button>${isAdmin()?`<button class="btn" data-act="planarch">Sauvegardes</button><button class="btn" data-act="planedit" data-id="${p.id}">Modifier</button><button class="btn primary" data-act="plannew">${ic('plus')}Nouveau planning</button>`:`<span class="pill">Consultation seule</span>`}</div></div>
    <div class="chips" style="margin-bottom:12px">${chips}</div>
    ${low.length?`<div class="banner"><span>${low.length} créneau${low.length>1?'x':''} sous le minimum de ${MIN_STAFF} personnes (${low.slice(0,4).join(', ')}${low.length>4?'…':''}).</span></div>`:`<div class="banner ok"><span>Tous les créneaux respectent le minimum de ${MIN_STAFF} personnes.</span></div>`}
    <div class="dgrid">${[0,1,2,3,4,5,6].map(d=>dayCard(p,d,null)).join('')}</div>
    <div class="card" style="margin-top:14px"><h3>Total des heures par semaine</h3><div class="tts">${tot}</div><p class="muted" style="margin-top:12px">CP : <b>${CP_TOTAL}</b> jours par personne${isAdmin()?' · Touchez une case pour la remplir : <b>présent</b>, puis <b>gestion</b>, puis vide.':' · Seul l’administrateur peut modifier le planning.'}</p></div>`;
}
function vStaffDay(m){
  if(slotDay<today())slotDay=today();
  const ds=slotDay,p=planFor(ds),d=dowOf(ds),duty=onDuty(ds),lv=visStaff().filter(s=>onLeave(s.id,ds));
  const hrs=duty.reduce((a,s)=>a+plDayH(ds,s.id).w,0);
  const low=[];for(let i=0;i<nrows(p,d);i++){const c=(p.cells[d]||{})[i]||{};if(S.staff.filter(s=>c[s.id]==='w'&&!onLeave(s.id,ds)).length<MIN_STAFF)low.push(PSL[i])}
  m.innerHTML=dayChips(ds)+`<div class="pst" style="margin-bottom:12px"><span><b class="num">${duty.length}</b> en poste</span><span><b class="num">${plHn(hrs)}</b> h planifiées</span><span><b class="num">${lv.length}</b> en congé</span><span>${esc(p.name)}</span></div>
    ${ds===today()?poCard('plan'):''}
    ${low.length?`<div class="banner"><span>Moins de ${MIN_STAFF} personnes sur : ${low.join(', ')}.</span><button class="btn" data-act="tab" data-id="equipe">Ouvrir le planning</button></div>`:`<div class="banner ok"><span>Équipe suffisante sur toute la journée.</span></div>`}
    <div class="dgrid one">${dayCard(p,d,ds)}</div>
    ${lv.length?`<div class="card" style="margin-top:14px"><h3>En congé payé</h3>${lv.map(s=>`<div class="row"><span class="avatar" style="background:${scol(s)};color:${inkOn(scol(s))}">${esc(initials(s.name))}</span><span class="grow"><b>${esc(s.name)}</b></span></div>`).join('')}</div>`:''}`;
}
function planForm(p,isNew){
  showModal(`${mh(isNew?'Nouveau planning':'Modifier le planning')}<form id="pform" data-plan="1" data-id="${p.id}"><div class="field"><label for="pn">Nom</label><input id="pn" value="${esc(p.name)}" required></div>
    ${p.base?`<p class="muted" style="margin-bottom:12px">Cette semaine type s’applique en dehors des périodes spéciales.</p>`:`<div class="two"><div class="field"><label for="pf">Du</label><input id="pf" type="date" value="${p.from}" required></div><div class="field"><label for="pt">Au</label><input id="pt" type="date" value="${p.to}" required></div></div>`}
    <button class="btn primary" type="submit" style="width:100%">Enregistrer</button>
    ${!p.base&&!isNew?`<button class="btn danger" type="button" data-act="plandel" data-id="${p.id}" style="width:100%;margin-top:8px">Supprimer ce planning</button>`:''}</form>`);
}
const redrawStaff=()=>{(tab.staff==='equipe'?vTeam:vStaffDay)($('#sub'))};
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,d=b.dataset;
  if(['pcell','planedit','plannew','plandel'].includes(a)&&!isAdmin()){toast('Réservé à l’administrateur');return}
  if(a==='pcell'){const p=curPlan(),dd=+d.d,i=+d.i;p.cells[dd]=p.cells[dd]||{};p.cells[dd][i]=p.cells[dd][i]||{};const c=p.cells[dd][i],v=c[d.s];
    if(!v)c[d.s]='w';else if(v==='w')c[d.s]='g';else delete c[d.s];save();redrawStaff()}
  else if(a==='planset'){planSel=d.id;vTeam($('#sub'))}
  else if(a==='planedit')planForm(S.plans.find(x=>x.id===d.id),false);
  else if(a==='plannew'){const src=curPlan(),np=JSON.parse(JSON.stringify(src));np.id=uid();np.name='Nouveau planning';np.base=false;np.from=addDays(today(),0);np.to=addDays(today(),13);S.plans.push(np);planSel=np.id;save();planForm(np,true);vTeam($('#sub'))}
  else if(a==='plandel'){S.plans=S.plans.filter(x=>x.id!==d.id);planSel=null;save();closeModal();vTeam($('#sub'));toast('Planning supprimé')}
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='pform'||!e.target.dataset.plan)return;e.preventDefault();
  const p=S.plans.find(x=>x.id===e.target.dataset.id);if(!p||!isAdmin())return;
  p.name=$('#pn').value.trim()||p.name;if(!p.base){const f=$('#pf').value,t=$('#pt').value;if(f&&t&&t>=f){p.from=f;p.to=t}}
  save();closeModal();vTeam($('#sub'));toast('Planning enregistré');
});
document.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset&&t.dataset.plate!==undefined){if(!isAdmin())return;const p=curPlan(),d=+t.dataset.plate;p.rows[d]=t.checked?7:5;save();redrawStaff()}
  else if(t.dataset&&t.dataset.scolor){const s=S.staff.find(x=>x.id===t.dataset.scolor);if(s){s.color=t.value.toUpperCase();save();toast('Couleur de '+fname(s)+' enregistrée')}}
});

/* ---------- rôles : administrateur / opérateur ---------- */
const RKEY='lago-role';
let ROLEMODE='admin';try{ROLEMODE=localStorage.getItem(RKEY)||'admin'}catch(e){}
const isAdmin=()=>ROLEMODE==='admin';
function setRole(r){ROLEMODE=r;try{localStorage.setItem(RKEY,r)}catch(e){}}
const rolePillOld=()=>`<button class="rolepill ${isAdmin()?'adm':''}" data-act="rolesw" aria-label="Changer de mode">${ic(isAdmin()?'shield':'users')}${isAdmin()?'Administrateur':'Opérateur'}</button>`;
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="rolesw_old"]');if(!b)return;
  if(isAdmin()){setRole('operator');chrome();render();toast('Mode opérateur : consultation des plannings')}
  else showModal(`${mh('Mode administrateur')}<form id="pinform"><div class="field"><label for="pinin">Code administrateur</label><input id="pinin" type="password" inputmode="numeric" autocomplete="off"></div><p id="pinerr" style="color:var(--bad);min-height:22px;font-weight:600"></p><button class="btn primary" type="submit" style="width:100%">Passer en administrateur</button><p class="muted" style="margin-top:10px;font-size:13px">Code de démonstration : 1234. Modifiable dans Paramètres, Équipe.</p></form>`);
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='pinform')return;e.preventDefault();
  if($('#pinin').value===(S.settings.pin||'1234')){setRole('admin');chrome();render();toast('Mode administrateur')}
  else{$('#pinerr').textContent='Code incorrect.';$('#pinin').value='';$('#pinin').focus()}
});
document.addEventListener('change',e=>{if(e.target.id==='pinset'){const v=e.target.value.trim();if(v.length>=4){S.settings.pin=v;save();toast('Code administrateur enregistré')}else{e.target.value=S.settings.pin||'1234';toast('Le code doit avoir au moins 4 caractères')}}});

/* ---------- planning clients : dalles de 15 minutes ---------- */
let planMode='timeline';
const modeSeg=()=>`<div class="seg"><button class="${planMode==='timeline'?'on':''}" data-act="vmode" data-k="timeline">Timeline</button><button class="${planMode==='dalles'?'on':''}" data-act="vmode" data-k="dalles">Dalles</button></div>`;
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="vmode"]');if(b){planMode=b.dataset.k==='dalles'?'dalles':'timeline';vDay($('#sub'))}});
const SAT=[[0,[232,241,255]],[.3,[255,240,205]],[.6,[255,184,120]],[.85,[240,92,80]],[1,[196,28,40]]];
function satStyle(p){
  p=Math.max(0,Math.min(1,p));let a=SAT[0],b=SAT[SAT.length-1];
  for(let i=0;i<SAT.length-1;i++)if(p>=SAT[i][0]&&p<=SAT[i+1][0]){a=SAT[i];b=SAT[i+1];break}
  const t=b[0]===a[0]?0:(p-a[0])/(b[0]-a[0]),c=a[1].map((v,i)=>Math.round(v+(b[1][i]-v)*t));
  const lum=(c[0]*299+c[1]*587+c[2]*114)/1000;
  return[`rgb(${c})`,lum>150?'#0A1F4D':'#FFFFFF'];
}
function dayStrip(ds){
  const cap=S.settings.cap;
  return `<div class="dys">${Array.from({length:14},(_,i)=>addDays(today(),i)).map((d,i)=>{
    const pk=Math.max(...QS.map(q=>occ(d,q))),pc=Math.min(100,Math.round(pk/cap*100)),ne=evOn(d).length;
    return `<button class="dy ${d===ds?'on':''}" data-act="day" data-d="${d}"><small>${i===0?'Auj.':wdS(d)}</small><b class="num">${+d.slice(8,10)}</b><i class="dybar"><u class="${pc>=100?'full':pc>=80?'warn':''}" style="width:${pc}%"></u></i><small>${pc} %${ne?' · '+ne+' év.':''}</small></button>`}).join('')}</div>`;
}
function vDay(m){
  if(planMode==='timeline')return vTimeline(m);
  if(slotDay<today())slotDay=today();
  const ds=slotDay,cap=S.settings.cap,isT=ds===today(),nm=nowMin(),nowQ=isT?Math.floor(nm/15)*15:-1;
  const occs=QS.map(q=>occ(ds,q)),peak=Math.max(...occs),pk=QS[occs.indexOf(peak)];
  const cur=isT&&nm>=QSTART&&nm<QEND+15?occ(ds,nowQ):null;
  const sales=S.sales.filter(s=>s.slot&&s.slot.startsWith(ds)),evs=evOn(ds);
  const starts={};sales.forEach(s=>{const q=+s.slot.split('|')[1],x=starts[q]=starts[q]||{n:0,j:0};x.n++;x.j+=s.jumpers});
  evs.forEach(ev=>{const x=starts[ev.h*60]=starts[ev.h*60]||{n:0,j:0};x.n++;x.j+=ev.guests});
  const hours=[...new Set(QS.map(q=>Math.floor(q/60)))];
  const rows=hours.map(h=>`<div class="hrow"><div class="hbl">${h}h</div><div class="tiles">${[0,15,30,45].map(o=>{const q=h*60+o,i=QS.indexOf(q);if(i<0)return '<span></span>';
    const n=occs[i],pc=n/cap,[bg,fg]=satStyle(pc),past=isT&&q+15<=nm,st=starts[q]||{n:0,j:0};
    return `<button class="dl ${q===nowQ?'cur':''} ${past?'past':''}" style="background:${bg};color:${fg}" data-act="slot" data-m="${q}" aria-label="${fm(q)} : ${n} présents sur ${cap}, ${st.n} réservation${st.n>1?'s':''} au départ"><span class="dt1 num">${fm(q)}</span><span class="pc2 num">${Math.round(pc*100)} %</span><b class="num">${n}<small> / ${cap}</small></b><span class="dt2">${st.n?st.n+' résa · '+st.j+' pers.':'Aucun départ'}</span></button>`}).join('')}</div></div>`).join('');
  const ns=Math.max(QSTART,Math.min(QEND,Math.ceil(nm/15)*15));
  m.innerHTML=dayStrip(ds)+`<div class="plbar"><div class="pst"><span><b class="num">${cur!=null?cur:cap}</b> ${cur!=null?'présents maintenant sur '+cap:'places au total'}</span><span>Pic <b class="num">${peak}</b> à ${fm(pk)}</span><span><b class="num">${sales.length}</b> réservation${sales.length>1?'s':''}</span><span><b class="num">${evs.length}</b> événement${evs.length>1?'s':''}</span></div>
    <div class="plact">${modeSeg()}<button class="btn primary" data-act="sellslot" data-m="${isT?ns:QSTART}">${ic('plus')}${tv('reserver')}</button></div></div>
    <div class="slegend"><span>Libre</span><i class="sgrad"></i><span>Complet (${cap})</span><span class="muted">Chaque dalle = 15 minutes. Touchez une dalle pour voir toutes les réservations du créneau.</span></div>
    <div class="dalles">${rows}</div>`;
}
function slotDetail(m){
  const ds=slotDay,cap=S.settings.cap,o=occ(ds,m),pc=o/cap,[bg]=satStyle(pc);
  const act=S.sales.filter(s=>s.slot&&s.slot.startsWith(ds)).map(s=>({s,st:+s.slot.split('|')[1],dur:s.dur||60})).filter(x=>x.st<=m&&m<x.st+x.dur);
  const go=act.filter(x=>x.st===m),inprog=act.filter(x=>x.st<m),pers=act.reduce((a,x)=>a+x.s.jumpers,0),other=Math.max(0,o-pers);
  const evs=evOn(ds).filter(e=>e.h*60<=m&&m<(e.h+e.dur)*60);
  const row=x=>`<button class="row rowbtn" data-act="ticket" data-id="${x.s.id}"><span class="grow"><b>${swatch(bracelet(x.st,x.dur).color)}${x.s.jumpers} ${NOUN()}${x.s.jumpers>1?'s':''} · ${x.s.clientId?esc(clientName(x.s.clientId)):'Au comptoir'}</b><span class="muted">${x.s.no} · ${fm(x.st)} à ${fm(x.st+x.dur)}</span></span><b class="num">${eur(x.s.total)}</b></button>`;
  const can=m>=QS[0],prev=QS.includes(m-15)?m-15:null,next=QS.includes(m+15)?m+15:null;
  showModal(`<div class="mh"><button class="ix" data-act="slot" data-m="${prev}" ${prev==null?'disabled':''} aria-label="Créneau précédent">${ic('left')}</button><h2 style="flex:1;text-align:center">${fm(m)} à ${fm(m+15)}</h2><button class="ix" data-act="slot" data-m="${next}" ${next==null?'disabled':''} aria-label="Créneau suivant">${ic('right')}</button><button class="ix" data-act="close" aria-label="Fermer">${ic('x')}</button></div>
   <p class="muted" style="text-transform:capitalize;margin-top:-6px">${dlong(ds)}</p>
   <div class="occbox" style="background:${bg};color:${satStyle(pc)[1]}"><div><span class="lab">Présents sur ce créneau</span><b class="num">${o}<small> / ${cap}</small></b></div><div style="text-align:right"><span class="lab">Places libres</span><b class="num">${cap-o}</b></div></div>
   <div class="grp-h">Départs à ${fm(m)} <span class="muted">· ${go.length} réservation${go.length>1?'s':''}, ${go.reduce((a,x)=>a+x.s.jumpers,0)} personne${go.reduce((a,x)=>a+x.s.jumpers,0)>1?'s':''}</span></div>
   ${go.length?go.map(row).join(''):'<p class="muted">Aucun départ en caisse sur ce créneau.</p>'}
   ${inprog.length?`<div class="grp-h">Déjà sur place <span class="muted">· ${inprog.length} réservation${inprog.length>1?'s':''}</span></div>${inprog.map(row).join('')}`:''}
   ${evs.length?`<div class="grp-h">Événements en cours</div>${evs.map(ev=>`<button class="row rowbtn" data-act="evinfo" data-id="${ev.id}"><span class="grow"><b>${esc(ev.title)}</b><span class="muted">${ROOMS[ev.room]} · ${ft(ev.h)} à ${ft(ev.h+ev.dur)}</span></span><b class="num">${ev.guests} pers.</b></button>`).join('')}`:''}
   ${other?`<div class="grp-h">Autres réservations</div><div class="row"><span class="grow"><b>Réservations en ligne et groupes</b><span class="muted">Hors ventes en caisse</span></span><b class="num">${other} pers.</b></div>`:''}
   <button class="btn primary" data-act="sellslot" data-m="${m}" ${cap-o<=0?'disabled':''} style="width:100%">Vendre sur ce départ</button>`);
}

/* ---------- style Roller : timeline par activité, panneau de créneau, menu en tuiles, recherche ---------- */
function leftFor(date,start,dur){let mx=0;for(let t=start;t<start+dur;t+=15){if(S.closed&&S.closed[date+'|'+t])return 0;mx=Math.max(mx,occ(date,t))}return S.settings.cap-mx}
function vTimeline(m){
  if(slotDay<today())slotDay=today();
  const ds=slotDay,cap=S.settings.cap,isT=ds===today(),nm=nowMin(),nowQ=isT?Math.floor(nm/15)*15:-1,N=QS.length;
  const occs=QS.map(q=>occ(ds,q)),peak=Math.max(...occs),pk=QS[occs.indexOf(peak)];
  const cur=isT&&nm>=QSTART&&nm<QEND+15?occ(ds,nowQ):null;
  const sales=S.sales.filter(s=>s.slot&&s.slot.startsWith(ds)),evs=evOn(ds);
  const starts={};sales.forEach(s=>{const q=+s.slot.split('|')[1],x=starts[q]=starts[q]||{n:0,j:0};x.n++;x.j+=s.jumpers});
  const hdr=HOURS.map(h=>`<span style="grid-column:span 4">${h}:00</span>`).join('');
  const cells=QS.map((q,i)=>{const o=occs[i],shut=(S.closed&&S.closed[ds+'|'+q])||!openAt(ds,q),[bg,fg]=satStyle(o/cap),past=isT&&q+15<=nm,st=starts[q];
    return `<button class="tc ${shut?'shut':''} ${past?'past':''} ${q===nowQ?'cur':''}" style="${shut?'':`background:${bg};color:${fg}`}" data-act="slot" data-m="${q}" aria-label="${fm(q)} : ${shut?'fermé':o+' présents sur '+cap}"><b class="num">${shut?'×':o}</b>${st&&!shut?`<small class="num">(${st.j})</small>`:''}</button>`}).join('');
  const rooms=Object.entries(ROOMS).map(([r,l])=>{const es=evs.filter(e=>e.room===r);
    return `<div class="tlrow"><div class="tll"><b>Évènement</b><span>${esc(l)}</span></div><div class="tlg ev" style="--n:${N}">${es.map(e=>{const a=Math.max(1,(e.h*60-QSTART)/15+1),b=Math.min(N+1,a+e.dur*4);return `<button class="tev ${r}" style="grid-column:${a}/${b}" data-act="evinfo" data-id="${e.id}"><b>${esc(e.title)}</b><span class="num">${e.guests} pers. · ${ft(e.h)} à ${ft(e.h+e.dur)}</span></button>`}).join('')||`<span class="tfree">Libre</span>`}</div></div>`}).join('');
  const f=(nm-QSTART)/(N*15),nowl=isT&&f>=0&&f<=1?`<i class="nowv" style="--f:${f}"></i>`:'';
  const ns=Math.max(QSTART,Math.min(QEND,Math.ceil(nm/15)*15));
  m.innerHTML=dayStrip(ds)+`<div class="plbar"><div class="pst"><span><b class="num">${cur!=null?cur:cap}</b> ${cur!=null?'présents maintenant sur '+cap:'places au total'}</span><span>Pic <b class="num">${peak}</b> à ${fm(pk)}</span><span><b class="num">${sales.length}</b> réservation${sales.length>1?'s':''}</span><span><b class="num">${evs.length}</b> événement${evs.length>1?'s':''}</span></div>
    <div class="plact">${modeSeg()}<button class="btn primary" data-act="sellslot" data-m="${isT?ns:QSTART}">${ic('plus')}${tv('reserver')}</button></div></div>
   <div class="tlw"><div class="tlr" style="--n:${N}"><div class="tlbody">
     <div class="tlrow tlhead"><div class="tll"></div><div class="tlg hh" style="--n:${N}">${hdr}</div></div>
     <div class="tlrow"><div class="tll"><b>${tv('session')}</b><span>${tv('lieu')} (${cap})</span></div><div class="tlg" style="--n:${N}">${cells}</div></div>
     ${rooms}${nowl}</div></div></div>
   <div class="slegend"><span>Libre</span><i class="sgrad"></i><span>Complet (${cap})</span><span class="muted">Un carré = 15 minutes : nombre de présents, et entre parenthèses les arrivées. Touchez un carré pour ouvrir le créneau.</span></div>`;
}
/* panneau d'un créneau */
let slotSel={},slotAt=null;
function slotDetail(m){
  if(m!==slotAt){slotSel={};slotAt=m}
  const ds=slotDay,cap=S.settings.cap,o=occ(ds,m),shut=!!(S.closed&&S.closed[ds+'|'+m])||!openAt(ds,m),isT=ds===today(),past=isT&&m+15<=nowMin(),[bg,fg]=satStyle(o/cap);
  const act=S.sales.filter(s=>s.slot&&s.slot.startsWith(ds)).map(s=>({s,st:+s.slot.split('|')[1],dur:s.dur||60})).filter(x=>x.st<=m&&m<x.st+x.dur);
  const go=act.filter(x=>x.st===m),inprog=act.filter(x=>x.st<m),pers=act.reduce((a,x)=>a+x.s.jumpers,0),other=Math.max(0,o-pers);
  const evs=evOn(ds).filter(e=>e.h*60<=m&&m<(e.h+e.dur)*60);
  const row=x=>`<button class="row rowbtn" data-act="ticket" data-id="${x.s.id}"><span class="grow"><b>${swatch(bracelet(x.st,x.dur).color)}${x.s.jumpers} ${NOUN()}${x.s.jumpers>1?'s':''} · ${x.s.clientId?esc(clientName(x.s.clientId)):'Au comptoir'}</b><span class="muted">${x.s.no} · ${fm(x.st)} à ${fm(x.st+x.dur)}</span></span><b class="num">${eur(x.s.total)}</b></button>`;
  const prods=S.products.filter(p=>p.active&&p.jumper),need=prods.reduce((a,p)=>a+(slotSel[p.id]||0),0),dur=Math.max(60,...prods.filter(p=>slotSel[p.id]).map(p=>p.dur||60)),left=leftFor(ds,m,dur);
  const prev=QS.includes(m-15)?m-15:null,next=QS.includes(m+15)?m+15:null,ng=go.reduce((a,x)=>a+x.s.jumpers,0);
  showModal(`<div class="mh"><button class="ix" data-act="slot" data-m="${prev}" ${prev==null?'disabled':''} aria-label="Créneau précédent">${ic('left')}</button><h2 style="flex:1;text-align:center">${tv('session')}</h2><button class="ix" data-act="slot" data-m="${next}" ${next==null?'disabled':''} aria-label="Créneau suivant">${ic('right')}</button><button class="ix" data-act="close" aria-label="Fermer">${ic('x')}</button></div>
   <div class="sinfo"><div><span class="lab">Début</span><b class="num">${fm(m)}</b></div><div><span class="lab">Fin</span><b class="num">${fm(m+15)}</b></div><div><span class="lab">Lieu</span><b>${tv('lieu')} (${cap})</b></div><div><span class="lab">Jour</span><b style="text-transform:capitalize">${dshort(ds)}</b></div></div>
   <div class="occbox" style="background:${shut?'#E8ECF4':bg};color:${shut?'var(--ink)':fg}"><div><span class="lab">${shut?'Créneau fermé':'Présents sur ce créneau'}</span><b class="num">${o}<small> / ${cap}</small></b></div><div style="text-align:right"><span class="lab">Places libres</span><b class="num">${shut?0:cap-o}</b></div></div>
   ${isAdmin()?`<button class="btn" data-act="slotshut" data-m="${m}" style="width:100%">${shut?'Rouvrir ce créneau':'Fermer ce créneau aux ventes'}</button>`:''}
   <div class="grp-h">Choix d’activités</div>
   <div class="atiles">${prods.map(p=>`<div class="at" style="--cat:var(${cat(p.cat).v})"><div class="atart">${art(p)}</div><b>${esc(p.name)}</b><span class="muted num">${eur(p.price)}</span><div class="step"><button data-act="sq" data-id="${p.id}" data-d="-1" aria-label="Retirer un">${ic('minus')}</button><b class="num">${slotSel[p.id]||0}</b><button data-act="sq" data-id="${p.id}" data-d="1" aria-label="Ajouter un">${ic('plus')}</button></div></div>`).join('')}</div>
   ${need>left&&!shut?`<p class="warn-t">Il ne reste que ${Math.max(0,left)} place${left>1?'s':''} sur ce créneau.</p>`:''}${shut?'<p class="warn-t">Ce créneau est fermé aux ventes.</p>':''}${past?'<p class="warn-t">Ce créneau est déjà passé.</p>':''}
   <button class="btn-pay" data-act="slotgo" data-m="${m}" ${need>0&&need<=left&&!shut&&!past?'':'disabled'}>Valider${need?' · '+need+' personne'+(need>1?'s':''):''}</button>
   <div class="grp-h">Départs à ${fm(m)} <span class="muted">· ${go.length} réservation${go.length>1?'s':''}, ${ng} personne${ng>1?'s':''}</span></div>
   ${go.length?go.map(row).join(''):'<p class="muted">Aucun départ en caisse sur ce créneau.</p>'}
   ${inprog.length?`<div class="grp-h">Déjà sur place <span class="muted">· ${inprog.length} réservation${inprog.length>1?'s':''}</span></div>${inprog.map(row).join('')}`:''}
   ${evs.length?`<div class="grp-h">Événements en cours</div>${evs.map(ev=>`<button class="row rowbtn" data-act="evinfo" data-id="${ev.id}"><span class="grow"><b>${esc(ev.title)}</b><span class="muted">${ROOMS[ev.room]} · ${ft(ev.h)} à ${ft(ev.h+ev.dur)}</span></span><b class="num">${ev.guests} pers.</b></button>`).join('')}`:''}
   ${other?`<div class="grp-h">Autres réservations</div><div class="row"><span class="grow"><b>Réservations en ligne et groupes</b><span class="muted">Hors ventes en caisse</span></span><b class="num">${other} pers.</b></div>`:''}`);
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,d=b.dataset;
  if(a==='sq'){slotSel[d.id]=Math.max(0,(slotSel[d.id]||0)+ +d.d);slotDetail(slotAt)}
  else if(a==='slotshut'){if(!isAdmin())return;S.closed=S.closed||{};const k=slotDay+'|'+d.m;if(S.closed[k])delete S.closed[k];else S.closed[k]=1;save();slotDetail(+d.m);if(view==='resa'&&tab.resa==='apercu')vDay($('#sub'))}
  else if(a==='slotgo'){const m0=+d.m;Object.entries(slotSel).forEach(([id,q])=>{for(let i=0;i<q;i++)addLineQuiet(id)});cart.slotDate=slotDay;cart.slotM=m0;slotSel={};slotAt=null;closeModal();location.hash==='#caisse'?render():location.hash='caisse'}
});
/* menu en tuiles et recherche */
const SIC={'resa:apercu':'calendar','resa:resas':'ticket','resa:events':'users','resa:bracelets':'wave','caisse:':'cash','gestion:caisse':'caisse','gestion:produits':'box','gestion:rapports':'chart','clients:fiches':'user','clients:fidelite':'ticket','clients:mailing':'wave','staff:equipe':'calendar','staff:sjour':'clock','staff:conges':'users','controle:visuel':'shield','controle:mensuel':'calendar','controle:maint':'gear','controle:ia':'wave','params:pgen':'gear','params:ppark':'home','params:pteam':'users','params:ploy':'ticket'};
const MTL=[['Réservations','calendar','resa','apercu',[['Planning','resa','apercu'],['Réservations','resa','resas'],['Événements','resa','events'],['Bracelets','resa','bracelets']]],
 ['Caisse','caisse','caisse','',[['Nouvelle vente','caisse',''],['Tiroir-caisse','gestion','caisse']]],
 ['Produits','box','gestion','produits',[['Produits','gestion','produits'],['Rapports','gestion','rapports']]],
 ['Clients','users','clients','fiches',[['Fiches','clients','fiches'],['Fidélité','clients','fidelite'],['Mailing','clients','mailing']]],
 ['Équipe','clock','staff','equipe',[['Planning','staff','equipe'],['Jour','staff','sjour'],['Congés','staff','conges']]],
 ['Contrôle','shield','controle','visuel',[['Contrôle quotidien','controle','visuel'],['Contrôle mensuel','controle','mensuel'],['Maintenance','controle','maint']]],
 ['Paramètres','gear','params','pgen',[['Général','params','pgen'],['Parc','params','ppark'],['Équipe','params','pteam'],['Fidélité','params','ploy']]]];
function homeTiles(){
  return `<div class="mtiles">${homeList().filter(t=>(isAdmin()||t[2]!=='params')&&!opHidden(t[2])).map(([l,i,v,t,sub])=>`<div class="mt ${sub.length?'has':''}${v==='controle'&&ctlTodo()?' todo':''}"><button class="mt-main" data-act="goto" data-v="${v}" data-t="${t}"><span class="mt-ic">${ic(i)}</span><span>${l}</span>${v==='controle'&&ctlTodo()?'<em class="mt-todo">À faire</em>':''}</button>${sub.length?`<div class="mt-sub">${sub.filter(x=>subOk(x[1],x[2])).map(([sl,sv,st])=>`<button data-act="goto" data-v="${sv}" data-t="${st}"><span class="si">${ic(SIC[sv+':'+st]||'plus')}</span><span class="sl2">${sl}</span><span class="sa"></span></button>`).join('')}</div>`:''}</div>`).join('')}</div>`;
}
document.addEventListener('input',e=>{
  if(e.target.id!=='gs')return;const n=norm(e.target.value);const box=$('#gsr');
  if(n.length<2){box.innerHTML='';return}
  const cl=S.clients.filter(c=>norm(c.name+' '+(c.phone||'')+' '+(c.email||'')).includes(n)).slice(0,5);
  const tk=S.sales.filter(s=>norm(s.no+' '+(s.clientId?clientName(s.clientId):'')).includes(n)).slice(-5).reverse();
  const ev=S.events.filter(x=>norm(x.title).includes(n)).slice(0,5);
  const h=[...cl.map(c=>`<button class="row rowbtn" data-act="gsclient" data-id="${c.id}"><span class="grow"><b>${esc(c.name)}</b><span class="muted">Client · ${esc(c.phone||c.email||'')}</span></span></button>`),
    ...tk.map(s=>`<button class="row rowbtn" data-act="ticket" data-id="${s.id}"><span class="grow"><b>${s.no}</b><span class="muted">Ticket · ${s.clientId?esc(clientName(s.clientId)):'comptoir'}</span></span><b class="num">${eur(s.total)}</b></button>`),
    ...ev.map(x=>`<button class="row rowbtn" data-act="evinfo" data-id="${x.id}"><span class="grow"><b>${esc(x.title)}</b><span class="muted">Événement · ${dshort(x.date)}</span></span></button>`)];
  box.innerHTML=h.length?h.join(''):'<p class="muted" style="padding:10px 14px">Aucun résultat.</p>';
});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="gsclient"]');if(b)clientDetail(b.dataset.id)});

/* ---------- caisse : barre d'actions, tickets en attente ; page Caisse (tiroir) ---------- */
function drawCbar(){
  const el=$('#cbar');if(!el)return;const T=totals(cart),n=(S.held||[]).length;
  el.innerHTML=`<button data-act="chold">${ic('clock')}<span>Attente${n?' ('+n+')':''}</span></button><button data-act="pickclient">${ic('user')}<span>Client</span></button><button data-act="tdisc">${ic('ticket')}<span>Remise</span></button><button data-act="cabandon" class="x" ${T.items?'':'disabled'}>${ic('trash')}<span>Abandonner</span></button><button data-act="cbpay" class="go">${ic('cash')}<span>Payer${T.total?' '+eur(T.total):''}</span></button>`;
}
drawCart=(function(o){return function(){o();drawCbar()}})(drawCart);
function heldList(){
  const h=S.held||[];
  showModal(`${mh('Tickets en attente')}${h.length?h.map(x=>{const T=totals(x.cart);return `<div class="row"><span class="grow"><b>${T.items} article${T.items>1?'s':''} · ${eur(T.total)}</b><span class="muted">Mis en attente à ${hm(x.ts)}${x.cart.clientId?' · '+esc(clientName(x.cart.clientId)):''}</span></span><button class="btn primary" data-act="hresume" data-id="${x.id}" style="min-height:44px">Reprendre</button><button class="ix" data-act="hdel" data-id="${x.id}" aria-label="Supprimer">${ic('trash')}</button></div>`}).join(''):'<p class="muted">Aucun ticket en attente.</p>'}`);
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,d=b.dataset;
  if(a==='chold'){S.held=S.held||[];if(cart.lines.length){S.held.push({id:uid(),ts:Date.now(),cart:JSON.parse(JSON.stringify(cart))});cart=newCart();save();drawCart();drawGrid();toast('Ticket mis en attente')}else heldList()}
  else if(a==='hresume'){const i=(S.held||[]).findIndex(x=>x.id===d.id);if(i>=0){if(cart.lines.length)S.held.push({id:uid(),ts:Date.now(),cart:JSON.parse(JSON.stringify(cart))});cart=S.held.splice(i,1)[0].cart;save();closeModal();drawCart();drawGrid()}}
  else if(a==='hdel'){S.held=(S.held||[]).filter(x=>x.id!==d.id);save();heldList()}
  else if(a==='cabandon'){cfAbandon();cart=newCart();drawCart();drawGrid();toast('Ticket abandonné')}
  else if(a==='cbpay'){const T=totals(cart);if(!T.total&&!(T.L.length&&(T.pInfo||T.pcInfo)))toast('Le ticket est vide');else if(!slotOk(T))toast('Choisissez un créneau valide pour encaisser');else openPay()}
});
/* page Caisse façon tiroir */
const DEN=[50000,20000,10000,5000,2000,1000,500,200,100,50,20,10,5,2,1];
const denL=v=>v>=100?v/100+' €':v+' cts';
let cashCnt={};
function cashInfo(){
  const td=today(),ds=S.sales.filter(s=>dkey(new Date(s.ts))===td);
  const cash=ds.reduce((a,s)=>a+s.pay.filter(p=>p.m==='cash').reduce((x,p)=>x+p.amt,0),0);
  const mv=(S.cashmoves||[]).filter(x=>dkey(new Date(x.ts))===td),net=mv.reduce((a,x)=>a+(x.t==='dep'?x.amt:-x.amt),0);
  return{ds,cash,mv,exp:S.settings.fond+cash+net,enc:ds.reduce((a,s)=>a+s.total,0)};
}
function vCashbox(m){
  const c=cashInfo(),counted=DEN.reduce((a,v)=>a+(cashCnt[v]||0)*v,0),gap=counted-c.exp,any=counted>0;
  m.innerHTML=`<div class="cashtop"><div class="cbox blue"><span class="cbi">${ic('caisse')}</span><div><span>Fond de caisse attendu</span><b class="num">${eur(c.exp)}</b></div></div><div class="cbox orange"><span class="cbi">${ic('cash')}</span><div><span>Encaissement du jour · ${c.ds.length} ticket${c.ds.length>1?'s':''}</span><b class="num">${eur(c.enc)}</b></div></div></div>
  <div class="cols"><div class="card"><h3>Retrait / Dépôt</h3><form id="mvform"><div class="field"><label for="mvt">Opération</label><select id="mvt"><option value="ret">Retrait</option><option value="dep">Dépôt</option></select></div>
    <div class="field"><label for="mva">Montant (€)</label><input id="mva" inputmode="decimal" placeholder="0,00" autocomplete="off"></div><div class="field"><label for="mvc">Commentaire</label><input id="mvc" placeholder="Ex. dépôt en banque" autocomplete="off"></div>
    <button class="btn primary" type="submit">Sauvegarder</button></form>
    ${c.mv.length?`<div style="margin-top:14px">${c.mv.map(x=>`<div class="row"><span class="grow"><b>${x.t==='dep'?'Dépôt':'Retrait'}</b><span class="muted">${hm(x.ts)}${x.c?' · '+esc(x.c):''}</span></span><b class="num">${x.t==='dep'?'+':'− '}${eur(x.amt)}</b></div>`).join('')}</div>`:''}</div>
   <div class="card"><h3>Vérification de caisse</h3><div class="den">${DEN.map(v=>`<div class="drow"><b>${denL(v)}</b><div class="step"><button data-act="dq" data-v="${v}" data-d="-1" aria-label="Retirer">${ic('minus')}</button><b class="num">${cashCnt[v]||0}</b><button data-act="dq" data-v="${v}" data-d="1" aria-label="Ajouter">${ic('plus')}</button></div><span class="num muted">${(cashCnt[v]||0)?eur(cashCnt[v]*v):''}</span></div>`).join('')}</div>
    <div class="dtot"><div><span class="lab">Compté</span><b class="num">${eur(counted)}</b></div><div><span class="lab">Attendu</span><b class="num">${eur(c.exp)}</b></div><div class="${!any?'':gap===0?'ok':'ko'}"><span class="lab">Écart</span><b class="num">${any?(gap>0?'+':'')+eur(gap):'—'}</b></div></div>
    <button class="btn" data-act="dreset" style="margin-top:10px">Remettre à zéro</button></div></div>`;
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act;
  if(a==='dq'){const v=+b.dataset.v;cashCnt[v]=Math.max(0,(cashCnt[v]||0)+ +b.dataset.d);vCashbox($('#sub'))}
  else if(a==='dreset'){cashCnt={};vCashbox($('#sub'))}
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='mvform')return;e.preventDefault();
  const amt=parseEur($('#mva').value);if(!(amt>0)){toast('Saisissez un montant');return}
  S.cashmoves=S.cashmoves||[];S.cashmoves.push({id:uid(),ts:Date.now(),t:$('#mvt').value,amt,c:$('#mvc').value.trim()});save();toast('Mouvement enregistré');vCashbox($('#sub'));
});

/* ---------- Contrôle : sous-menus, rapports, PDF, IA ---------- */
const MOIS=['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const MPTS=['Toiles des trampolines (usure, déchirures)','Ressorts et élastiques','Cadres et structures métalliques','Protections de cadre (mousses de recouvrement)','Filets de sécurité','Fosses à mousse','Structures gonflables (Airtrack)','Parcours Ninja / escalade','Sols et revêtements','Éclairage et sorties de secours','Extincteurs et trousse de secours','Signalétique et règlement affiché','Vestiaires, sanitaires, casiers'];
const ITYPES=['Chute','Collision','Entorse / foulure','Choc à la tête','Coupure / plaie','Malaise','Autre'];
const ISECOURS=['Glace','Désinfection','Pansement','Repos','Appel des secours (15 / 18)','Parents prévenus','Aucun'];
const IWHO=['Client','Enfant','Accompagnant','Employé','Autre'];
const MEQ=['Trampoline','Ninja Warrior','Plaine de jeux','Air bag','Autre'];
let ctl={mon:today().slice(0,7),inc:null,mnt:null,chat:[],aiOut:'',busy:false};
tab.controle='visuel';
const CSUB=[['visuel','Contrôle quotidien'],['mensuel','Contrôle mensuel'],['maint','Maintenance'],['incident','Rapport d’incident']];
TABS.controle=CSUB;
SUBS.visuel=vVisuel;SUBS.mensuel=vMensuel;SUBS.maint=vMaint;SUBS.incident=vIncident;SUBS.ia=vIA;
function vControl(m){tabbed(m,'Contrôle')}
VIEWS.controle=vControl;
const subR=()=>{if(view==='controle'&&$('#sub'))SUBS[tab.controle]($('#sub'))};
const ymd=ts=>{const d=new Date(ts);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const sname=id=>{const s=S.staff.find(x=>x.id===id);return s?s.name:''};
const staffSel=(f,v,ph='Choisir')=>`<select data-f="${f}"><option value="">${ph}</option>${S.staff.map(s=>`<option value="${s.id}" ${v===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`;
const fl=(l,i)=>`<div class="field"><label>${l}</label>${i}</div>`;
const tg=(p,list,arr)=>`<div class="tgs">${list.map(x=>`<button type="button" class="tg ${(arr||[]).includes(x)?'on':''}" data-act="m_tg" data-p="${p}" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>`;
const rd=(p,list,val)=>`<div class="tgs">${list.map(x=>`<button type="button" class="tg ${val===x?'on':''}" data-act="m_set" data-p="${p}" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>`;
const dfr=d=>d?new Date(d+'T12:00:00').toLocaleDateString('fr-FR'):'';
const monRec=()=>{const k=ctl.mon;if(!S.monthly[k])S.monthly[k]={date:today(),by:curStaff(),items:{},p1:'',p2:'',obs:'',fix:'',zone:'',conf:'',writer:curStaff(),signed:0};return S.monthly[k]};
const monLabel=k=>MOIS[+k.slice(5)-1]+' '+k.slice(0,4);

/* ---- sélecteur de chemin pour les champs ---- */
function setPath(p,v){const [r,k]=p.split('.');
  if(r==='mon'){monRec()[k]=v;save()} else if(r==='inc'&&ctl.inc)ctl.inc[k]=v; else if(r==='mnt'&&ctl.mnt)ctl.mnt[k]=v;}
function getPath(p){const [r,k]=p.split('.');return r==='mon'?monRec()[k]:r==='inc'?ctl.inc&&ctl.inc[k]:ctl.mnt&&ctl.mnt[k]}

/* ---- visuel quotidien : version intégrée ---- */
function vVisuel(m){
  const c=ensureCheck(),done=c.done,n=CHECK_IDS.filter(k=>c.items[k]).length,tot=CHECK_IDS.length;
  const hist=Array.from({length:7},(_,i)=>addDays(today(),i-6)).map(d=>{const x=S.checks[d],ko=x&&Object.values(x.items).some(i=>i.s==='ko');
    return `<span class="${x&&x.done?(ko?'ko':'ok'):''}${d===(CHKDAY||today())?' sel':''}" title="${dshort(d)}" data-act="chkday" data-d="${d}" role="button" tabindex="0" aria-label="Contrôle du ${dshort(d)}">${+d.slice(8)}</span>`}).join('');
  const issues=Object.entries(S.checks).filter(([d,x])=>x.done).sort((a,b)=>b[0].localeCompare(a[0])).flatMap(([d,x])=>Object.entries(x.items).filter(([k,i])=>i.s==='ko').map(([k,i])=>[d,k,i.note])).slice(0,4);
  const label=k=>CHECKS.flatMap(g=>g.items).find(i=>i[0]===k)[1];
  m.innerHTML=chkDayBar()+`<div class="impo"><span class="pill warn">Important</span><span>À réaliser chaque jour avant l’ouverture.</span><button class="btn" data-act="m_pdf" data-k="daily">${ic('check')}PDF du jour</button></div>`+
  (done?`<div class="banner ok"><span>Contrôle du ${dfr(CHKDAY||today())} validé par ${esc(staffOf(c.by).name)} le ${new Date(c.ts).toLocaleDateString('fr-FR')} à ${hm(c.ts)}.</span><div class="bacts"><button class="btn" data-act="m_pdf" data-k="daily">PDF</button><button class="btn" data-act="docgo" data-t="daily">Voir dans Documents</button><button class="btn" data-act="chkopen">Modifier</button></div></div>`
   :`<div class="prog"><div class="bar"><i style="width:${Math.round(n/tot*100)}%"></i></div><b class="num">${n}/${tot}</b></div>`)+
  CHECKS.map(g=>`<div class="card" style="margin-bottom:14px"><h3><span class="gic">${gIcon(g.g)}</span>${g.g}</h3>${g.items.map(([k,l,t])=>{const a=c.items[k];
    return `<div class="chk"><div class="q">${l}</div><div class="yn"><button class="ok ${a&&a.s==='ok'?'on':''}" data-act="chk" data-k="${k}" data-s="ok" ${done?'disabled':''}>Conforme</button>
    <button class="ko ${a&&a.s==='ko'?'on':''}" data-act="chk" data-k="${k}" data-s="ko" ${done?'disabled':''}>Anomalie</button></div>
    ${t==='val'?`<div class="prs"><label class="prl"><span>Airbag 1 (hPa)</span><input id="press" inputmode="decimal" placeholder="Pression" value="${esc(c.press)}" ${done?'disabled':''} aria-label="Pression de l’airbag 1 en hPa"></label><label class="prl"><span>Airbag 2 (hPa)</span><input id="press2" inputmode="decimal" placeholder="Pression" value="${esc(c.press2||'')}" ${done?'disabled':''} aria-label="Pression de l’airbag 2 en hPa"></label></div>`:''}
    ${a&&a.s==='ko'?`<input data-note="${k}" placeholder="Décrivez l’anomalie" value="${esc(a.note)}" ${done?'disabled':''} aria-label="Anomalie">`:''}</div>`}).join('')}</div>`).join('')+
  (done?'':`<div class="card" style="margin-bottom:14px"><h3>Validation</h3><p class="muted" style="margin:-6px 0 10px">Contrôle du ${chkLong(CHKDAY||today())}</p><div class="field"><label for="chkby">Contrôle réalisé par</label><select id="chkby"><option value="">Choisir</option>${S.staff.map(s=>`<option value="${s.id}" ${c.by===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>
    <button class="btn-pay" id="chkok" data-act="chkdone" ${ctrlReady(c)?'':'disabled'}>Valider le contrôle</button>
    <p class="muted" style="margin-top:8px;font-size:13px">Tous les points, les deux pressions d’airbag et le nom sont nécessaires. Une anomalie demande une description.</p></div>`)+
  `<div class="card"><h3>7 derniers jours</h3><div class="hist">${hist}</div>
    ${issues.length?`<div style="margin-top:12px">${issues.map(([d,k,nt])=>`<div class="row"><span class="grow"><b>${esc(label(k))}</b><span class="muted">${esc(nt)}</span></span><span class="pill bad">${dshort(d)}</span></div>`).join('')}</div>`:''}</div>`;
}

/* ---- contrôle mensuel ---- */
function vMensuel(m){
  const r=monRec(),k=ctl.mon,y=+k.slice(0,4);
  const mchips=Array.from({length:12},(_,i)=>{const kk=y+'-'+String(i+1).padStart(2,'0'),x=S.monthly[kk];
    return `<button class="mchip ${kk===k?'on':''} ${x&&x.signed?'dn':''}" data-act="m_mon" data-k="${kk}">${MOIS[i].slice(0,4)}.</button>`}).join('');
  const nc=MPTS.filter((_,i)=>r.items[i]==='NC').length,filled=Object.keys(r.items).length;
  m.innerHTML=`<div class="mhead"><div class="yr"><button class="btn" data-act="m_yr" data-d="-1" aria-label="Année précédente">${ic('left')}</button><b class="num">${y}</b><button class="btn" data-act="m_yr" data-d="1" aria-label="Année suivante">${ic('right')}</button></div><div class="mchips">${mchips}</div></div>
  <div class="card" style="margin-bottom:14px"><div class="mtitle"><h3>${monLabel(k).toUpperCase()} – Contrôle mensuel des équipements</h3>${r.signed?'<span class="pill ok">Signé</span>':`<span class="pill">${filled}/${MPTS.length}</span>`}</div>
   <div class="g2">${fl('Date du contrôle',`<input type="date" data-f="mon.date" value="${r.date}">`)}${fl('Contrôle réalisé par',staffSel('mon.by',r.by))}</div></div>
  <div class="card" style="margin-bottom:14px"><h3>Points de contrôle</h3><p class="muted" style="font-size:13px;margin:0 0 6px">C = conforme · NC = non conforme · SO = sans objet</p>
   ${MPTS.map((l,i)=>`<div class="mrow"><span class="mq"><b class="num">${i+1}</b> ${l}</span><span class="cs">${['C','NC','SO'].map(v=>`<button type="button" class="${v} ${r.items[i]===v?'on':''}" data-act="m_c" data-i="${i}" data-v="${v}">${v}</button>`).join('')}</span></div>`).join('')}
   <div class="g2" style="margin-top:12px">${fl('Pression gonflable 1 (hPa)',`<input inputmode="decimal" data-f="mon.p1" value="${esc(r.p1)}">`)}${fl('Pression gonflable 2 (hPa)',`<input inputmode="decimal" data-f="mon.p2" value="${esc(r.p2)}">`)}</div></div>
  <div class="card" style="margin-bottom:14px"><h3>Observations et suites</h3>
   ${fl('Observations',`<textarea data-f="mon.obs" rows="3">${esc(r.obs)}</textarea>`)}
   ${fl('Action corrective mise en œuvre',`<textarea data-f="mon.fix" rows="2">${esc(r.fix)}</textarea>`)}
   ${fl('Zone condamnée (le cas échéant)',`<input data-f="mon.zone" value="${esc(r.zone)}">`)}
   ${fl('Structure conforme à l’ouverture au public ?',rd('mon.conf',['Oui','Non'],r.conf))}
   ${aiOk()?`<button class="btn ai" data-act="m_ai" data-k="mon" ${ctl.busy?'disabled':''}>${ic('wave')}Analyse IA du mois</button><div class="aiout" id="aiout">${esc(ctl.aiOut)}</div>`:''}</div>
  <div class="card"><h3>Signature</h3><div class="g2">${fl('Rédigé par',staffSel('mon.writer',r.writer))}<div class="field"><label>Statut</label><div class="muted">${r.signed?'Signé le '+new Date(r.signed).toLocaleString('fr-FR'):'Non signé'} ${nc?'· '+nc+' point(s) NC':''}</div></div></div>
   <div class="acts"><button class="btn primary" data-act="m_sign">${r.signed?'Signer à nouveau':'Valider et signer'}</button><button class="btn" data-act="m_pdf" data-k="monthly">${ic('check')}Exporter en PDF</button></div></div>`;
}

/* ---- rapport d'incident ---- */
function incNew(){return{id:uid(),date:today(),time:hm(Date.now()),writer:curStaff(),who:'Client',nom:'',prenom:'',naiss:'',tel:'',types:[],autre:'',desc:'',pain:null,secours:[],secouriste:'',notes:'',signed:0,ts:Date.now()}}
function vIncident(m){
  const d=ctl.inc;
  if(!d){
    const L=[...S.incidents].sort((a,b)=>b.ts-a.ts);
    m.innerHTML=`<div class="impo"><span>Rapports d’incident de ${esc(S.settings.name)}</span><button class="btn primary" data-act="m_incnew">${ic('plus')}Nouveau rapport</button></div>
    <div class="card">${L.length?L.map(x=>`<div class="row"><span class="grow"><b>${esc((x.prenom+' '+x.nom).trim()||'Personne non précisée')}</b><span class="muted">${dfr(x.date)} à ${esc(x.time)} · ${esc(x.types.join(', ')||'—')}</span></span>${x.pain!=null?`<span class="pill ${x.pain>=6?'bad':x.pain>=3?'warn':''}">Douleur ${x.pain}/10</span>`:''}<button class="btn" data-act="m_incopen" data-id="${x.id}">Ouvrir</button><button class="btn" data-act="m_pdf" data-k="inc" data-id="${x.id}">PDF</button></div>`).join(''):'<p class="muted">Aucun rapport pour le moment.</p>'}</div>
    ${aiOk()&&L.length?`<div class="card" style="margin-top:14px"><h3>Analyse des incidents</h3><button class="btn ai" data-act="m_ai" data-k="incs" ${ctl.busy?'disabled':''}>${ic('wave')}Repérer les tendances</button><div class="aiout" id="aiout">${esc(ctl.aiOut)}</div></div>`:''}`;
    return}
  m.innerHTML=`<div class="impo"><b>RAPPORT D’INCIDENT</b><button class="btn" data-act="m_inccancel">${ic('left')}Retour</button></div>
  <div class="card" style="margin-bottom:14px"><h3>Circonstances</h3><div class="g2">${fl('Lieu',`<input value="${esc(S.settings.name)}" disabled>`)}${fl('Rédigé par',staffSel('inc.writer',d.writer))}${fl('Date',`<input type="date" data-f="inc.date" value="${d.date}">`)}${fl('Heure',`<input type="time" data-f="inc.time" value="${esc(d.time)}">`)}</div></div>
  <div class="card" style="margin-bottom:14px"><h3>Personne concernée</h3>${fl('Type',rd('inc.who',IWHO,d.who))}
   <div class="g2">${fl('Nom',`<input data-f="inc.nom" value="${esc(d.nom)}">`)}${fl('Prénom',`<input data-f="inc.prenom" value="${esc(d.prenom)}">`)}${fl('Date de naissance',`<input type="date" data-f="inc.naiss" value="${d.naiss}">`)}${fl('Téléphone',`<input inputmode="tel" data-f="inc.tel" value="${esc(d.tel)}">`)}</div></div>
  <div class="card" style="margin-bottom:14px"><h3>Incident</h3>${fl('Type d’incident',tg('inc.types',ITYPES,d.types))}
   ${d.types.includes('Autre')?fl('Précisez',`<input data-f="inc.autre" value="${esc(d.autre)}">`):''}
   ${aiOk()?`<div class="field"><label>Notes rapides (l’IA rédige la description)</label><textarea id="incnotes" rows="2" placeholder="ex : garçon 9 ans, réception sur le côté, poignet, pleure un peu">${esc(d.notes)}</textarea><button class="btn ai" data-act="m_ai" data-k="incdraft" ${ctl.busy?'disabled':''}>${ic('wave')}Rédiger avec l’IA</button></div>`:''}
   ${fl('Description des faits',`<textarea data-f="inc.desc" id="incdesc" rows="4">${esc(d.desc)}</textarea>`)}
   ${fl('Douleur ressentie : <b class="num">'+(d.pain==null?'non précisée':d.pain+' / 10')+'</b>',`<div class="tgs">${Array.from({length:11},(_,i)=>`<button type="button" class="tg sm ${d.pain===i?'on':''}" data-act="m_pain" data-v="${i}">${i}</button>`).join('')}</div>`)}</div>
  <div class="card" style="margin-bottom:14px"><h3>Premiers secours</h3>${fl('Gestes réalisés',tg('inc.secours',ISECOURS,d.secours))}${fl('Secouriste',staffSel('inc.secouriste',d.secouriste))}</div>
  <div class="card"><h3>Signature</h3><p class="muted">${d.signed?'Signé le '+new Date(d.signed).toLocaleString('fr-FR')+' par '+esc(sname(d.writer)):'Non signé'}</p>
   <div class="acts"><button class="btn primary" data-act="m_incsave">Enregistrer et signer</button><button class="btn" data-act="m_pdf" data-k="incdraft">${ic('check')}PDF</button>${S.incidents.some(x=>x.id===d.id)?`<button class="btn" data-act="m_incdel" data-id="${d.id}">${ic('trash')}Supprimer</button>`:''}</div></div>`;
}

/* ---- rapport de maintenance ---- */
function mntNew(){return{id:uid(),date:today(),equip:MEQ[0],kinds:[],type:'',pb:'',action:'',pieces:'',min:'',statut:'À faire',tech:'',ts:Date.now()}}
function vMaint(m){
  const d=ctl.mnt;
  if(!d){
    const L=[...S.maint].sort((a,b)=>b.ts-a.ts),open=L.filter(x=>x.statut!=='Terminé').length;
    m.innerHTML=`<div class="impo"><span><b class="num">${open}</b> intervention${open>1?'s':''} en cours ou à faire</span><button class="btn primary" data-act="m_mntnew">${ic('plus')}Nouveau rapport</button></div>
    <div class="card">${L.length?L.map(x=>`<div class="row"><span class="grow"><b>${esc(mntEq(x))} · ${esc(x.type)}</b><span class="muted">${dfr(x.date)} · ${esc(x.pb||'—')}</span></span><span class="pill ${x.statut==='Terminé'?'ok':x.statut==='En cours'?'warn':'bad'}">${x.statut}</span><button class="btn" data-act="m_mntopen" data-id="${x.id}">Ouvrir</button><button class="btn" data-act="m_pdf" data-k="mnt" data-id="${x.id}">PDF</button></div>`).join(''):'<p class="muted">Aucune intervention enregistrée.</p>'}</div>`;
    return}
  m.innerHTML=`<div class="impo"><b>RAPPORT DE MAINTENANCE</b><button class="btn" data-act="m_mntcancel">${ic('left')}Retour</button></div>
  <div class="card">${mntKindsBox(d)}<div class="g2">${fl('Date',`<input type="date" data-f="mnt.date" value="${d.date}">`)}${fl('Équipement',`<select data-f="mnt.equip">${mntEqOpts(d)}</select>`)}</div>${mntEqOther(d)}
   ${fl('Problème constaté',`<textarea data-f="mnt.pb" id="mntpb" rows="3">${esc(d.pb)}</textarea>`)}
   ${aiOk()?`<button class="btn ai" data-act="m_ai" data-k="mntsug" ${ctl.busy?'disabled':''} style="margin-bottom:12px">${ic('wave')}Suggérer l’action et les pièces</button>`:''}
   ${fl('Action réalisée',`<textarea data-f="mnt.action" id="mntac" rows="3">${esc(d.action)}</textarea>`)}
   <div class="g2">${fl('Pièces remplacées',`<input data-f="mnt.pieces" id="mntpi" value="${esc(d.pieces)}">`)}${fl('Temps passé (min)',`<input inputmode="numeric" data-f="mnt.min" value="${esc(d.min)}">`)}${fl('Technicien',`<input data-f="mnt.tech" value="${esc(d.tech)}" placeholder="Nom ou société">`)}</div>
   ${fl('Statut',rd('mnt.statut',['À faire','En cours','Terminé'],d.statut))}
   <div class="acts"><button class="btn primary" data-act="m_mntsave">Enregistrer</button><button class="btn" data-act="m_pdf" data-k="mntdraft">${ic('check')}PDF</button>${S.maint.some(x=>x.id===d.id)?`<button class="btn" data-act="m_mntdel" data-id="${d.id}">${ic('trash')}Supprimer</button>`:''}</div></div>`;
}

/* ---- IA ---- */
let SAMPLE=null,DL=null;
(async()=>{try{if(window.claude&&claude.use){SAMPLE=await claude.use('sample');DL=await claude.use('downloads')}}catch(e){}
  try{if(window.claude&&claude.use&&!DL)DL=await claude.use('downloads')}catch(e){}
  if(SAMPLE&&view==='controle')subR()})();
const aiOk=()=>{aiSync();return !!SAMPLE};
const AIERR={not_granted:'L’assistant n’est pas autorisé pour cette page.',sampling_disabled:'L’assistant n’est pas disponible sur ce compte.',rate_limited:'Trop de demandes. Réessayez dans un instant.',upstream_error:'Connexion interrompue. Réessayez.',invalid_json:'Réponse illisible, réessayez.',refused:'Demande refusée.',cancelled:''};
function aiCtx(){
  const t=today(),sales=S.sales.filter(s=>ymd(s.ts)===t),ca=sales.reduce((a,s)=>a+s.total,0);
  const occs=QS.map(q=>occ(t,q)),pk=Math.max(...occs);
  const c=S.checks[t],ko=c?Object.values(c.items).filter(i=>i.s==='ko').length:0;
  const mk=ctl.mon,mr=S.monthly[mk],mnc=mr?MPTS.filter((_,i)=>mr.items[i]==='NC'):[];
  const inc=[...S.incidents].sort((a,b)=>b.ts-a.ts).slice(0,8).map(x=>`${x.date} ${x.types.join('/')} douleur ${x.pain==null?'?':x.pain}/10 : ${x.desc.slice(0,120)}`);
  const mn=[...S.maint].sort((a,b)=>b.ts-a.ts).slice(0,8).map(x=>`${x.date} ${mntEq(x)} ${x.type} ${x.statut} : ${x.pb.slice(0,80)}`);
  return `Parc de loisirs « ${S.settings.name} », capacité ${S.settings.cap} personnes, ouvert ${S.settings.open}h-${S.settings.close}h.
Aujourd'hui (${t}) : ${sales.length} tickets, chiffre d'affaires ${(ca/100).toFixed(2)} €, pic de fréquentation prévu ${pk}/${S.settings.cap} à ${fm(QS[occs.indexOf(pk)])}.
Contrôle visuel du jour : ${c&&c.done?'validé':'non validé'}, ${ko} anomalie(s).
Contrôle mensuel ${monLabel(mk)} : ${mr?(mr.signed?'signé':'en cours')+', points NC : '+(mnc.join('; ')||'aucun')+', observations : '+(mr.obs||'-'):'non commencé'}.
Derniers incidents : ${inc.join(' | ')||'aucun'}.
Dernières maintenances : ${mn.join(' | ')||'aucune'}.`;
}
async function aiRun(prompt,{json=false,onText}={}){
  ctl.busy=true;
  try{return json?await SAMPLE.json(prompt,{modelTier:'quick'}):(await SAMPLE(prompt,{modelTier:'default',onText})).text}
  finally{ctl.busy=false}
}
function aiShow(t){ctl.aiOut=t;const o=$('#aiout');if(o)o.textContent=t}
const AIRULES='Tu es l’assistant intégré de Lago, logiciel de gestion de parc de trampolines. Réponds en français, de façon courte, concrète et factuelle, sans inventer de données absentes. Tu aides à la sécurité et à l’exploitation ; tu ne remplaces pas un contrôle réglementaire.';
async function aiAction(k){
  try{
    if(k==='mon'){const r=monRec();aiShow('Analyse en cours…');
      const rows=MPTS.map((l,i)=>`${l} : ${r.items[i]||'non renseigné'}`).join('\n');
      const prev=Object.entries(S.monthly).filter(([kk])=>kk<ctl.mon).sort().slice(-3).map(([kk,x])=>kk+' NC: '+(MPTS.filter((_,i)=>x.items[i]==='NC').join('; ')||'aucun')).join('\n');
      await aiRun(AIRULES+'\nAnalyse ce contrôle mensuel : 1) résumé en une phrase, 2) points NC et priorité (urgent / à planifier), 3) récurrences avec les mois précédents, 4) l’ouverture au public est-elle raisonnable ? Maximum 120 mots.\n\n'+rows+'\nPressions : '+r.p1+' / '+r.p2+' hPa\nObservations : '+r.obs+'\nMois précédents :\n'+(prev||'aucun'),{onText:({text})=>aiShow(text)})}
    else if(k==='incs'){aiShow('Analyse en cours…');
      await aiRun(AIRULES+'\nVoici les incidents. Repère les tendances (zones, types, horaires, publics), les risques et propose 3 actions de prévention. Maximum 130 mots.\n\n'+S.incidents.map(x=>`${x.date} ${x.time} | ${x.who} | ${x.types.join('/')} | douleur ${x.pain==null?'?':x.pain} | ${x.desc}`).join('\n'),{onText:({text})=>aiShow(text)})}
    else if(k==='incdraft'){const n=($('#incnotes')||{}).value||'';if(n.trim().length<8){toast('Saisissez quelques notes');return}
      ctl.inc.notes=n;toast('Rédaction en cours…');
      const j=await aiRun(AIRULES+'\nÀ partir de ces notes d’un employé, rédige la description factuelle de l’incident (3 à 5 phrases, neutre, sans jugement ni faute attribuée, sans rien inventer). Réponds uniquement en JSON : {"description":string,"types":[parmi '+JSON.stringify(ITYPES)+'],"douleur":nombre 0-10 ou null}.\n\nNotes : '+n,{json:true});
      if(j&&typeof j.description==='string'){ctl.inc.desc=j.description;if(Array.isArray(j.types)&&!ctl.inc.types.length)ctl.inc.types=j.types.filter(x=>ITYPES.includes(x));if(typeof j.douleur==='number'&&ctl.inc.pain==null)ctl.inc.pain=Math.max(0,Math.min(10,Math.round(j.douleur)));subR();toast('Description rédigée : relisez avant de signer')}}
    else if(k==='mntsug'){const d=ctl.mnt;if(!d.pb.trim()){toast('Décrivez d’abord le problème');return}
      toast('Réflexion en cours…');
      const j=await aiRun(AIRULES+'\nUn employé décrit un problème sur l’équipement « '+mntEq(d)+' » (intervention : '+(d.type||'non précisée').toLowerCase()+'). Propose une action concrète et les pièces probables. Réponds uniquement en JSON : {"action":string,"pieces":string}.\n\nProblème : '+d.pb,{json:true});
      if(j&&j.action){if(!d.action)d.action=String(j.action);if(!d.pieces&&j.pieces)d.pieces=String(j.pieces);subR();toast('Suggestion ajoutée : à vérifier')}}
  }catch(e){const m=AIERR[e.code];if(e.code==='not_granted'||e.code==='sampling_disabled'){SAMPLE=null;subR()}if(m!=='')toast(m||'L’assistant est indisponible');if(e.text&&k==='mon'||e.text&&k==='incs')aiShow(e.text);else if(k==='mon'||k==='incs')aiShow('')}
  ctl.busy=false;
}

/* ---- assistant IA ---- */
const IASUG=['Fais le bilan de la journée','Quels sont les risques sécurité à surveiller ?','Comment remplir les créneaux creux cette semaine ?','Rédige un message pour les clients du week-end'];
function vIA(m){
  if(!aiOk()){m.innerHTML=`<div class="card"><h3>Assistant IA</h3><p class="muted">L’assistant n’est pas disponible dans cet affichage. Ouvrez Lago depuis votre compte Claude pour l’activer.</p></div>`;return}
  m.innerHTML=`<div class="card ia"><div class="iah"><span class="iaic">${ic('wave')}</span><div><h3 style="margin:0">Assistant Lago</h3><p class="muted" style="margin:0;font-size:13px">Il connaît vos ventes du jour, la fréquentation, les contrôles, incidents et maintenances.</p></div></div>
   <div class="iachips">${IASUG.map((s,i)=>`<button class="btn" data-act="m_ask" data-i="${i}">${s}</button>`).join('')}</div>
   <div class="chat" id="chat">${ctl.chat.length?ctl.chat.map(t=>`<div class="bub ${t.role}">${esc(t.content)}</div>`).join(''):'<p class="muted">Posez une question ou choisissez une suggestion.</p>'}</div>
   <div class="ask"><input id="askin" placeholder="Votre question…" autocomplete="off"><button class="btn primary" data-act="m_send" ${ctl.busy?'disabled':''}>Envoyer</button></div>
   <p class="muted" style="font-size:12px;margin:8px 0 0">Les réponses sont générées par IA et peuvent contenir des erreurs. Vérifiez avant d’agir. Utilise votre propre quota Claude.</p></div>`;
  const c=$('#chat');if(c)c.scrollTop=c.scrollHeight;
}
let askCtl=null;
async function ask(q){
  if(!q.trim()||ctl.busy||!SAMPLE)return;
  ctl.chat.push({role:'user',content:q});ctl.chat.push({role:'assistant',content:'…'});ctl.busy=true;subR();
  const turns=[{role:'user',content:AIRULES+'\n\nDonnées actuelles de l’établissement :\n'+aiCtx()+'\n\nRéponds aux questions suivantes.'},...ctl.chat.slice(0,-1).slice(-8)];
  if(turns[1]&&turns[1].role==='assistant')turns.splice(1,0,{role:'user',content:'Bonjour'});
  const bub=()=>{const b=document.querySelectorAll('#chat .bub.assistant');return b[b.length-1]};
  try{const r=await SAMPLE(turns,{cache:false,modelTier:'default',onText:({text})=>{const b=bub();if(b)b.textContent=text}});
    ctl.chat[ctl.chat.length-1].content=r.text}
  catch(e){ctl.chat[ctl.chat.length-1].content=e.text||AIERR[e.code]||'L’assistant est indisponible.';if(e.code==='not_granted'||e.code==='sampling_disabled')SAMPLE=null}
  ctl.busy=false;subR();
}

/* ---- générateur PDF (sans bibliothèque) ---- */
function pdfBuild(title,sub,foot,fn){
  const W=595,H=842,M=42,pages=[],imgs=[],pim={};let cur,y;
  const st=S.settings,LG=st.logoJ?{bin:atob(st.logoJ.split(',')[1]),w:st.logoW,h:st.logoH}:null;
  const MAP={'’':"'",'‘':"'",'“':'"','”':'"','–':'-','—':'-','…':'...','•':'-','→':'->','€':'\x80','œ':'\x9c','Œ':'\x8c'};
  const enc=s=>String(s==null?'':s).replace(/\u202f/g,' ').replace(/[’‘“”–—…•→€œŒ]/g,c=>MAP[c]).replace(/[^\x09\x20-\xff]/g,'?').replace(/[\\()]/g,'\\$&').replace(/\t/g,' ');
  const op=(x,yy,s,sz,b,col)=>{cur.push(`${col||'0.1 0.14 0.25'} rg BT /F${b?2:1} ${sz} Tf ${x.toFixed(1)} ${yy.toFixed(1)} Td (${enc(s)}) Tj ET`)};
  const rect=(x,yy,w,h,col)=>cur.push(`${col} rg ${x} ${yy} ${w} ${h} re f`);
  function np(){cur=[];pages.push(cur);rect(M,H-34,W-2*M,3,'1 0.48 0.1');if(LG){const hh=36,ww=Math.min(170,hh*LG.w/LG.h);cur.push(`q ${ww.toFixed(1)} 0 0 ${(ww*LG.h/LG.w).toFixed(1)} ${M} ${H-72} cm /Im1 Do Q`)}else op(M,H-62,(st.name||'WE FLY').toUpperCase(),22,1,'0.1 0.3 0.84');op(M,H-84,title,13,1);if(sub)op(W-M-sub.length*5.2,H-62,sub,10,0,'0.4 0.45 0.55');rect(M,H-92,W-2*M,1,'0.85 0.88 0.93');y=H-114}
  const need=n=>{if(y-n<62)np()};
  const wrap=(t,w,sz)=>{const mx=Math.max(8,Math.floor(w/(sz*.5))),out=[];String(t==null?'':t).split('\n').forEach(par=>{let l='';par.split(' ').forEach(wd=>{if((l+' '+wd).trim().length>mx&&l){out.push(l);l=wd}else l=(l+' '+wd).trim()});out.push(l)});return out};
  const w={
    gap:n=>{y-=n},
    img:(u,iw,ih,lab)=>{np();const mw=W-2*M,mh=H-200,k=Math.min(mw/iw,mh/ih),dw=iw*k,dh=ih*k;if(lab)op(M,H-110,lab,10,1,'0.35 0.4 0.5');const ix=imgs.push({bin:atob(u.split(',')[1]),w:iw,h:ih})-1;pim[pages.length-1]=ix;cur.push(`q ${dw.toFixed(1)} 0 0 ${dh.toFixed(1)} ${(M+(mw-dw)/2).toFixed(1)} ${(H-122-dh).toFixed(1)} cm /Ix${ix} Do Q`);y=62},
    sec:t=>{need(34);rect(M,y-6,W-2*M,20,'0.93 0.95 0.99');rect(M,y-6,4,20,'1 0.48 0.1');op(M+12,y,t,11,1);y-=26},
    kv:(l,v)=>{const ls=wrap(v||'-',W-2*M-160,10);need(ls.length*14+4);op(M,y,l,10,1,'0.35 0.4 0.5');ls.forEach((x,i)=>op(M+160,y-i*14,x,10,0));y-=ls.length*14+4},
    p:(t,sz=10)=>{wrap(t,W-2*M,sz).forEach(l=>{need(sz+5);op(M,y,l,sz,0);y-=sz+4})},
    row:(l,st)=>{const ls=wrap(l,W-2*M-70,10);need(ls.length*13+6);ls.forEach((x,i)=>op(M,y-i*13,x,10,0));const col=st==='NC'?'0.85 0.2 0.2':st==='C'?'0.1 0.55 0.3':'0.45 0.5 0.6';op(W-M-30,y,st||'-',10,1,col);y-=ls.length*13+3;rect(M,y+1,W-2*M,.5,'0.9 0.92 0.96');y-=3},
    sig:(l,v)=>{need(60);y-=6;op(M,y,l,10,1,'0.35 0.4 0.5');op(M,y-14,v||'',10,0);rect(M,y-40,220,.8,'0.5 0.55 0.65');op(M,y-52,'Signature',8,0,'0.5 0.55 0.65');y-=64}
  };
  np();fn(w);
  const N=pages.length;pages.forEach((p,i)=>{cur=p;rect(M,40,W-2*M,.8,'0.85 0.88 0.93');op(M,28,(st.name||'WE FLY').toUpperCase()+' / '+foot,8,0,'0.5 0.55 0.65');const t='Page '+(i+1)+'/'+N;op(W-M-t.length*4.4,28,t,8,0,'0.5 0.55 0.65')});
  let out='%PDF-1.4\n',off=[];const add=s=>{off.push(out.length);out+=(off.length)+' 0 obj\n'+s+'\nendobj\n'};
  const kids=pages.map((_,i)=>(5+i*2)+' 0 R').join(' ');
  add('<< /Type /Catalog /Pages 2 0 R >>');add(`<< /Type /Pages /Kids [${kids}] /Count ${N} >>`);
  add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  pages.forEach((p,i)=>{const s=p.join('\n');add(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >>${(LG||pim[i]!==undefined)?' /XObject << '+(LG?'/Im1 '+(5+2*N)+' 0 R ':'')+(pim[i]!==undefined?'/Ix'+pim[i]+' '+(5+2*N+(LG?1:0)+pim[i])+' 0 R ':'')+'>>':''} >> /Contents ${6+i*2} 0 R >>`);add(`<< /Length ${s.length} >>\nstream\n${s}\nendstream`)});
  if(LG)add(`<< /Type /XObject /Subtype /Image /Width ${LG.w} /Height ${LG.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${LG.bin.length} >>\nstream\n${LG.bin}\nendstream`);
  imgs.forEach(im=>add(`<< /Type /XObject /Subtype /Image /Width ${im.w} /Height ${im.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${im.bin.length} >>
stream
${im.bin}
endstream`));
  const xr=out.length;out+=`xref\n0 ${off.length+1}\n0000000000 65535 f \n`+off.map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${off.length+1} /Root 1 0 R >>\nstartxref\n${xr}\n%%EOF`;
  const u=new Uint8Array(out.length);for(let i=0;i<out.length;i++)u[i]=out.charCodeAt(i)&255;return u;
}
function pdfFor(k,id){
  if(k==='daily'){const c=ensureCheck();return['Contrôle visuel quotidien-'+(CHKDAY||today()),pdfBuild('CONTRÔLE VISUEL QUOTIDIEN',dfr(CHKDAY||today()),'REGISTRE DES CONTRÔLES QUOTIDIENS',w=>{
    w.kv('Réalisé par',c.by?sname(c.by):'-');if(c.press2!==undefined){w.kv('Pression airbag 1',c.press?c.press+' hPa':'-');w.kv('Pression airbag 2',c.press2?c.press2+' hPa':'-')}else w.kv('Pression relevée',c.press?c.press+' hPa':'-');w.kv('Statut',c.done?'Validé à '+hm(c.ts):'En cours');w.gap(6);
    CHECKS.forEach(g=>{w.sec(g.g);g.items.forEach(([kk,l])=>{const a=c.items[kk];w.row(l+(a&&a.s==='ko'&&a.note?' - '+a.note:''),a?(a.s==='ok'?'C':'NC'):'-')})});w.sig('Contrôleur',c.by?sname(c.by):'')})]}
  if(k==='monthly'){const r=monRec(),y=monLabel(ctl.mon);return['Controle mensuel-'+ctl.mon,pdfBuild(y.toUpperCase()+' – CONTRÔLE MENSUEL DES ÉQUIPEMENTS',dfr(r.date),'REGISTRE DES CONTRÔLES MENSUELS',w=>{
    w.kv('Date du contrôle',dfr(r.date));w.kv('Contrôle réalisé par',sname(r.by));w.gap(6);w.sec('Points de contrôle (C conforme / NC non conforme / SO sans objet)');
    MPTS.forEach((l,i)=>w.row((i+1)+'. '+l,r.items[i]||'-'));w.gap(6);w.kv('Pression gonflable 1',r.p1?r.p1+' hPa':'-');w.kv('Pression gonflable 2',r.p2?r.p2+' hPa':'-');w.gap(4);
    w.sec('Observations et suites');w.kv('Observations',r.obs);w.kv('Action corrective',r.fix);w.kv('Zone condamnée',r.zone);w.kv('Structure conforme',r.conf);w.kv('Rédigé par',sname(r.writer));
    w.sig('Signature',r.signed?sname(r.writer||r.by)+' - '+new Date(r.signed).toLocaleDateString('fr-FR'):'')})]}
  const d=k==='inc'?S.incidents.find(x=>x.id===id):k==='incdraft'?ctl.inc:k==='mnt'?S.maint.find(x=>x.id===id):ctl.mnt;if(!d)return null;
  if(k==='inc'||k==='incdraft')return['Rapport incident-'+d.date,pdfBuild('RAPPORT D’INCIDENT',dfr(d.date),'RAPPORT D’INCIDENT',w=>{
    w.sec('Circonstances');w.kv('Lieu',S.settings.name);w.kv('Date et heure',dfr(d.date)+' à '+d.time);w.kv('Rédigé par',sname(d.writer));
    w.sec('Personne concernée');w.kv('Type',d.who);w.kv('Nom',d.nom);w.kv('Prénom',d.prenom);w.kv('Date de naissance',dfr(d.naiss));w.kv('Téléphone',d.tel);
    w.sec('Incident');w.kv('Type d’incident',d.types.join(', ')+(d.autre?' ('+d.autre+')':''));w.kv('Description',d.desc);w.kv('Douleur',d.pain==null?'-':d.pain+' / 10');
    w.sec('Premiers secours');w.kv('Gestes réalisés',d.secours.join(', '));w.kv('Secouriste',sname(d.secouriste));
    w.sig('Signature',d.signed?sname(d.writer)+' - '+new Date(d.signed).toLocaleString('fr-FR'):sname(d.writer));(d.scans||[]).forEach((sc,i)=>w.img(sc.u,sc.w,sc.h,'Rapport papier numerise - page '+(i+1)+' sur '+d.scans.length))})];
  return['Rapport maintenance-'+d.date,pdfBuild('RAPPORT DE MAINTENANCE',dfr(d.date),'RAPPORTS DE MAINTENANCE',w=>{
    w.kv('Date',dfr(d.date));w.kv('Équipement',mntEq(d));w.kv('Nature de l’intervention',d.type);w.kv('Statut',d.statut);w.sec('Intervention');w.kv('Problème constaté',d.pb);w.kv('Action réalisée',d.action);w.kv('Pièces remplacées',d.pieces);
    w.kv('Temps passé',d.min?d.min+' min':'');w.kv('Technicien',d.tech);w.sig('Signature',d.tech)})];
}
async function doPdf(k,id){
  const r=pdfFor(k,id);if(!r){toast('Rien à exporter');return}
  if(!DL&&window.claude&&claude.use){try{DL=await claude.use('downloads')}catch(e){}}
  if(!DL){toast('L’export PDF n’est pas disponible dans cet affichage');return}
  try{await DL.save({filename:r[0].replace(/[^\w\-\u00C0-\u00FF ]/g,'')+'.pdf',data:new Blob([r[1]],{type:'application/pdf'})});toast('PDF enregistré')}
  catch(e){toast(e.code==='declined'?'Export annulé':e.code==='rate_limited'?'Une demande est déjà ouverte':'Export impossible')}
}

/* ---- événements du module ---- */
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act^="m_"]');if(!b||b.disabled)return;const a=b.dataset.act,d=b.dataset;
  switch(a){
    case 'm_mon':ctl.mon=d.k;ctl.aiOut='';subR();break;
    case 'm_yr':ctl.mon=(+ctl.mon.slice(0,4)+ +d.d)+ctl.mon.slice(4);ctl.aiOut='';subR();break;
    case 'm_c':{const r=monRec();r.items[d.i]=r.items[d.i]===d.v?undefined:d.v;if(r.items[d.i]===undefined)delete r.items[d.i];save();subR();break}
    case 'm_sign':{const r=monRec();if(!r.by||!r.writer){toast('Choisissez le contrôleur et le rédacteur');break}if(Object.keys(r.items).length<MPTS.length){toast('Renseignez les '+MPTS.length+' points');break}r.signed=Date.now();save();subR();toast('Contrôle mensuel signé');break}
    case 'm_tg':{const arr=getPath(d.p)||[];const i=arr.indexOf(d.v);i<0?arr.push(d.v):arr.splice(i,1);setPath(d.p,arr);subR();break}
    case 'm_set':setPath(d.p,d.v);subR();break;
    case 'm_pain':ctl.inc.pain=ctl.inc.pain===+d.v?null:+d.v;subR();break;
    case 'm_incnew':ctl.inc=incNew();ctl.aiOut='';subR();break;
    case 'm_incopen':ctl.inc=JSON.parse(JSON.stringify(S.incidents.find(x=>x.id===d.id)));subR();break;
    case 'm_inccancel':ctl.inc=null;subR();break;
    case 'm_incsave':{const x=ctl.inc;if(!x.writer){toast('Choisissez le rédacteur');break}if(!x.desc.trim()){toast('Décrivez les faits');break}x.signed=Date.now();const i=S.incidents.findIndex(y=>y.id===x.id);i<0?S.incidents.push(x):S.incidents[i]=x;save();ctl.inc=null;subR();toast('Rapport enregistré et signé');break}
    case 'm_incdel':askYes('Supprimer ce rapport ?',()=>{S.incidents=S.incidents.filter(x=>x.id!==d.id);save();ctl.inc=null;subR()},'Supprimer');break;
    case 'm_mntnew':ctl.mnt=mntNew();subR();break;
    case 'm_mntopen':ctl.mnt=JSON.parse(JSON.stringify(S.maint.find(x=>x.id===d.id)));subR();break;
    case 'm_mntcancel':ctl.mnt=null;subR();break;
    case 'm_mntsave':{const x=ctl.mnt;if(!(x.kinds&&x.kinds.length)&&!x.type){toast('Cochez au moins une nature d’intervention, en haut du rapport');break}if(x.equip==='Autre'&&!(x.equipAutre||'').trim()){toast('Précisez l’équipement dans le champ « Autre »');break}if(x.equip!=='Autre')delete x.equipAutre;if(!x.pb.trim()){toast('Décrivez le problème');break}const i=S.maint.findIndex(y=>y.id===x.id);i<0?S.maint.push(x):S.maint[i]=x;save();ctl.mnt=null;subR();toast('Rapport enregistré');break}
    case 'm_mntdel':askYes('Supprimer ce rapport ?',()=>{S.maint=S.maint.filter(x=>x.id!==d.id);save();ctl.mnt=null;subR()},'Supprimer');break;
    case 'm_pdf':doPdf(d.k,d.id);break;
    case 'm_ai':aiAction(d.k).then(subR);break;
    case 'm_ask':ask(IASUG[+d.i]);break;
    case 'm_send':{const i=$('#askin');if(i&&i.value.trim()){const q=i.value;i.value='';ask(q)}break}
  }
});
function fieldEv(e){const t=e.target;if(!t.dataset||!t.dataset.f)return;let v=t.value;
  if(t.dataset.f==='inc.time'||true)setPath(t.dataset.f,v)}
document.addEventListener('input',e=>{fieldEv(e);const t=e.target;if(t.id==='incnotes'&&ctl.inc)ctl.inc.notes=t.value});
document.addEventListener('change',fieldEv);
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='askin'){e.preventDefault();const i=e.target;if(i.value.trim()){const q=i.value;i.value='';ask(q)}}});

