let pimg;
function fileToData(file,max,cb){
  const fr=new FileReader();
  fr.onload=()=>{const im=new Image();im.onload=()=>{
    const k=Math.min(1,max/Math.max(im.width,im.height)),w=Math.max(1,Math.round(im.width*k)),h=Math.max(1,Math.round(im.height*k));
    const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');
    x.drawImage(im,0,0,w,h);const png=c.toDataURL('image/png');
    x.globalCompositeOperation='destination-over';x.fillStyle='#fff';x.fillRect(0,0,w,h);
    cb({png,jpg:c.toDataURL('image/jpeg',.85),w,h})};
    im.onerror=()=>toast('Image illisible');im.src=fr.result};
  fr.readAsDataURL(file);
}
const logoHtml=(cls='')=>{const l=S.settings.logo;return l?`<img class="brandlogo ${cls}" src="${l}" alt="${esc(S.settings.name)}">`:''};
const OPM=[['resa','Planning clients'],['staff','Planning staff'],['clients','Clients'],['controle','Contrôle'],['gestion','Gestion']];
