function profForm(id){
  const p=id?S.profiles.find(x=>x.id===id):{id:'',name:'',pin:'',perms:{caisse:true,controle:true,'controle:visuel':true,'controle:incident':true}};
  const cb=(k,l,ind)=>`<label class="check" ${ind?'style="margin-left:26px"':''}><input type="checkbox" data-pk="${k}" ${p.perms[k]?'checked':''}>${l}</label>`;
  showModal(`${mh(id?'Modifier le profil':'Nouveau profil')}<form id="proform" data-id="${id||''}">
   <div class="two"><div class="field"><label for="prn">Nom du profil</label><input id="prn" required value="${esc(p.name)}" placeholder="ex : Accueil, Bar, Manager"></div>
   </div>
   <div class="field"><label>Accès autorisés</label>${PMODS.filter(x=>x[0]!=='caisse').map(([k,l,subs])=>cb(k,l)+(subs||[]).map(([t,tl])=>cb(k+':'+t,tl,1)).join('')).join('')}</div>
   <div style="display:flex;gap:8px"><button class="btn primary" type="submit" style="flex:1">Enregistrer</button>${id&&S.profiles.length>1?`<button class="btn danger" type="button" data-act="profdel" data-id="${id}">Supprimer</button>`:''}</div></form>`);
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act,d=b.dataset;
  if(a==='rolesw_x')whoModal();
  else if(a==='pswitch'){
    if(d.id==='admin'){pinAsk('admin');return}
    const p=S.profiles.find(x=>x.id===d.id);if(!p)return;
    if(p.pin)pinAsk(p.id);else applyWho(p.id);
  }
  else if(a==='profnew'&&isAdmin())profForm('');
  else if(a==='profedit'&&isAdmin())profForm(d.id);
  else if(a==='profdel'&&isAdmin()){S.profiles=S.profiles.filter(x=>x.id!==d.id);save();closeModal();vSetProf($('#sub'));toast('Profil supprimé')}
});
document.addEventListener('submit',e=>{
  const f=e.target;
  if(f.id==='ppinform'){e.preventDefault();const id=f.dataset.id,v=$('#ppin').value;
    const ok=id==='admin'?v===(S.settings.pin||'1234'):v===(S.profiles.find(p=>p.id===id)||{}).pin;
    if(ok)applyWho(id);else{$('#ppinerr').textContent='Code incorrect.';$('#ppin').value='';$('#ppin').focus()}}
  else if(f.id==='proform'){e.preventDefault();if(!isAdmin())return;
    const name=$('#prn').value.trim(),pin='';if(!name)return;
    if(pin&&pin.length<4){toast('Le code doit avoir au moins 4 caractères');return}
    const perms={};f.querySelectorAll('[data-pk]').forEach(c=>{perms[c.dataset.pk]=c.checked});
    PMODS.forEach(([k,l,subs])=>{if(!perms[k])(subs||[]).forEach(([t])=>perms[k+':'+t]=false)});
    const id=f.dataset.id;if(id){Object.assign(S.profiles.find(x=>x.id===id),{name,pin,perms})}else S.profiles.push({id:uid(),name,pin,perms});
    save();closeModal();vSetProf($('#sub'));toast('Profil enregistré')}
});

