/* ---- D. personnalisation avancée ---- */
function homeList(){
  const h=S.settings.home||{},ord=h.order||[],hide=h.hide||{},nm=h.names||{};
  const L=MTL.slice().sort((a,b)=>{const x=ord.indexOf(a[2]),y=ord.indexOf(b[2]);return (x<0?99:x)-(y<0?99:y)});
  return L.filter(t=>!hide[t[2]]).map(t=>[nm[t[2]]||t[0],...t.slice(1)])
}
function vSetHome(m){
  const h=S.settings.home=S.settings.home||{},hide=h.hide||{},nm=h.names||{};
  const L=MTL.slice().sort((a,b)=>{const o=h.order||[];const x=o.indexOf(a[2]),y=o.indexOf(b[2]);return (x<0?99:x)-(y<0?99:y)});
  m.innerHTML=`<div class="card"><h3>Écran d’accueil et menus</h3><p class="muted" style="font-size:13px;margin-bottom:8px">Renommez, réordonnez ou masquez les tuiles de l’accueil. Les noms s’appliquent aussi au menu de gauche.</p>
   ${L.map((t,i)=>`<div class="row"><span class="mt-ic sm2">${ic(t[1])}</span><input class="grow" data-hname="${t[2]}" value="${esc(nm[t[2]]||'')}" placeholder="${esc(t[0])}" aria-label="Nom de ${esc(t[0])}"><label class="check" style="margin:0"><input type="checkbox" data-hshow="${t[2]}" ${hide[t[2]]?'':'checked'}>Visible</label><button class="btn" data-act="hmove" data-v="${t[2]}" data-d="-1" ${i?'':'disabled'} aria-label="Monter">${ic('left')}</button><button class="btn" data-act="hmove" data-v="${t[2]}" data-d="1" ${i<L.length-1?'':'disabled'} aria-label="Descendre">${ic('right')}</button></div>`).join('')}</div>`;
}
TABS.params.push(['phome','Accueil']);SUBS.phome=vSetHome;
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="hmove"]');if(!b||!isAdmin())return;
  const h=S.settings.home=S.settings.home||{};const cur=MTL.slice().sort((a,c)=>{const o=h.order||[];return (o.indexOf(a[2])<0?99:o.indexOf(a[2]))-(o.indexOf(c[2])<0?99:o.indexOf(c[2]))}).map(t=>t[2]);
  const i=cur.indexOf(b.dataset.v),j=i+ +b.dataset.d;if(j<0||j>=cur.length)return;[cur[i],cur[j]]=[cur[j],cur[i]];h.order=cur;save();vSetHome($('#sub'))});
document.addEventListener('change',e=>{const t=e.target;if(!isAdmin())return;
  if(t.dataset.hname!==undefined){const h=S.settings.home=S.settings.home||{};h.names=h.names||{};h.names[t.dataset.hname]=t.value.trim();save();renderNav();toast('Enregistré')}
  else if(t.dataset.hshow){const h=S.settings.home=S.settings.home||{};h.hide=h.hide||{};h.hide[t.dataset.hshow]=!t.checked;save();toast('Enregistré')}
  else if(t.dataset.look){const st=S.settings;st[t.dataset.look]=t.value;save();applyLook();toast('Enregistré')}
  else if(t.dataset.sidec){S.settings.sideColor=t.value;save();applyLook()}
});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="sidereset"]');if(!b||!isAdmin())return;delete S.settings.sideColor;save();applyTheme();applyLook();vSetApp($('#sub'))});
function lum(h){const n=parseInt(h.slice(1),16),r=n>>16&255,g=n>>8&255,b=n&255;return (0.299*r+0.587*g+0.114*b)/255}
function applyLookBase(){
  const st=S.settings,r=document.documentElement.style;
  document.body.dataset.round=st.round||'std';
  const z=+st.zoom||100;document.body.style.zoom=z===100?'':z/100;
  if(st.sideColor){r.setProperty('--side',st.sideColor);r.setProperty('--side-bg',st.sideColor);r.setProperty('--side-ink',lum(st.sideColor)>.62?'#0A1F4D':'#fff')}else{r.removeProperty('--side-bg');r.removeProperty('--side-ink')}
}
function lookCard(){const st=S.settings;
  return `<div class="cols"><div class="card"><h3>Style</h3>
   ${fld('Angles',`<select data-look="round"><option value="std" ${st.round!=='sq'&&st.round!=='pill'?'selected':''}>Arrondis (standard)</option><option value="sq" ${st.round==='sq'?'selected':''}>Carrés</option><option value="pill" ${st.round==='pill'?'selected':''}>Très arrondis</option></select>`)}
   ${fld('Taille d’affichage',`<select data-look="zoom">${[90,100,110,125].map(z=>`<option value="${z}" ${(+st.zoom||100)===z?'selected':''}>${z} %</option>`).join('')}</select>`,'Agrandit tout Lago pour un écran tactile.')}
   <div class="field"><label>Couleur du menu de gauche</label><input type="color" class="cpick wide" data-sidec="1" value="${st.sideColor||st.brand}"><button class="btn" style="margin-top:8px" data-act="sidereset">Même couleur que le thème</button></div></div></div>`}

/* ---- E. planning d'ouverture ---- */
function hoursInit(){const st=S.settings;if(!S.hours){S.hours={week:{},exc:[]};for(let d=0;d<7;d++)S.hours.week[d]={closed:false,o:st.open*60,c:st.close*60}}}
function hoursFor(ds){
  hoursInit();const dow=new Date(ds+'T12:00:00').getDay();let r={...S.hours.week[dow],label:''};
  S.hours.exc.forEach(x=>{if(ds>=x.from&&ds<=x.to)r={closed:!!x.closed,o:x.o,c:x.c,label:x.label||''}});return r;
}
const openAt=(ds,t)=>{const h=hoursFor(ds);return !h.closed&&t>=h.o&&t+15<=h.c};
function syncEnvelope(){
  hoursInit();const all=[...Object.values(S.hours.week),...S.hours.exc].filter(x=>!x.closed);if(!all.length)return;
  S.settings.open=Math.floor(Math.min(...all.map(x=>x.o))/60);S.settings.close=Math.ceil(Math.max(...all.map(x=>x.c))/60);applySettings();
}
function vHours(m){
  hoursInit();const ad=isAdmin(),W=S.hours.week,dis=ad?'':'disabled';
  const order=[1,2,3,4,5,6,0];
  const t0=today();
  const cal=Array.from({length:28},(_,i)=>addDays(t0,i)).map(d=>{const h=hoursFor(d),sp=h.label||(S.hours.exc.some(x=>d>=x.from&&d<=x.to));
    return `<div class="hc ${h.closed?'cl':sp?'sp':''}"><small>${wdS(d)} ${+d.slice(8)}</small><b>${h.closed?'Fermé':hmm(h.o).replace(':00','h').replace(':','h')+'–'+hmm(h.c).replace(':00','h').replace(':','h')}</b>${h.label?`<i>${esc(h.label)}</i>`:''}</div>`}).join('');
  m.innerHTML=`<div class="cols"><div class="card"><h3>Semaine type</h3>
   ${order.map(d=>`<div class="hrow"><b>${dayShort[d]}</b><label class="check" style="margin:0"><input type="checkbox" data-hopen="${d}" ${W[d].closed?'':'checked'} ${dis}>Ouvert</label><input type="time" data-ho="${d}" value="${hmm(W[d].o)}" ${W[d].closed?'disabled':dis} aria-label="Ouverture ${dayShort[d]}"><span>à</span><input type="time" data-hc="${d}" value="${hmm(W[d].c)}" ${W[d].closed?'disabled':dis} aria-label="Fermeture ${dayShort[d]}"></div>`).join('')}
   ${ad?`<button class="btn" style="margin-top:10px" data-act="hcopy">Copier le lundi sur toute la semaine</button>`:''}</div>
   <div class="card"><h3>Vacances, jours fériés, fermetures</h3><p class="muted" style="font-size:13px;margin-bottom:8px">Horaires spéciaux ou fermetures sur une période. Ils remplacent la semaine type.</p>
   ${S.hours.exc.length?S.hours.exc.slice().sort((a,b)=>a.from.localeCompare(b.from)).map(x=>`<div class="row"><span class="grow"><b>${esc(x.label||'Horaires spéciaux')}</b><span class="muted">${dshort(x.from)}${x.to!==x.from?' → '+dshort(x.to):''} · ${x.closed?'Fermé':hmm(x.o)+' – '+hmm(x.c)}</span></span>${ad?`<button class="btn" data-act="hexedit" data-id="${x.id}">Modifier</button>`:''}</div>`).join(''):'<p class="muted">Aucune période spéciale.</p>'}
   ${ad?`<button class="btn primary" style="margin-top:10px" data-act="hexnew">${ic('plus')}Ajouter une période</button>`:''}</div></div>
   <div class="card" style="margin-top:14px"><h3>Les 4 prochaines semaines</h3><div class="hcal">${cal}</div>${ad?'':'<p class="muted" style="font-size:13px;margin-top:8px">Seul l’administrateur modifie les horaires.</p>'}</div>`;
}
function hexForm(id){
  const x=id?S.hours.exc.find(y=>y.id===id):{id:'',label:'',from:today(),to:today(),closed:true,o:S.settings.open*60,c:S.settings.close*60};
  showModal(`${mh(id?'Modifier la période':'Nouvelle période')}<form id="hexform" data-id="${id||''}">
   ${fld('Intitulé',`<input id="hxl" value="${esc(x.label)}" placeholder="ex : Vacances de Noël, Jour de l’an">`)}
   <div class="two">${fld('Du',`<input id="hxf" type="date" required value="${x.from}">`)}${fld('Au',`<input id="hxt" type="date" required value="${x.to}">`)}</div>
   <label class="check"><input type="checkbox" id="hxc" ${x.closed?'checked':''}>Établissement fermé</label>
   <div class="two">${fld('Ouverture',`<input id="hxo" type="time" value="${hmm(x.o)}">`)}${fld('Fermeture',`<input id="hxe" type="time" value="${hmm(x.c)}">`)}</div>
   <div style="display:flex;gap:8px"><button class="btn primary" type="submit" style="flex:1">Enregistrer</button>${id?`<button class="btn danger" type="button" data-act="hexdel" data-id="${id}">Supprimer</button>`:''}</div></form>`);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||!isAdmin())return;const a=b.dataset.act;
  if(a==='hexnew')hexForm('');else if(a==='hexedit')hexForm(b.dataset.id);
  else if(a==='hexdel'){S.hours.exc=S.hours.exc.filter(x=>x.id!==b.dataset.id);syncEnvelope();save();closeModal();vHours($('#sub'))}
  else if(a==='hcopy'){const m=S.hours.week[1];for(let d=0;d<7;d++)S.hours.week[d]={...m};syncEnvelope();save();vHours($('#sub'));toast('Horaires copiés')}
});
document.addEventListener('submit',e=>{if(e.target.id!=='hexform'||!isAdmin())return;e.preventDefault();
  const id=e.target.dataset.id,x={id:id||uid(),label:$('#hxl').value.trim(),from:$('#hxf').value,to:$('#hxt').value,closed:$('#hxc').checked,o:pmm($('#hxo').value),c:pmm($('#hxe').value)};
  if(x.to<x.from){toast('La date de fin précède le début');return}if(!x.closed&&x.c<=x.o){toast('La fermeture doit suivre l’ouverture');return}
  if(id)S.hours.exc[S.hours.exc.findIndex(y=>y.id===id)]=x;else S.hours.exc.push(x);syncEnvelope();save();closeModal();vHours($('#sub'));toast('Période enregistrée')});
document.addEventListener('change',e=>{const t=e.target;if(!isAdmin())return;hoursInit();
  if(t.dataset.hopen!==undefined){S.hours.week[t.dataset.hopen].closed=!t.checked;syncEnvelope();save();vHours($('#sub'))}
  else if(t.dataset.ho!==undefined||t.dataset.hc!==undefined){const d=t.dataset.ho!==undefined?t.dataset.ho:t.dataset.hc,k=t.dataset.ho!==undefined?'o':'c',w=S.hours.week[d];const v=pmm(t.value);
    if(k==='o'&&v>=w.c||k==='c'&&v<=w.o){toast('Horaires incohérents');vHours($('#sub'));return}w[k]=v;syncEnvelope();save();toast('Horaires enregistrés')}
});
TABS.resa.push(['horaires','Ouverture']);SUBS.horaires=vHours;
function leftFor(date,start,dur){let mx=0;for(let t=start;t<start+dur;t+=15){if(!openAt(date,t)||(S.closed&&S.closed[date+'|'+t]))return 0;mx=Math.max(mx,occ(date,t))}return S.settings.cap-mx}

/* ====== Q : stats, inventaire, devis, mur d'équipe, IA vocale, photos, import Qweekle, ludique ====== */
const eurN=c=>(c/100).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';
function saveBytes(name,bytes,type){
  return (async()=>{
    if(!DL&&window.claude&&claude.use){try{DL=await claude.use('downloads')}catch(e){}}
    if(!DL){try{const bl=new Blob([bytes],{type:type||'application/pdf'}),u=URL.createObjectURL(bl),a=document.createElement('a');a.href=u;a.download=name.replace(/[^\w\-À-ÿ .]/g,'');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);toast('Fichier téléchargé')}catch(e){toast('Export impossible')}return}
    try{await DL.save({filename:name.replace(/[^\w\-À-ÿ .]/g,''),data:new Blob([bytes],{type:type||'application/pdf'})});toast('Fichier enregistré')}
    catch(e){toast(e.code==='declined'?'Export annulé':'Export impossible')}
  })();
}
/* ---- avatars / photos ---- */
function avAV0(a,big){const cl='avatar'+(big?' big':'');return a&&a.photo?`<span class="${cl} ph"><img src="${a.photo}" alt=""></span>`:`<span class="${cl}">${esc(initials(a?a.name:'?'))}</span>`}
document.addEventListener('change',e=>{const t=e.target;
  if(t.id==='photof'&&t.files[0]&&ME){fileToData(t.files[0],220,r=>{ME.photo=r.jpg;save();chrome();accountMenu();toast('Photo enregistrée')});t.value=''}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="photorm"]');if(!b||!ME)return;delete ME.photo;save();chrome();accountMenu()});

/* ---- visibilité du planning staff ---- */
function visStaff(){if(isAdmin()||perm('staff:all'))return S.staff;const s=ME&&ME.staffId?S.staff.find(x=>x.id===ME.staffId):null;return s?[s]:[]}
const canAll=()=>isAdmin()||perm('staff:all');

/* ---- mur d'équipe ---- */
const boardL=()=>S.board||(S.board=[]);
function unreadN(){return ME?boardL().filter(x=>x.ts>(ME.seen||0)&&x.accId!==ME.id&&boardAlive(x)).length:0}
function boardHtml(){
  const L=(boardPurge(),boardL().filter(x=>boardAlive(x))).sort((a,b)=>(b.ts)-(a.ts)).slice(0,8),n=unreadN();
  return `<section class="board card"><div class="bh"><h3>${ic('users')}Messages de l’équipe ${n?`<span class="pill warn">${n} nouveau${n>1?'x':''}</span>`:''}</h3></div>
   <form id="bform" class="bcomp">${avA(ME)}<textarea id="btext" rows="1" placeholder="Laissez un message à l’équipe : ex. caisse faite, problème de lumière à régler…" maxlength="400"></textarea><div class="bc2"><span></span><button class="btn primary" type="submit">Publier</button></div></form>
   <div class="blist">${L.length?L.map(x=>{const a=accs().find(y=>y.id===x.accId);return `<div class="bmsg ${x.ts>(ME&&ME.seen||0)&&ME&&x.accId!==ME.id?'new':''}">${avA(a||{name:x.name})}<div class="bb"><div class="bm"><b>${esc(x.name)}</b><span class="muted">${new Date(x.ts).toLocaleString('fr-FR',{weekday:'short',hour:'2-digit',minute:'2-digit'})}</span></div><p>${esc(x.text)}</p></div><div class="ba">${ME&&(isAdmin()||x.accId===ME.id)?`<button class="btn" data-act="bdel" data-id="${x.id}" aria-label="Supprimer">${ic('trash')}</button>`:''}</div></div>`}).join(''):'<p class="muted">Aucun message pour le moment.</p>'}</div></section>`;
}
document.addEventListener('submit',e=>{if(e.target.id!=='bform'||!ME)return;e.preventDefault();const t=$('#btext').value.trim();if(!t)return;
  boardL().push({id:uid(),accId:ME.id,name:ME.name,text:t,urgent:false,ts:Date.now(),done:false});save();ME.seen=Date.now();save();vHome($('#main'));toast('Message publié')});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="bdone"],[data-act="bdel"]');if(!b)return;const x=boardL().find(y=>y.id===b.dataset.id);if(!x)return;
  if(b.dataset.act==='bdel'&&(isAdmin()||x.accId===ME.id))S.board.splice(S.board.indexOf(x),1);save();vHome($('#main'))});
function noteNew(){const n=unreadN();if(n)toast(n+' nouveau'+(n>1?'x':'')+' message'+(n>1?'s':'')+' de l’équipe')}

/* ---- accueil : mur + mon planning ---- */
function myWeek(){
  const s=ME&&ME.staffId?S.staff.find(x=>x.id===ME.staffId):null;if(!s)return '';
  const rows=Array.from({length:7},(_,i)=>addDays(today(),i)).map((d,i)=>{const lv=onLeave(s.id,d),sh=lv?'Congé':shiftLabel(d,s.id);
    return `<div class="mw ${i===0?'td':''} ${sh&&!lv?'on':''}"><small>${i===0?'Auj.':wdS(d)}</small><b>${+d.slice(8)}</b><span>${sh||'Repos'}</span></div>`}).join('');
  return `<div class="card myw"><h3>Mon planning · ${esc(s.name)}</h3><div class="mws">${rows}</div></div>`;
}
function vHomeV0(m){
  vHomeBase(m);
  const hero=m.querySelector('.hero');
  if(hero)hero.insertAdjacentHTML('afterend',(pshow('h_board')?boardHtml():'')+(pshow('h_week')?myWeek():''));
  if(!canAll()){m.querySelectorAll('.home .card').forEach(c=>{const h=c.querySelector('h3');if(h&&/Équipe en poste/.test(h.textContent))c.remove()});
    m.querySelectorAll('.kpi').forEach(k=>{if(/Équipe en poste/.test(k.textContent))k.remove()})}
  if(ME){setTimeout(()=>{if(ME){ME.seen=Date.now();save()}},3000)}
}

/* ---- statistiques ---- */
let stP='30';
const stPeriods=[['1','Aujourd’hui'],['7','7 jours'],['30','30 jours'],['mois','Ce mois'],['an','Cette année']];
function stRange(p){const t=today();let from,n;
  if(p==='mois'){from=t.slice(0,8)+'01';n=+t.slice(8)}else if(p==='an'){from=t.slice(0,4)+'-01-01';n=Math.round((new Date(t)-new Date(from))/864e5)+1}else{n=+p;from=addDays(t,-(n-1))}
  const days=Array.from({length:n},(_,i)=>addDays(from,i)),pf=addDays(from,-n);return{from,to:t,n,days,pdays:Array.from({length:n},(_,i)=>addDays(pf,i))}}
const sumBy=(L,f)=>L.reduce((a,x)=>a+f(x),0);
function stCalc(days){const set=new Set(days),L=S.sales.filter(s=>set.has(dkey(new Date(s.ts))));
  const ca=sumBy(L,s=>s.total),jp=sumBy(L,s=>s.jumpers||0);return{L,ca,n:L.length,jp,avg:L.length?ca/L.length:0,perJ:jp?ca/jp:0}}
const dlt=(a,b)=>b?Math.round((a-b)/b*100):null;
const dTag=v=>v==null?'':`<span class="dl ${v>=0?'up':'dn'}">${v>=0?'▲':'▼'} ${Math.abs(v)} %</span>`;
function bars(items,fmt,color){const mx=Math.max(1,...items.map(i=>i[1]));return `<div class="hb">${items.map(([l,v])=>`<div class="hbr"><span class="hbl">${esc(l)}</span><span class="hbb"><i style="width:${Math.round(v/mx*100)}%;background:${color||'var(--brand)'}"></i></span><b class="num">${fmt(v)}</b></div>`).join('')||'<p class="muted">Pas de données.</p>'}</div>`}
function vStats(m){
  const R=stRange(stP),cur=stCalc(R.days),prev=stCalc(R.pdays),byDay=R.days.map(d=>[d,sumBy(cur.L.filter(s=>dkey(new Date(s.ts))===d),s=>s.total)]);
  const mx=Math.max(1,...byDay.map(x=>x[1])),avgD=cur.ca/Math.max(1,byDay.filter(x=>x[1]>0).length);
  const svg=`<div class="cols2" role="img" aria-label="Chiffre d’affaires par jour">${byDay.map(([d,v],i)=>`<div class="cc" title="${dshort(d)} : ${eurN(v)}"><i class="cbr ${d===today()?'td':''}" style="height:${Math.max(v?3:0,Math.round(v/mx*100))}%;animation-delay:${Math.min(i*15,600)}ms"></i>${R.n<=14?`<small>${+d.slice(8)}</small>`:''}</div>`).join('')}<u class="avgl" style="bottom:calc(${Math.round(avgD/mx*100)}% * .86 + 22px)"></u></div>`;
  const cats={};cur.L.forEach(s=>s.lines.forEach(l=>{const c=cat(l.cat).name;cats[c]=(cats[c]||0)+l.ttc}));
  const catL=Object.entries(cats).sort((a,b)=>b[1]-a[1]),catT=sumBy(catL,x=>x[1])||1;
  const prods={};cur.L.forEach(s=>s.lines.forEach(l=>{const p=prods[l.name]=prods[l.name]||{q:0,v:0};p.q+=l.qty;p.v+=l.ttc}));
  const top=Object.entries(prods).sort((a,b)=>b[1].v-a[1].v).slice(0,8);
  const pays={};cur.L.forEach(s=>s.pay.forEach(p=>{pays[METHODS[p.m]||p.m]=(pays[METHODS[p.m]||p.m]||0)+p.amt}));
  // heures de pointe : sauteurs par jour de semaine x heure
  const heat={},hrs=[];for(let h=S.settings.open;h<S.settings.close;h++)hrs.push(h);
  cur.L.forEach(s=>{if(!s.slot)return;const [d,mm]=s.slot.split('|'),w=(new Date(d+'T12:00').getDay()+6)%7,h=Math.floor(+mm/60);heat[w+'|'+h]=(heat[w+'|'+h]||0)+(s.jumpers||0)});
  const hm2=Math.max(1,...Object.values(heat));
  const dn=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];
  const heatH=`<div class="heat" style="--c:${hrs.length}"><span></span>${hrs.map(h=>`<b>${h}h</b>`).join('')}${dn.map((n,w)=>`<b class="hd">${n}</b>${hrs.map(h=>{const v=heat[w+'|'+h]||0;return `<i style="--a:${(v/hm2).toFixed(2)}" title="${n} ${h}h : ${v} ${PLUR()}">${v||''}</i>`}).join('')}`).join('')}</div>`;
  // contrôle / qualité
  const chk=R.days.filter(d=>S.checks[d]&&S.checks[d].done).length,past=R.days.filter(d=>d<=today()).length;
  const inc=S.incidents.filter(x=>x.date>=R.from).length,mn=S.maint.filter(x=>x.statut!=='Terminé').length;
  const low=Object.entries(S.stock||{}).filter(([id,s])=>s.q<=s.min).length;
  const withCl=cur.L.filter(s=>s.clientId).length;
  const kp=(l,v,d,sub)=>`<div class="kpi st"><div class="l">${l}</div><div class="v num" data-count>${v}</div><div class="sub2">${dTag(d)} ${sub||''}</div></div>`;
  m.innerHTML=head('Statistiques')+`<div class="seg stseg">${stPeriods.map(([k,l])=>`<button class="${stP===k?'on':''}" data-act="stp" data-k="${k}">${l}</button>`).join('')}</div>
   <div class="kpis st6">${kp('Chiffre d’affaires',eurN(cur.ca),dlt(cur.ca,prev.ca),'vs période précédente')}${kp('Tickets',cur.n,dlt(cur.n,prev.n))}${kp('Panier moyen',eurN(cur.avg),dlt(cur.avg,prev.avg))}${kp(CAPP(),cur.jp,dlt(cur.jp,prev.jp))}${kp('CA par sauteur',eurN(cur.perJ),dlt(cur.perJ,prev.perJ))}${kp('Clients identifiés',cur.n?Math.round(withCl/cur.n*100)+' %':'–',null,'des tickets')}</div>
   ${aiOk()?`<div class="card ai-sum"><button class="btn ai" data-act="stai" ${ctl.busy?'disabled':''}>${ic('wave')}Résumé et conseils IA</button><p class="aiout" id="stai">${esc(ctl.stAi||'')}</p></div>`:''}
   <div class="card"><div class="mtitle"><h3>Chiffre d’affaires par jour</h3><span class="muted">moyenne ${eurN(avgD)} · ligne orange</span></div><div class="bchw">${svg}</div></div>
   <div class="cols"><div class="card"><h3>Ventes par catégorie</h3>${bars(catL.map(([c,v])=>[c+' · '+Math.round(v/catT*100)+' %',v]),eurN)}</div>
    <div class="card"><h3>Produits les plus vendus</h3>${bars(top.map(([n,p])=>[n+' ×'+p.q,p.v]),eurN,'var(--pay)')}</div></div>
   <div class="card"><h3>Heures de pointe <span class="muted" style="font-weight:500">${PLUR()} par créneau</span></h3><div class="heatw">${heatH}</div></div>
   <div class="cols"><div class="card"><h3>Modes de paiement</h3>${bars(Object.entries(pays).sort((a,b)=>b[1]-a[1]),eurN)}</div>
    <div class="card"><h3>Sécurité et exploitation</h3><div class="mini"><div><b class="num">${chk}/${past}</b><span>contrôles quotidiens validés</span></div><div><b class="num">${inc}</b><span>incident${inc>1?'s':''} déclaré${inc>1?'s':''}</span></div><div><b class="num">${mn}</b><span>maintenance${mn>1?'s':''} ouverte${mn>1?'s':''}</span></div><div><b class="num">${low}</b><span>produit${low>1?'s':''} à réapprovisionner</span></div></div></div></div>`;
  m.querySelectorAll('[data-count]').forEach(countUp);
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act="stp"],[data-act="stai"]');if(!b)return;
  if(b.dataset.act==='stp'){stP=b.dataset.k;vStats($('#main'));return}
  if(!SAMPLE)return;const R=stRange(stP),c=stCalc(R.days),p=stCalc(R.pdays);ctl.stAi='Analyse en cours…';$('#stai').textContent=ctl.stAi;
  try{ctl.busy=true;const r=await SAMPLE(AIRULES+`\nPériode : ${R.n} jours. CA ${eurN(c.ca)} (avant : ${eurN(p.ca)}), ${c.n} tickets, ${c.jp} sauteurs, panier moyen ${eurN(c.avg)}.\n${aiCtx()}\nDonne 3 constats clés et 3 actions concrètes pour augmenter le chiffre d’affaires ou mieux remplir les créneaux creux. Maximum 140 mots.`,{modelTier:'default',onText:({text})=>{const el=$('#stai');if(el)el.textContent=text}});ctl.stAi=r.text}
  catch(x){ctl.stAi=AIERR[x.code]||'L’assistant est indisponible.';const el=$('#stai');if(el)el.textContent=ctl.stAi}ctl.busy=false});
function countUpBase(el){
  const txt=el.textContent,mt=txt.match(/[\d   ]+(?:,\d+)?/);if(!mt)return;
  const raw=mt[0],dec=(raw.split(',')[1]||'').length,val=parseFloat(raw.replace(/[\s  ]/g,'').replace(',','.'));if(!isFinite(val)||val===0)return;
  const pre=txt.slice(0,mt.index),post=txt.slice(mt.index+raw.length),t0=performance.now(),D=700;
  const f=v=>v.toLocaleString('fr-FR',{minimumFractionDigits:dec,maximumFractionDigits:dec});
  const step=t=>{const k=Math.min(1,(t-t0)/D),e=1-Math.pow(1-k,3);el.textContent=pre+f(val*e)+post;if(k<1)requestAnimationFrame(step)};requestAnimationFrame(step);
}
NAV.splice(NAV.length-1,0,['stats','Statistiques','chart','Stats']);VIEWS.stats=vStats;
MTL.splice(MTL.length-1,0,['Statistiques','chart','stats','',[]]);

/* ---- inventaire ---- */
let invCat='all',invCount=false;
const stk=()=>S.stock||(S.stock={});
function decStock(sale){let alert=[];sale.lines.forEach(l=>{const s=stk()[l.pid];if(!s)return;s.q=Math.max(0,s.q-l.qty);if(s.q<=s.min)alert.push(l.name)});
  if(alert.length)setTimeout(()=>toast('Stock bas : '+alert.slice(0,3).join(', ')),1200)}
function afterSaleV0(sale,c){afterSaleBase(sale,c);try{decStock(sale)}catch(e){}}
function stStatus(s){return s.q<=0?['Rupture','bad']:s.q<=s.min?['Bas','warn']:['OK','ok']}
function vInventaire(m){
  const ad=canEdit()||perm('gestion:inventaire'),T=Object.keys(stk());
  const tracked=S.products.filter(p=>stk()[p.id]&&(invCat==='all'||p.cat===invCat));
  const rup=T.filter(id=>stk()[id].q<=0).length,bas=T.filter(id=>stk()[id].q>0&&stk()[id].q<=stk()[id].min).length;
  const un=S.products.filter(p=>!stk()[p.id]&&p.active);
  const last=(S.invLog||[]).slice(-1)[0];
  m.innerHTML=`<div class="kpis st6" style="margin-bottom:12px"><div class="kpi st"><div class="l">Produits suivis</div><div class="v num">${T.length}</div></div><div class="kpi st"><div class="l">Stock bas</div><div class="v num" style="color:var(--pay)">${bas}</div></div><div class="kpi st"><div class="l">Ruptures</div><div class="v num" style="color:var(--bad)">${rup}</div></div><div class="kpi st"><div class="l">Dernier inventaire</div><div class="v" style="font-size:18px">${last?dshort(dkey(new Date(last.ts))):'Jamais'}</div></div></div>
   <div class="impo"><div class="chips" style="margin:0">${[{id:'all',name:'Tout'},...CATS].map(c=>`<button class="chip ${invCat===c.id?'on':''}" data-act="invcat" data-id="${c.id}">${c.name}</button>`).join('')}</div>
    <span class="acts">${ad?`<button class="btn ${invCount?'':'primary'}" data-act="invmode">${invCount?'Annuler':'Faire l’inventaire'}</button>`:''}${invCount?'<button class="btn primary" data-act="invok">Valider l’inventaire</button>':''}<button class="btn" data-act="invlist">Liste de réapprovisionnement</button></span></div>
   <div class="card">${tracked.length?tracked.map(p=>{const s=stk()[p.id],[sl,sc]=stStatus(s);return `<div class="row inv"><span class="grow"><b>${esc(p.name)}</b><span class="muted">${esc(p.scat||cat(p.cat).name)}</span></span><span class="pill ${sc}">${sl}</span>
     ${invCount?`<label class="muted">Compté</label><input class="qin" type="number" min="0" data-invc="${p.id}" value="${s.q}">`:`<span class="qty">${ad?`<button class="btn" data-act="invd" data-id="${p.id}" data-d="-1" aria-label="Moins">${ic('minus')}</button>`:''}<b class="num qn">${s.q}</b>${ad?`<button class="btn" data-act="invd" data-id="${p.id}" data-d="1" aria-label="Plus">${ic('plus')}</button>`:''}</span>`}
     <label class="muted" title="Alerte sous ce seuil">Seuil</label><input class="qin" type="number" min="0" data-invmin="${p.id}" value="${s.min}" ${ad?'':'disabled'}>${ad?`<button class="btn" data-act="invoff" data-id="${p.id}" aria-label="Ne plus suivre">${ic('x')}</button>`:''}</div>`}).join(''):'<p class="muted">Aucun produit suivi dans cette catégorie.</p>'}</div>
   ${ad&&un.length?`<div class="card" style="margin-top:14px"><h3>Ajouter au suivi</h3><div class="tgs">${un.slice(0,24).map(p=>`<button class="tg" data-act="invon" data-id="${p.id}">${ic('plus')} ${esc(p.name)}</button>`).join('')}</div></div>`:''}`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act^="inv"]');if(!b)return;const a=b.dataset.act,id=b.dataset.id;
  if(a==='invcat'){invCat=id;vInventaire($('#sub'));return}
  if(a==='invlist'){const L=Object.entries(stk()).filter(([i,s])=>s.q<=s.min).map(([i,s])=>`${S.products.find(p=>p.id===i).name} : ${s.q} en stock (seuil ${s.min})`);showModal(`${mh('À réapprovisionner')}${L.length?`<div class="receipt" style="text-align:left">${L.map(esc).join('<br>')}</div>`:'<p class="muted">Rien à commander pour le moment.</p>'}<button class="btn primary" data-act="close" style="width:100%;margin-top:10px">Fermer</button>`);return}
  if(!(canEdit()||perm('gestion:inventaire')))return;
  if(a==='invd'){const s=stk()[id];s.q=Math.max(0,s.q+ +b.dataset.d);save();vInventaire($('#sub'))}
  else if(a==='invoff'){delete stk()[id];save();vInventaire($('#sub'))}
  else if(a==='invon'){stk()[id]={q:0,min:5};save();vInventaire($('#sub'))}
  else if(a==='invmode'){invCount=!invCount;vInventaire($('#sub'))}
  else if(a==='invok'){const diffs=[];document.querySelectorAll('[data-invc]').forEach(i=>{const s=stk()[i.dataset.invc],v=Math.max(0,+i.value||0);if(v!==s.q){diffs.push({pid:i.dataset.invc,from:s.q,to:v});s.q=v}});
    (S.invLog=S.invLog||[]).push({id:uid(),ts:Date.now(),by:ME?ME.name:'',diffs});invCount=false;save();vInventaire($('#sub'));toast(diffs.length?diffs.length+' écart(s) corrigé(s)':'Inventaire validé : aucun écart')}
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.invmin&&(canEdit()||perm('gestion:inventaire'))){stk()[t.dataset.invmin].min=Math.max(0,+t.value||0);save();vInventaire($('#sub'))}});
TABS.gestion.splice(1,0,['inventaire','Inventaire']);SUBS.inventaire=vInventaire;

/* ---- devis ---- */
let qd=null;
const quotes=()=>S.quotes||(S.quotes=[]);
const qTot=q=>q.lines.reduce((a,l)=>a+Math.round(l.price*100)*l.qty,0);
const QST=[['draft','Brouillon',''],['sent','Envoyé','warn'],['ok','Accepté','ok'],['no','Refusé','bad']];
function quoteNo(){const y=new Date().getFullYear(),n=quotes().filter(q=>String(q.no).includes('-'+y+'-')).length+1;return 'D-'+y+'-'+String(n).padStart(3,'0')}
function vDevis(m){
  const L=[...quotes()].sort((a,b)=>b.ts-a.ts),open=L.filter(q=>q.status==='sent').reduce((a,q)=>a+qTot(q),0);
  m.innerHTML=`<div class="impo"><span><b class="num">${eurN(open)}</b> de devis en attente de réponse</span><button class="btn primary" data-act="qnew">${ic('plus')}Nouveau devis</button></div>
   <div class="card">${L.length?L.map(q=>{const st=QST.find(x=>x[0]===q.status);return `<div class="row"><span class="grow"><b>${esc(q.no)} · ${esc(q.title||'Devis')}</b><span class="muted">${esc(q.name||'Client')} · ${q.date?dshort(q.date):'date à définir'} · ${q.guests||0} invités</span></span><b class="num">${eurN(qTot(q))}</b><span class="pill ${st[2]}">${st[1]}</span><button class="btn" data-act="qopen" data-id="${q.id}">Ouvrir</button><button class="btn" data-act="qpdf" data-id="${q.id}">PDF</button></div>`}).join(''):'<p class="muted">Aucun devis. Créez-en un pour un anniversaire, une privatisation ou un team building.</p>'}</div>`;
}
function qForm(){
  const q=qd,pr=S.products.filter(p=>p.active&&(p.event||p.cat==='event'||p.cat==='gestion'));
  showModal(`${mh(q.fresh?'Nouveau devis':'Devis '+q.no)}<form id="qform">
   <div class="two">${fld('Client',`<input data-q="name" list="qcl" value="${esc(q.name)}" placeholder="Nom du client"><datalist id="qcl">${S.clients.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist>`)}${fld('E-mail',`<input data-q="email" type="email" value="${esc(q.email||'')}">`)}</div>
   <div class="two">${fld('Intitulé',`<input data-q="title" value="${esc(q.title)}" placeholder="Anniversaire, team building…">`)}${fld('Date prévue',`<input data-q="date" type="date" value="${q.date||''}">`)}</div>
   <div class="two">${fld('Invités',`<input data-q="guests" type="number" min="0" value="${q.guests||''}">`)}${fld('Valable jusqu’au',`<input data-q="valid" type="date" value="${q.valid||''}">`)}</div>
   <div class="field"><label>Lignes</label>${q.lines.map((l,i)=>`<div class="qline"><input data-ql="${i}:label" value="${esc(l.label)}" placeholder="Désignation"><input data-ql="${i}:qty" type="number" min="1" value="${l.qty}" style="width:64px"><input data-ql="${i}:price" inputmode="decimal" value="${l.price}" style="width:92px" aria-label="Prix TTC"><button type="button" class="btn" data-act="qdl" data-i="${i}" aria-label="Retirer">${ic('x')}</button></div>`).join('')}
    <div class="acts"><select id="qadd"><option value="">Ajouter un produit…</option>${pr.map(p=>`<option value="${p.id}">${esc(p.name)} · ${eurN(p.price)}</option>`).join('')}</select><button type="button" class="btn" data-act="qaddfree">${ic('plus')}Ligne libre</button></div></div>
   ${fld('Notes et conditions',`<textarea data-q="notes" rows="2">${esc(q.notes||'')}</textarea>`)}
   <p class="qtot">Total TTC <b class="num">${eurN(qTot(q))}</b></p>
   ${fld('Statut',`<div class="tgs">${QST.map(s=>`<button type="button" class="tg ${q.status===s[0]?'on':''}" data-act="qst" data-v="${s[0]}">${s[1]}</button>`).join('')}</div>`)}
   <div class="acts"><button class="btn primary" type="submit">Enregistrer</button><button class="btn" type="button" data-act="qpdfd">PDF</button>${q.status==='ok'&&!q.evDone?`<button class="btn" type="button" data-act="qev">Créer l’événement</button>`:''}${q.fresh?'':`<button class="btn danger" type="button" data-act="qdel">Supprimer</button>`}</div></form>`);
}
function qPdf(q){return['Devis '+q.no,pdfBuild('DEVIS '+q.no,dfr(dkey(new Date(q.ts))),'DEVIS',w=>{
  w.sec('Client');w.kv('Nom',q.name);w.kv('E-mail',q.email);w.sec('Prestation');w.kv('Intitulé',q.title);w.kv('Date prévue',q.date?dfr(q.date):'à définir');w.kv('Invités',q.guests);
  w.sec('Détail');q.lines.forEach(l=>w.kv(l.qty+' x '+l.label,eurN(Math.round(l.price*100)*l.qty)));w.gap(6);w.kv('TOTAL TTC',eurN(qTot(q)));
  if(q.valid)w.kv('Valable jusqu’au',dfr(q.valid));if(q.notes)w.kv('Conditions',q.notes);w.gap(8);w.p('Pour accord, merci de retourner ce devis daté et signé, précédé de la mention « Bon pour accord ».',9);w.sig('Bon pour accord (date et signature du client)','')})]}
function qSyncForm(){document.querySelectorAll('[data-q]').forEach(i=>{qd[i.dataset.q]=i.type==='number'?+i.value:i.value});
  document.querySelectorAll('[data-ql]').forEach(i=>{const [n,f]=i.dataset.ql.split(':'),l=qd.lines[+n];if(!l)return;l[f]=f==='label'?i.value:f==='qty'?Math.max(1,+i.value||1):parseFloat(String(i.value).replace(',','.'))||0})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act^="q"]');if(!b)return;const a=b.dataset.act;if(!/^q(new|open|pdf|pdfd|dl|addfree|st|ev|del)$/.test(a))return;
  if(a==='qnew'){qd={id:uid(),no:quoteNo(),name:'',email:'',title:'',date:'',guests:10,valid:addDays(today(),15),notes:'Acompte de 30 % à la réservation.',lines:[],status:'draft',ts:Date.now(),fresh:true};qForm();return}
  if(a==='qopen'){qd=JSON.parse(JSON.stringify(quotes().find(x=>x.id===b.dataset.id)));qForm();return}
  if(a==='qpdf'){const r=qPdf(quotes().find(x=>x.id===b.dataset.id));saveBytes(r[0]+'.pdf',r[1]);return}
  if(!qd)return;qSyncForm();
  if(a==='qpdfd'){const r=qPdf(qd);saveBytes(r[0]+'.pdf',r[1])}
  else if(a==='qdl'){qd.lines.splice(+b.dataset.i,1);qForm()}
  else if(a==='qaddfree'){qd.lines.push({label:'',qty:1,price:0});qForm()}
  else if(a==='qst'){qd.status=b.dataset.v;qForm()}
  else if(a==='qdel'){const qid=qd.id;askYes('Supprimer ce devis ?',()=>{S.quotes=quotes().filter(x=>x.id!==qid);save();vDevis($('#sub'))},'Supprimer')}
  else if(a==='qev'){const r=Object.keys(ROOMS)[0],cl=S.clients.find(c=>c.name===qd.name);S.events.push({id:uid(),date:qd.date||today(),h:14,dur:2,room:r,title:qd.title||'Événement',guests:qd.guests||10,pack:'',clientId:cl?cl.id:null,sale:qd.no});qd.evDone=true;toast('Événement créé dans le planning')}
});
document.addEventListener('change',e=>{if(e.target.id==='qadd'&&qd&&e.target.value){qSyncForm();const p=S.products.find(x=>x.id===e.target.value);qd.lines.push({label:p.name,qty:1,price:p.price/100});qForm()}
  else if(qd&&(e.target.dataset.ql||e.target.dataset.q)){qSyncForm();const t=document.querySelector('.qtot b');if(t)t.textContent=eurN(qTot(qd))}});
document.addEventListener('submit',e=>{if(e.target.id!=='qform'||!qd)return;e.preventDefault();qSyncForm();if(!qd.name.trim()){toast('Indiquez le client');return}
  const q={...qd};delete q.fresh;const i=quotes().findIndex(x=>x.id===q.id);i<0?quotes().push(q):quotes()[i]=q;save();qd=null;closeModal();vDevis($('#sub'));toast('Devis enregistré')});
TABS.resa.push(['devis','Devis']);SUBS.devis=vDevis;

/* ---- recherche IA texte et voix ---- */
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
function aiCtx2(){
  const all=canAll(),me=ME&&ME.staffId?S.staff.find(s=>s.id===ME.staffId):null,t=today();
  let o=`Utilisateur connecté : ${ME?ME.name:'?'}${me?' (fiche employé : '+me.name+')':''}, ${isAdmin()?'administrateur':'opérateur'}. Aujourd’hui : ${dlong(t)} (${t}).\nÉtablissement : ${S.settings.name}.\n`;
  o+='Horaires et planning de l’équipe sur 8 jours :\n';
  for(let i=0;i<8;i++){const d=addDays(t,i),h=hoursFor(d),eq=S.staff.filter(s=>all||(me&&s.id===me.id)).map(s=>{const lv=onLeave(s.id,d),l=lv?'en congé':shiftLabel(d,s.id);return l?s.name+' '+l:''}).filter(Boolean);
    o+=`- ${dlong(d)} (${d}) : ${h.closed?'établissement fermé':'ouvert '+hmm(h.o)+'-'+hmm(h.c)}${h.label?' ('+h.label+')':''} ; équipe : ${eq.join(', ')||'personne de prévu'}${isAdmin()&&evOn(d).length?' ; événements : '+evOn(d).map(e=>e.title+' '+e.guests+' invités').join(', '):''}\n`}
  if(!all)o+='(Cet utilisateur ne peut voir que son propre planning : ne communique pas les horaires des autres.)\n';
  o+='Messages récents de l’équipe : '+(boardL().slice(-5).map(x=>x.name+' : '+x.text).join(' | ')||'aucun')+'\n';
  return o;
}
let aiq=null;
function aiAskModal(prefill){
  showModal(`${mh('Poser une question à l’IA')}<form id="aiqf"><div class="ask"><input id="aiqin" placeholder="ex : je suis Lilou, avec qui je travaille demain ?" autocomplete="off" value="${esc(prefill||'')}">${SR?`<button type="button" class="btn mic" data-act="aimic" aria-label="Dicter">${ic('wave')}</button>`:''}<button class="btn primary" type="submit">Demander</button></div></form>
   <div class="iachips" style="margin-top:10px">${['Avec qui je travaille demain ?','Qui travaille ce week-end ?','Quels événements cette semaine ?','Quand est-on fermé ?'].map(s=>`<button class="btn" data-act="aiex" data-v="${esc(s)}">${s}</button>`).join('')}</div>
   <div class="aians" id="aians"></div>`);setTimeout(()=>{const i=$('#aiqin');if(i)i.focus()},60);
}
async function aiAsk(q){
  const out=$('#aians');if(!out||!q.trim())return;out.textContent='…';
  if(!SAMPLE){out.textContent='L’assistant n’est pas disponible dans cet affichage.';return}
  try{ctl.busy=true;await SAMPLE(AIRULES+'\nRéponds uniquement d’après ces données, en une ou deux phrases claires. Si l’utilisateur dit « je suis X », considère que X est la personne concernée. Si l’information manque, dis-le.\n\n'+aiCtx2()+'\nQuestion : '+q,{cache:false,modelTier:'default',onText:({text})=>{const o=$('#aians');if(o)o.textContent=text}})}
  catch(e){const o=$('#aians');if(o)o.textContent=AIERR[e.code]||'L’assistant est indisponible.'}ctl.busy=false;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="aiq"],[data-act="aiex"],[data-act="aimic"]');if(!b)return;const a=b.dataset.act;
  if(a==='aiq')aiAskModal();
  else if(a==='aiex'){$('#aiqin').value=b.dataset.v;aiAsk(b.dataset.v)}
  else if(a==='aimic'){if(!SR)return;try{const r=new SR();r.lang='fr-FR';r.interimResults=true;b.classList.add('rec');let fin='';
    r.onresult=ev=>{fin=Array.from(ev.results).map(x=>x[0].transcript).join('');$('#aiqin').value=fin};
    r.onerror=()=>{b.classList.remove('rec');toast('Micro indisponible : autorisez-le ou écrivez votre question')};
    r.onend=()=>{b.classList.remove('rec');if(fin.trim())aiAsk(fin)};r.start()}catch(x){toast('Micro indisponible')}}
});
document.addEventListener('submit',e=>{if(e.target.id==='aiqf'){e.preventDefault();aiAsk($('#aiqin').value)}});
