/* ---- import Qweekle (CSV) ---- */
let qwRows=null,qwHead=[];
function csvParse(t){const d=(t.split('\n')[0].match(/;/g)||[]).length>=(t.split('\n')[0].match(/,/g)||[]).length?';':',';const R=[];let r=[],c='',q=false;
  for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch==='"'){if(t[i+1]==='"'){c+='"';i++}else q=false}else c+=ch}else if(ch==='"')q=true;else if(ch===d){r.push(c);c=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&t[i+1]==='\n')i++;r.push(c);c='';if(r.some(x=>x.trim()))R.push(r);r=[]}else c+=ch}
  if(c||r.length){r.push(c);R.push(r)}return R}
const pDate=s=>{s=String(s||'').trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return m[0];m=s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);if(m)return (m[3].length===2?'20'+m[3]:m[3])+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');return ''};
const pTime=s=>{const m=String(s||'').match(/(\d{1,2})\s*[:hH]\s*(\d{2})?/);return m?(+m[1])*60+(+m[2]||0):null};
function vQweekle(m){
  const n=S.sales.filter(s=>s.qw).length,sel=(id)=>`<select id="${id}"><option value="">—</option>${qwHead.map((h,i)=>`<option value="${i}">${esc(h)}</option>`).join('')}</select>`;
  m.innerHTML=`<div class="card" style="margin-bottom:14px"><h3>Planning Qweekle</h3><p class="muted">Importez l’export de vos réservations Qweekle (fichier CSV) : elles apparaissent dans le planning clients pour toute l’équipe, avec leur nombre de participants. Faites-le à nouveau pour mettre à jour.</p>
   <p class="muted" style="margin-top:6px;font-size:13px"><b>Synchronisation automatique :</b> elle demande un accès à l’API de Qweekle et un serveur Lago hébergé. En attendant, l’import par fichier fait le même travail en un clic.</p>
   <div class="acts" style="margin-top:10px"><label class="btn primary" for="qwf">${ic('plus')}Choisir un fichier CSV</label><input type="file" id="qwf" accept=".csv,text/csv,text/plain" hidden>${n?`<button class="btn" data-act="qwclear">Supprimer les ${n} réservations importées</button>`:''}</div></div>
   ${qwRows?`<div class="card"><h3>Associer les colonnes (${qwRows.length} lignes)</h3><div class="g2">${fld('Date',sel('qwd'))}${fld('Heure de début',sel('qwh'))}${fld('Nombre de personnes',sel('qwn'))}${fld('Durée en minutes (facultatif)',sel('qwu'))}${fld('Nom du client (facultatif)',sel('qwc'))}</div><button class="btn primary" data-act="qwgo">Importer</button></div>`:''}`;
  if(qwRows){const auto=(id,re)=>{const i=qwHead.findIndex(h=>re.test(h.toLowerCase()));if(i>=0)$('#'+id).value=i};auto('qwd',/date|jour/);auto('qwh',/heure|début|debut|horaire/);auto('qwn',/nb|nombre|pers|particip|quantit/);auto('qwu',/dur/);auto('qwc',/client|nom/)}
}
document.addEventListener('change',e=>{if(e.target.id!=='qwf'||!e.target.files[0])return;const fr=new FileReader();fr.onload=()=>{const R=csvParse(String(fr.result));if(R.length<2){toast('Fichier vide ou illisible');return}qwHead=R[0];qwRows=R.slice(1);vQweekle($('#sub'))};fr.readAsText(e.target.files[0],'UTF-8')});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="qwgo"],[data-act="qwclear"]');if(!b||!isAdmin())return;
  if(b.dataset.act==='qwclear'){S.sales=S.sales.filter(s=>!s.qw||s.wb);save();vQweekle($('#sub'));toast('Réservations importées supprimées');return}
  const ix=id=>$('#'+id).value===''?-1:+$('#'+id).value,D=ix('qwd'),H=ix('qwh'),N=ix('qwn'),U=ix('qwu'),C=ix('qwc');if(D<0||H<0||N<0){toast('Associez au moins la date, l’heure et le nombre de personnes');return}
  S.sales=S.sales.filter(s=>!s.qw||s.wb);let k=0;
  qwRows.forEach(r=>{const d=pDate(r[D]),t=pTime(r[H]),j=parseInt(r[N]);if(!d||t==null||!j)return;const st=Math.floor(t/15)*15;
    S.sales.push({id:uid(),no:'QW-'+(++k),ts:new Date(d+'T'+hmm(st)+':00').getTime(),lines:[],sub:0,disc:0,total:0,vat:{},pay:[],clientId:null,slot:d+'|'+st,dur:U>=0?(parseInt(r[U])||60):60,jumpers:j,qw:true,qwName:C>=0?r[C]:''})});
  save();qwRows=null;vQweekle($('#sub'));toast(k+' réservation(s) importée(s)')});
TABS.params.push(['pqw','Qweekle']);SUBS.pqw=vQweekle;

