/* ---------- S. contrôles : saisie réservée à l'admin + 1 compte désigné, consultation pour tous ---------- */
const ctlMode=()=>S.settings.ctlV2?(S.settings.ctlAcc||''):'*';
const canCtl=()=>isAdmin()||!!(ME&&(ctlMode()==='*'||ctlMode()===ME.id));
const CTL_RESTRICTED=['visuel','mensuel','maint'];
const CTL_OK=['m_pdf','m_mon','m_yr','m_mntopen','m_mntcancel'];
function ctlWho(){const a=accs().find(x=>x.id===S.settings.ctlAcc&&x.status==='active');return a?a.name:''}
function roCtl(m,t){
  if(canCtl()||!CTL_RESTRICTED.includes(t))return;
  m.querySelectorAll('input,select,textarea').forEach(i=>{i.disabled=true});
  m.querySelectorAll('button').forEach(b=>{const a=b.dataset.act||'';if(!CTL_OK.includes(a)){b.disabled=true;b.setAttribute('aria-disabled','true')}});
  const w=ctlWho();
  m.insertAdjacentHTML('afterbegin',`<div class="banner"><span>Consultation seule : seuls l’administrateur${w?' et '+esc(w):''} peuvent remplir cette partie.</span></div>`);
}
CSUB.forEach(([t])=>{const f=SUBS[t];if(!f)return;SUBS[t]=m=>{f(m);roCtl(m,t)}});
/* garde-fou : aucune action d'écriture sans droit */
document.addEventListener('click',e=>{
  if(canCtl()||view!=='controle'||!CTL_RESTRICTED.includes(tab.controle))return;
  const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act;
  if(['chk','allok','chkdone','chkopen'].includes(a)||(a.startsWith('m_')&&!CTL_OK.includes(a))){e.preventDefault();e.stopImmediatePropagation();toast('Réservé à l’administrateur et au compte désigné')}
},true);
['change','input'].forEach(ev=>document.addEventListener(ev,e=>{
  if(canCtl()||view!=='controle'||!CTL_RESTRICTED.includes(tab.controle)||!e.target.closest('#sub'))return;
  e.stopImmediatePropagation();
},true));
/* réglage : compte désigné (Paramètres › Comptes) */
