const SHEET_SCRIPT=`function doPost(e){
  var d=JSON.parse(e.postData.contents);
  var ss=SpreadsheetApp.getActiveSpreadsheet();
  var sh=ss.getSheetByName(d.type);
  if(!sh){
    sh=ss.insertSheet(d.type);
    sh.appendRow(['ID','Date','Heure','Rédacteur','Résumé','Détails','Statut','Reçu le']);
    sh.setFrozenRows(1);sh.getRange(1,1,1,8).setFontWeight('bold');
  }
  var row=[d.id,d.date,d.time,d.author,d.summary,d.details,d.status,new Date()];
  var n=sh.getLastRow(),i=-1;
  if(n>1){i=sh.getRange(2,1,n-1,1).getValues().map(function(r){return r[0]}).indexOf(d.id)}
  if(i>=0){sh.getRange(i+2,1,1,row.length).setValues([row])}else{sh.appendRow(row)}
  return ContentService.createTextOutput('ok');
}`;
/* --- construction des lignes --- */
const ckLabel=k=>{for(const g of CHECKS){const f=g.items.find(i=>i[0]===k);if(f)return f[1]}return k};
function sheetItem(kind,rec,key){
  if(kind==='visuel'){
    const ko=Object.entries(rec.items||{}).filter(([k,v])=>v&&v.s==='ko'),nc=ko.length;
    return{id:'visuel-'+key,type:'Contrôle quotidien',date:key,time:rec.ts?hm(rec.ts):'',author:rec.by||'',
      summary:nc?nc+' point'+(nc>1?'s':'')+' non conforme'+(nc>1?'s':''):'Tout conforme',
      details:(ko.length?ko.map(([k,v])=>ckLabel(k)+' : '+(v.note||'')).join(' | ')+' | ':'')+(rec.press||rec.press2?(rec.press2!==undefined?'Pression airbag 1 : '+(rec.press||'-')+' hPa | Pression airbag 2 : '+(rec.press2||'-')+' hPa':'Pression airbags : '+rec.press):''),status:rec.done?'Validé':'En cours'};
  }
  if(kind==='mensuel'){
    const nc=MPTS.map((p,i)=>rec.items&&rec.items[i]==='NC'?p:null).filter(Boolean);
    return{id:'mensuel-'+key,type:'Contrôle mensuel',date:rec.date||key,time:rec.signed?hm(rec.signed):'',author:rec.writer||rec.by||'',
      summary:nc.length?nc.length+' point'+(nc.length>1?'s':'')+' non conforme'+(nc.length>1?'s':''):'Tout conforme',
      details:[nc.length?'NC : '+nc.join(', '):'',rec.obs?'Observations : '+rec.obs:'',rec.fix?'Actions : '+rec.fix:'',rec.zone?'Zone : '+rec.zone:''].filter(Boolean).join(' | '),status:rec.signed?'Signé':'En cours'};
  }
  if(kind==='incident'){
    return{id:'incident-'+rec.id,type:'Rapport d’incident',date:rec.date,time:rec.time||'',author:rec.writer||'',
      summary:[rec.who,[rec.prenom,rec.nom].filter(Boolean).join(' '),(rec.types||[]).join(', ')].filter(Boolean).join(' · '),
      details:[rec.desc,rec.pain!=null?'Douleur : '+rec.pain+'/10':'',(rec.secours||[]).length?'Secours : '+rec.secours.join(', '):'',rec.secouriste?'Secouriste : '+rec.secouriste:'',rec.notes].filter(Boolean).join(' | '),status:'Signé'};
  }
  return{id:'maint-'+rec.id,type:'Rapport d’intervention',date:rec.date,time:rec.ts?hm(rec.ts):'',author:rec.tech||'',
    summary:[mntEq(rec),rec.type].filter(Boolean).join(' · '),
    details:[rec.pb?'Problème : '+rec.pb:'',rec.action?'Action : '+rec.action:'',rec.pieces?'Pièces : '+rec.pieces:'',rec.min?rec.min+' min':''].filter(Boolean).join(' | '),status:rec.statut||''};
}
async function sheetPost(item){
  await fetch(S.settings.sheetUrl,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(item)});
}
function sheetStatus(t){S.settings.sheetStatus=t;save();const e=$('#y_st');if(e)e.textContent=t}
async function sheetFlush(){
  if(!S.settings.sheetUrl)return;
  const q=(S.sheetQ||[]).slice();if(!q.length)return;
  let ok=0;const keep=[];
  for(const it of q){try{await sheetPost(it);ok++}catch(e){keep.push(it)}}
  S.sheetQ=keep;
  sheetStatus(keep.length?ok+' envoyé'+(ok>1?'s':'')+', '+keep.length+' en attente (pas de connexion ou adresse refusée) · '+new Date().toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Dernier envoi réussi : '+new Date().toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}));
  save();
}
function sheetQueue(item){
  if(!S.settings.sheetUrl)return;
  S.sheetQ=(S.sheetQ||[]).filter(x=>x.id!==item.id);S.sheetQ.push(item);save();sheetFlush();
}
