/* ---------- Z. synchronisation en ligne (Firebase Realtime Database, sans SDK) ---------- */
const CKEY='lago-cloud',CBOX='lago-cloud-box';
const CLOUD_SKIP=['held'],LOCAL_KEYS=['seen'];
const JM='\u0001J',NM='\u0001N',EA='\u0001A',EO='\u0001O';
const isO=x=>!!x&&typeof x==='object';
const same=(a,b)=>a===b||(isO(a)&&isO(b)&&JSON.stringify(a)===JSON.stringify(b));
function cloudCfg(){try{return JSON.parse(localStorage.getItem(CKEY)||'null')}catch(e){return null}}
function cloudOn(){const c=cloudCfg();return !!(c&&c.u&&c.r)}
function cloudSet(c){try{c?localStorage.setItem(CKEY,JSON.stringify(c)):localStorage.removeItem(CKEY)}catch(e){}}
const KBAD=/[.$#\[\]\/%\x00-\x1f\x7f]/,KBADG=/[.$#\[\]\/%\x00-\x1f\x7f]/g,hasOwn=Object.prototype.hasOwnProperty;
const kEnc=k=>{k=String(k);return k===''?'%00':KBAD.test(k)?k.replace(KBADG,c=>'%'+c.charCodeAt(0).toString(16).toUpperCase().padStart(2,'0')):k};
const kDec=k=>k==='%00'?'':k.indexOf('%')<0?k:k.replace(/%([0-9A-F]{2})/g,(_,h)=>String.fromCharCode(parseInt(h,16)));
/* données Lago -> arbre Firebase */
function proj(v,key){
  if(v===undefined||typeof v==='function')return undefined;
  if(v===null)return NM;
  if(typeof v==='number')return isFinite(v)?v:undefined;
  if(typeof v!=='object')return v;
  if(Array.isArray(v)){
    if(!v.length)return EA;
    const ids=new Set();let allTs=true;
    for(let i=0;i<v.length;i++){
      const e=v[i];
      if(!(isO(e)&&!Array.isArray(e)&&typeof e.id==='string'&&e.id&&!('_a' in e))||ids.has(e.id))return JM+JSON.stringify(v);
      ids.add(e.id);if(typeof e.ts!=='number')allTs=false;
    }
    const o={_a:1};
    for(let i=0;i<v.length;i++){const e=v[i],p=proj(e);if(p!==undefined)o[kEnc(e.id)]=p}
    if(!allTs)o._o=JM+JSON.stringify(v.map(e=>e.id));
    return o;
  }
  const o={};let n=0;
  for(const k in v){if(LOCAL_KEYS.includes(k))continue;const x=v[k],p=typeof x==='string'?x:proj(x);if(p!==undefined){o[kEnc(k)]=p;n++}}
  return n?o:EO;
}
function projS(){const o={};for(const k in S){if(CLOUD_SKIP.includes(k))continue;const p=proj(S[k]);if(p!==undefined)o[kEnc(k)]=p}return o}
/* arbre Firebase -> données Lago */
function dec(n){
  if(typeof n==='string'){if(n===NM)return null;if(n===EA)return [];if(n===EO)return {};if(n.startsWith(JM)){try{return JSON.parse(n.slice(JM.length))}catch(e){return undefined}}return n}
  if(isO(n)){
    if(n._a){
      const items=Object.keys(n).filter(k=>k!=='_a'&&k!=='_o').map(k=>dec(n[k])).filter(x=>isO(x)&&typeof x.id==='string');
      let ord=[];if(typeof n._o==='string'){try{ord=JSON.parse(n._o.slice(JM.length))}catch(e){}}
      const pos=new Map(ord.map((id,i)=>[id,i])),allTs=items.every(x=>typeof x.ts==='number');
      items.sort((a,b)=>{
        if(allTs&&a.ts!==b.ts)return a.ts-b.ts;
        const pa=pos.has(a.id)?pos.get(a.id):1e9,pb=pos.has(b.id)?pos.get(b.id):1e9;
        return pa!==pb?pa-pb:(a.id<b.id?-1:1);
      });
      return items;
    }
    const o={};for(const k in n){const v=dec(n[k]);if(v!==undefined)o[kDec(k)]=v}return o;
  }
  return n;
}
const fixArr=x=>{if(Array.isArray(x)){const o={};x.forEach((v,i)=>{if(v!=null)o[i]=fixArr(v)});return o}if(isO(x)){const o={};for(const k in x)o[k]=fixArr(x[k]);return o}return x};
function setAt(t,parts,val){
  if(!parts.length)return val;
  const o=isO(t)?{...t}:{},h=parts[0],nv=setAt(o[h],parts.slice(1),val);
  if(nv===undefined)delete o[h];else o[h]=nv;
  return Object.keys(o).length?o:undefined;
}
const primT=x=>x!==undefined&&!isO(x);
const hasKeys=o=>{for(const k in o)return true;return false};
function merge3(b,l,r){
  /* serveur inchangé (r identique à la base) ou identique au local : le résultat de la fusion est exactement la version locale */
  if((b===r||l===r)&&(!isO(l)||hasKeys(l)))return l;
  if((isO(b)||isO(l)||isO(r))&&!primT(b)&&!primT(l)&&!primT(r)){
    const o={};let n=0;
    const visit=k=>{const m=merge3(b&&b[k],l&&l[k],r&&r[k]);if(m!==undefined){o[k]=m;n++}};
    if(b)for(const k of Object.keys(b))visit(k);
    if(l)for(const k of Object.keys(l))if(!(b&&hasOwn.call(b,k)))visit(k);
    if(r)for(const k of Object.keys(r))if(!(b&&hasOwn.call(b,k))&&!(l&&hasOwn.call(l,k)))visit(k);
    return n?o:undefined;
  }
  return same(l,b)?r:l;
}
function diffT(r,m,path,out){
  if(r===m)return;
  if(isO(r)&&isO(m)){
    const rk=Object.keys(r);
    for(let i=0;i<rk.length;i++){const k=rk[i],x=r[k],y=m[k];if(x!==y)diffT(x,y,path?path+'/'+k:k,out)}
    const mk=Object.keys(m);
    for(let i=0;i<mk.length;i++){const k=mk[i];if(!hasOwn.call(r,k))diffT(undefined,m[k],path?path+'/'+k:k,out)}
  }
  else if(!same(r,m)){
    /* Firebase refuse une clé vide : à la racine on envoie chaque clé de premier niveau séparément */
    if(path===''){
      if(isO(m)){for(const k of Object.keys(m))out[k]=m[k]===undefined?null:m[k];for(const k of Object.keys(r||{}))if(!(k in m))out[k]=null}
      else if(isO(r)){for(const k of Object.keys(r))out[k]=null}
    }else out[path]=m===undefined?null:m;
  }
}
/* état de la synchronisation */
const CL={R:undefined,B:undefined,fetched:false,ready:false,busy:false,again:false,es:null,state:'off',t:null,ui:false,err:'',last:0,ev:0,ka:75000,away:30000,hid:0,sv:0,okSv:-1,fail:0};
function setCS(s){if(s==='off'&&!CL.offAt)CL.offAt=Date.now();else if(s==='ok')CL.offAt=0;CL.state=s;if(s==='ok')CL.err='';document.querySelectorAll('.zst').forEach(e=>{e.dataset.s=s;e.title=s==='ok'?'':(CL.err||'');const t=e.querySelector('b');if(t)t.textContent=s==='ok'?'Synchronisé':s==='sync'?'Synchronisation…':'Hors ligne'});try{syDraw()}catch(e){}}
/* v64 : si la route réseau principale vers la base ne répond plus (connexion bloquée dans le navigateur : erreur 503 ou attente sans fin),
   on essaie la route équivalente « nom de serveur. » (même base, même adresse) et on la garde tant qu'elle marche. */
const cAltOk=c=>!!c&&/^https:\/\/[^\/:]+\.(firebasedatabase\.app|firebaseio\.com)\/?$/i.test(c.u||'');
const cHostFor=(c,alt)=>c.u.replace(/\/+$/,'')+(alt&&cAltOk(c)?'.':'');
const cBaseFor=(c,alt)=>cHostFor(c,alt)+'/'+c.r;
const cUrl=p=>{const c=cloudCfg();return cBaseFor(c,c.alt)+(p?'/'+p:'')+'.json'};
function cAltSet(alt){const c=cloudCfg();if(c&&!!c.alt!==!!alt){c.alt=!!alt;cloudSet(c);if(CL.ready)setTimeout(cloudListen,0)}}
async function cFetch(ms){
  ms=ms||Math.min(60000,8000*Math.pow(2,Math.min(CL.fail||0,3)));const c=cloudCfg(),alts=cAltOk(c),first=!!c.alt;
  const get=(alt,sig)=>fetch(cBaseFor(c,alt)+'.json',{signal:sig}).then(async r=>{if(!r.ok)throw new Error('http '+r.status);return{j:await r.json(),alt}});
  /* route principale d'abord ; sans réponse après 2,5 s (ou en cas d'erreur), on lance la route alternative en parallèle : la première qui répond gagne */
  const out=await new Promise((resolve,reject)=>{
    const acs=[],errs=[];let done=false,n=0,t2=0,tt=0;
    const end=(f,v)=>{if(done)return;done=true;clearTimeout(t2);clearTimeout(tt);acs.forEach(a=>{try{a.abort()}catch(e){}});f(v)};
    const run=alt=>{n++;const a=new AbortController();acs.push(a);get(alt,a.signal).then(v=>end(resolve,v),e=>{if(done)return;errs.push(e);if(alts&&n<2){clearTimeout(t2);run(!first)}else if(errs.length>=n)end(reject,errs[0])})};
    tt=setTimeout(()=>end(reject,errs[0]||new Error('délai dépassé')),ms);
    run(first);
    if(alts)t2=setTimeout(()=>{if(!done&&n<2)run(!first)},Math.min(2500,ms/3));
  });
  CL.R=out.j===null?undefined:fixArr(out.j);CL.fetched=true;
  if(!!out.alt!==!!c.alt)cAltSet(out.alt);
}
/* envoi des modifications : 10 s maximum par essai, puis l'autre route (sauf refus explicite de la base) */
async function cPatch(patch){
  const c=cloudCfg(),alts=cAltOk(c);
  const send=async alt=>{const ac=new AbortController(),to=setTimeout(()=>ac.abort(),10000);try{const r=await fetch(cBaseFor(c,alt)+'.json',{method:'PATCH',body:JSON.stringify(patch),signal:ac.signal});if(!r.ok)throw new Error('http '+r.status)}finally{clearTimeout(to)}};
  try{await send(!!c.alt)}
  catch(e){if(!alts||/^http 4/.test(String((e&&e.message)||'')))throw e;await send(!c.alt);cAltSet(!c.alt)}
}
function treeToS(T,full){
  if(full)for(const k of Object.keys(S))if(!CLOUD_SKIP.includes(k))delete S[k];
  for(const k in (T||{}))S[kDec(k)]=dec(T[k]);
}
function cloudNormalize(){
  S.settings=Object.assign(defaultSettings(),S.settings||{});
  ['products','clients','sales','closures','events','mails','staff','leaves','plans','maint','incidents','profiles','planArchive','awards','qwres','web','gifts','waivers','accounts','board','passes','promos','entries','mlog'].forEach(k=>{if(!Array.isArray(S[k]))S[k]=[]});
  ['shifts','checks','monthly','stock','hours','devs'].forEach(k=>{if(!isO(S[k])||Array.isArray(S[k]))S[k]={}});
  if(!S.profiles.length)S.profiles=defaultProfiles();
  try{migrateM()}catch(e){}
  number();
}
function applyM(M,L){
  let ch=false;
  for(const k of new Set([...Object.keys(M||{}),...Object.keys(L||{})])){
    if(same(M&&M[k],L&&L[k]))continue;ch=true;
    const key=kDec(k),old=S[key];
    if(M&&M[k]===undefined)delete S[key];else S[key]=dec(M[k]);
    if(key==='accounts'&&Array.isArray(old)&&Array.isArray(S.accounts))S.accounts.forEach(a=>{const o=old.find(x=>x.id===a.id);if(o&&o.seen!==undefined)a.seen=o.seen});
  }
  if(!ch)return false;
  cloudNormalize();
  if(typeof ME!=='undefined'&&ME&&Array.isArray(S.accounts)){const a=S.accounts.find(x=>x.id===ME.id);if(a)ME=a}
  saveBase();
  CL.ui=true;return true;
}
async function cloudStep(){
  const cf=cloudCfg();if(!cf||cf.fresh)throw new Error('connexion initiale non terminée');
  if(!CL.fetched)await cFetch();
  if(Array.isArray(S.sales)){S.sales.sort((x,y)=>(x.ts||0)-(y.ts||0)||(x.id<y.id?-1:1));number()}
  const sv0=CL.sv,L=projS(),M=merge3(CL.B,L,CL.R);
  applyM(M,L);
  const patch={};diffT(CL.R,M,'',patch);
  CL.B=CL.R;
  if(Object.keys(patch).length){
    setCS('sync');
    await cPatch(patch);
    let R=CL.R;for(const p in patch)R=setAt(R,p.split('/'),patch[p]===null?undefined:patch[p]);
    CL.R=R;CL.B=R;
    try{localStorage.removeItem(CBOX)}catch(e){}
  }
  if(CL.sv===sv0){CL.okSv=sv0;try{localStorage.removeItem(CBOX)}catch(e){}}   // rien n'a été modifié pendant l'envoi : plus rien en attente (une boîte restée là serait rejouée au prochain démarrage)
  CL.fail=0;CL.last=Date.now();setCS('ok');
}
async function cloudSync(){
  if(!cloudOn()||!CL.ready)return;
  if(CL.busy){CL.again=true;return}
  CL.busy=true;
  try{do{CL.again=false;await cloudStep()}while(CL.again)}
  catch(e){CL.err=String((e&&e.message)||e);setCS('off');cloudStash();const d=Math.min(60000,8000*Math.pow(2,CL.fail));CL.fail++;setTimeout(()=>cloudKick(CL.fail<=1?d:Math.round(d*(0.85+Math.random()*0.3))),0)}
  CL.busy=false;
}
function cloudKick(ms){if(!cloudOn()||!CL.ready)return;clearTimeout(CL.t);CL.t=setTimeout(cloudSync,ms==null?700:ms)}
const getAt=(t,parts)=>parts.reduce((x,k)=>isO(x)?x[k]:undefined,t);
function cloudStash(){
  if(!CL.ready||!cloudOn())return;
  if(CL.sv===CL.okSv){try{localStorage.removeItem(CBOX)}catch(e){}return}
  try{const p={},o={};diffT(CL.B,projS(),'',p);
    for(const k in p){const v=getAt(CL.B,k.split('/'));o[k]=v===undefined?null:v}
    if(Object.keys(p).length)localStorage.setItem(CBOX,JSON.stringify({n:p,o}));else localStorage.removeItem(CBOX)}catch(e){}
}
function cloudListen(){
  const c=cloudCfg();if(!c)return;if(CL.es)CL.es.close();
  const es=new EventSource(cUrl(''));CL.es=es;CL.ev=Date.now();
  const on=(t,ev)=>{let d;try{d=JSON.parse(ev.data)}catch(e){return}
    const parts=String(d.path||'/').split('/').filter(Boolean);
    if(t==='put')CL.R=setAt(CL.R,parts,d.data===null?undefined:fixArr(d.data));
    else Object.entries(d.data||{}).forEach(([k,v])=>{CL.R=setAt(CL.R,parts.concat(k.split('/')),v===null?undefined:fixArr(v))});
    CL.ev=Date.now();CL.fetched=true;cloudKick(120)};
  es.addEventListener('put',ev=>on('put',ev));es.addEventListener('patch',ev=>on('patch',ev));
  es.addEventListener('keep-alive',()=>{CL.ev=Date.now()});
  es.onopen=()=>{CL.ev=Date.now();if(CL.state==='off')setCS('ok')};es.onerror=()=>setCS('off');
  if(cAltOk(c))setTimeout(()=>{if(CL.es===es&&es.readyState===0&&!CL.busy){CL.fetched=false;cloudKick(0)}},7000);
}
/* flux endormi (veille du téléphone, changement de réseau…) : on le rouvre et on relit la base */
function cloudWake(force,away){
  if(!cloudOn()||!CL.ready)return;
  const es=CL.es,stale=!es||es.readyState===2||!!away||Date.now()-CL.ev>(force?Math.min(40000,CL.ka):CL.ka);
  if(stale){cloudListen();CL.fetched=false;cloudKick(2500)}   // le flux rouvert apporte l'état complet (et relance la synchro à son arrivée) ; sinon lecture directe au bout de 2,5 s
  else if(force)cloudKick(300);
}
setInterval(()=>{if(!document.hidden)cloudWake(false)},5000);
addEventListener('focus',()=>cloudWake(true));
addEventListener('pageshow',e=>{if(e.persisted)cloudWake(true)});
async function cloudBoot(){
  const c=cloudCfg();
  await cFetch(7000);
  c.alt=(cloudCfg()||{}).alt;
  if(c.fresh&&CL.R!==undefined){treeToS(CL.R,true);cloudNormalize();saveBase();CL.B=CL.R;c.fresh=false;delete c.boot;cloudSet(c);CL.ui=true}
  else if(c.fresh){if(c.boot)tplBootstrap(c.boot);c.fresh=false;cloudSet(c)}
  else{
    if(CL.R===undefined){CL.B=undefined}
    else{
      let box=null;try{box=JSON.parse(localStorage.getItem(CBOX)||'null')}catch(e){}
      let M=CL.R;if(box&&box.n)for(const p in box.n)M=setAt(M,p.split('/'),box.n[p]===null?undefined:box.n[p]);
      treeToS(M,true);cloudNormalize();CL.B=CL.R;CL.ui=true;
      saveBase();
    }
  }
  CL.ready=true;migrateImgs();cloudListen();await cloudSync();
}
/* démarrage : avant l’écran de connexion */
function bootGate(){
  window.__lagoUp=1;{const bs=document.getElementById('boot');if(bs)bs.remove()}
  if(/^#cloud=/i.test(location.hash)){const x=joinParse(location.hash);if(x&&tplLinkBusy(x)){window.__joinBlock=1;setTimeout(tplBlockNote,600)}else if(x)cloudSet({u:x.u,r:x.r,fresh:true,boot:x.b?{t:x.t,n:x.n}:undefined});else window.__joinBad=true;history.replaceState(null,'',location.pathname+location.search)}
  if(!cloudOn()){bootGateBase();return}
  const sp=document.createElement('div');sp.id='zsplash';sp.style.cssText='position:fixed;inset:0;z-index:1000;display:grid;place-items:center;background:#1D4FD7;color:#fff;font:600 18px system-ui';sp.textContent='Connexion à l’équipe…';document.body.appendChild(sp);
  cloudBoot().catch(e=>{
    setCS('off');const c=cloudCfg();
    if(c&&c.fresh){toast('Base injoignable : vérifiez la connexion, puis rouvrez l’appli');return}
    /* hors ligne au démarrage : on repart de l’état local, les modifications seront envoyées au retour du réseau */
    let B=projS(),box=null;try{box=JSON.parse(localStorage.getItem(CBOX)||'null')}catch(x){}
    if(box&&box.o)for(const p in box.o)B=setAt(B,p.split('/'),box.o[p]===null?undefined:box.o[p]);
    CL.B=B;CL.R=undefined;CL.fetched=false;CL.ready=true;cloudListen();cloudKick(8000);
  }).finally(()=>{sp.remove();chrome();bootGateBase()});
}
const saveV0=saveBase;
