/* données de démonstration : repérage précis (signature des exemples), pour ne jamais toucher aux vraies données */
const DEMO_CL=['Camille Martin','Lucas Bernard','Inès Dubois','Hugo Petit','Léa Moreau','Nathan Roux'];
const DEMO_EV=['Séminaire Sogimex','Anniversaire de Léo','Anniversaire de Jade','Anniversaire de Noé','Sortie centre de loisirs','Anniversaire d’Emma','Anniversaire de Gabin'];
const isDemoCl=c=>DEMO_CL.includes(c.name)&&/^06 12 34 56 0[1-6]$/.test(c.phone||'');
const isDemoEv=e=>DEMO_EV.includes(e.title);
const isDemoCheck=(d,c)=>!!(c&&c.done&&[13,16,19,22,25,28].some(m=>c.ts===new Date(d+'T09:'+pad(m)+':00').getTime()));
function demoLeaves(){
  const L=S.leaves||[],dd=(a,b)=>Math.round((new Date(b+'T12:00')-new Date(a+'T12:00'))/864e5);
  const a=L.find(l=>l.staffId==='e3'&&l.status==='ok'&&dd(l.from,l.to)===4),
        b=a&&L.find(l=>l.staffId==='e5'&&l.status==='pending'&&dd(l.from,l.to)===2&&dd(a.from,l.from)===7),
        c=a&&L.find(l=>l.staffId==='e2'&&l.status==='ok'&&dd(l.from,l.to)===4&&dd(l.from,a.from)===29);
  return a&&b&&c?[a.id,b.id,c.id]:[];
}
function demoKeepIds(){
  return new Set([...(S.sales||[]).filter(s=>!s.demo).map(s=>s.clientId),...(S.events||[]).filter(e=>!isDemoEv(e)).map(e=>e.clientId)].filter(Boolean));
}
function demoCount(){
  const keep=demoKeepIds();
  return (S.sales||[]).filter(s=>s.demo).length+(S.clients||[]).filter(c=>isDemoCl(c)&&!keep.has(c.id)).length+(S.events||[]).filter(isDemoEv).length+demoLeaves().length+Object.keys(S.checks||{}).filter(d=>isDemoCheck(d,S.checks[d])).length;
}
function clearDemo(){
  S.sales=(S.sales||[]).filter(s=>!s.demo);
  S.events=(S.events||[]).filter(e=>!isDemoEv(e));
  const keep=demoKeepIds();
  S.clients=(S.clients||[]).filter(c=>!isDemoCl(c)||keep.has(c.id));
  const dl=demoLeaves();S.leaves=(S.leaves||[]).filter(l=>!dl.includes(l.id));
  Object.keys(S.checks||{}).forEach(d=>{if(isDemoCheck(d,S.checks[d]))delete S.checks[d]});
  S.noDemo=true;number();
  try{if(cart&&cart.clientId&&!S.clients.some(c=>c.id===cart.clientId))cart.clientId=null}catch(e){}
  save();
}
