setInterval(()=>{if(PV&&!ME){PV=false;pvBanner()}},1500);
/* ---- mot de passe : « Mon compte » et « Mot de passe oublié » par e-mail ---- */
const MAILRE=/^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/;
const mailOf=a=>{if(!a)return '';const e=String(a.email||'').trim();if(MAILRE.test(e))return e;const i=String(a.ident||'').trim();return MAILRE.test(i)?i:''};
const maskMail=m=>{const [u,d]=String(m).split('@');return (u.length<=2?u.slice(0,1):u.slice(0,2))+'•••@'+d};
const mailCfg=()=>{const m=mjCfg();return m.sid&&m.tid&&m.key?m:null};
const RALPHA='ABCDEFGHJKMNPQRSTUVWXYZ23456789',RST_MIN=30,RST_WAIT=60,RST_TRIES=5;
function rstCode(){let c='';try{const b=new Uint8Array(8);crypto.getRandomValues(b);for(const x of b)c+=RALPHA[x%RALPHA.length]}catch(e){c='';for(let i=0;i<8;i++)c+=RALPHA[Math.floor(Math.random()*RALPHA.length)]}return c}
const rstNorm=s=>String(s||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
const rstHash=(code,a)=>hashPw(rstNorm(code),a.id+'|rst');
const rstShow=c=>c.slice(0,4)+'-'+c.slice(4);
/* envoi par EmailJS (service gratuit, appelé directement depuis le navigateur) */
async function mailSend(to,params){
  const m=mailCfg();if(!m)throw new Error('config');
  const ac=new AbortController(),to_=setTimeout(()=>ac.abort(),15000);
  try{
    const r=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',signal:ac.signal,headers:{'Content-Type':'application/json'},
      body:JSON.stringify({service_id:m.sid,template_id:m.tid,user_id:m.key,template_params:Object.assign({to_email:to,email:to,app_name:S.settings.name||'Lago',from_name:mlFrom(),reply_to:mlReply()},params)})});
    if(!r.ok){const t=await r.text().catch(()=>'');const e=new Error('http '+r.status+' '+t.slice(0,160));e.status=r.status;e.body=t;throw e}
  }finally{clearTimeout(to_)}
}
function mailErr(e){
  if(e&&e.mlc)return mlErrTxt(e);
  const t=String((e&&e.body)||(e&&e.message)||e),s=e&&e.status;
  if(e&&e.name==='AbortError')return 'pas de réponse du service d’e-mails (connexion ?)';
  if(/service id/i.test(t))return 'Service ID incorrect';
  if(/template id|template.*not found/i.test(t))return 'Template ID incorrect';
  if(/public key|user_id|account not found/i.test(t))return 'Public Key incorrecte';
  if(s===403)return 'accès refusé par EmailJS (clé ou domaine non autorisé)';
  if(s===429)return 'trop d’envois : quota EmailJS atteint';
  if(/Failed to fetch|NetworkError|Load failed/i.test(t))return 'service d’e-mails injoignable (connexion ou blocage du navigateur)';
  return t.replace(/^http \d+\s*/,'').slice(0,120)||'erreur inconnue';
}
/* demande de code : la clé (hachée) est écrite sur le compte, le code en clair part par e-mail */
async function rstRequest(a){
  if(!a)return {err:'Compte introuvable.'};
  if(a.status==='pending')return {err:'Compte en attente : l’administrateur doit d’abord le valider.'};
  if(a.status!=='active')return {err:'Ce compte est désactivé. Contactez l’administrateur.'};
  const to=mailOf(a);
  if(!to)return {err:'Aucune adresse e-mail n’est enregistrée sur ce compte. Demandez à l’administrateur de vous définir un nouveau mot de passe.'};
  if(!mailCfg())return {err:'L’envoi d’e-mails n’est pas encore activé. Demandez à l’administrateur de vous définir un nouveau mot de passe (Paramètres › Comptes).'};
  const w=a.rst&&a.rst.ts?Math.ceil((a.rst.ts+RST_WAIT*1000-Date.now())/1000):0;
  if(w>0)return {wait:w,to};
  const code=rstCode(),prev=a.rst,now=Date.now();
  a.rst={h:await rstHash(code,a),ts:now,exp:now+RST_MIN*60000,n:0};save();
  try{await mlSend(mlResetMsg(a,to,code))}
  catch(e){if(prev)a.rst=prev;else delete a.rst;save();console.warn('mail',e);return {err:'L’e-mail n’a pas pu être envoyé ('+mailErr(e)+'). Réessayez plus tard ou demandez un nouveau mot de passe à l’administrateur.'}}
  return {ok:true,to};
}

/* ---- écran de connexion ---- */
function gateForgot(id,ident){
  const a=id?accs().find(x=>x.id===id):null;
  if(a){const to=mailOf(a);
    gateShell(`<div class="gpick">${avA(a,1)}<h2>${esc(a.name)}</h2></div><h3 class="gsub">Mot de passe oublié</h3>
     <p class="muted" style="text-align:center">${to?`Nous envoyons un code à usage unique à <b>${esc(maskMail(to))}</b>. Il est valable ${RST_MIN} minutes.`:'Aucune adresse e-mail n’est enregistrée sur ce compte : demandez à l’administrateur de vous définir un nouveau mot de passe.'}</p>
     <form id="gfg" data-id="${a.id}"><p id="gerr" class="gerr"></p><button class="btn primary gbtn" type="submit" ${to?'':'disabled'}>Envoyer le code par e-mail</button>
     <div class="gfoot"><button type="button" class="btn" data-act="g_hascode" data-id="${a.id}">J’ai déjà un code</button><button type="button" class="btn" data-act="g_pick" data-id="${a.id}">Retour</button></div></form>`);
  }else gateShell(`<h2>Mot de passe oublié</h2><p class="muted">Entrez votre identifiant : nous envoyons un code à usage unique à l’adresse e-mail de votre compte.</p>
     <form id="gfg"><div class="field"><label for="gi">Identifiant (e-mail ou pseudo)</label><input id="gi" required autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" value="${esc(ident||'')}"></div>
     <p id="gerr" class="gerr"></p><button class="btn primary gbtn" type="submit">Envoyer le code par e-mail</button>
     <div class="gfoot"><button type="button" class="btn" data-act="g_back">Retour</button></div></form>`);
}
function gateReset(id,sentTo,waited){
  const a=accs().find(x=>x.id===id);if(!a)return gateStart();
  const pw=`autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="new-password"`;
  gateShell(`<div class="gpick">${avA(a,1)}<h2>${esc(a.name)}</h2></div><h3 class="gsub">Nouveau mot de passe</h3>
   <p class="muted" style="text-align:center">${waited?'Un code vient d’être envoyé : ':sentTo?`Code envoyé à <b>${esc(maskMail(sentTo))}</b>. `:''}Saisissez-le, puis choisissez un nouveau mot de passe.<br>Pensez à regarder dans les courriers indésirables.</p>
   <form id="grs" data-id="${a.id}"><div class="field"><label for="gc">Code reçu par e-mail</label><input id="gc" required autocomplete="one-time-code" autocapitalize="characters" autocorrect="off" spellcheck="false" placeholder="XXXX-XXXX" style="letter-spacing:2px;text-transform:uppercase"></div>
   <div class="field"><label for="gp1">Nouveau mot de passe (6 caractères min.)</label><input id="gp1" type="password" required minlength="6" ${pw}></div>
   <div class="field"><label for="gp2">Confirmer le mot de passe</label><input id="gp2" type="password" required minlength="6" ${pw}></div>
   <label class="check" style="margin:-4px 0 10px"><input type="checkbox" id="gshow2">Afficher les mots de passe</label>
   <p id="gerr" class="gerr"></p><button class="btn primary gbtn" type="submit">Changer le mot de passe et entrer</button>
   <div class="gfoot"><button type="button" class="btn" data-act="g_again" data-id="${a.id}">Renvoyer un code</button><button type="button" class="btn" data-act="g_back">Annuler</button></div></form>`);
  setTimeout(()=>{const c=$('#gc');if(c)c.focus()},50);
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="g_forgot"],[data-act="g_hascode"],[data-act="g_again"],a[data-act="rolesw"]');if(!b)return;
  const a=b.dataset.act;
  if(a==='rolesw'){e.preventDefault();return}
  if(a==='g_forgot'){const f=$('#gform'),i=$('#gi');gateForgot(f&&f.dataset.kind==='pick'?f.dataset.id:'',i&&f.dataset.kind!=='pick'?i.value:'')}
  else if(a==='g_hascode')gateReset(b.dataset.id,'');
  else if(a==='g_again')gateForgot(b.dataset.id);
});
document.addEventListener('change',e=>{if(e.target.id==='gshow2'){['gp1','gp2'].forEach(i=>{const p=document.getElementById(i);if(p)p.type=e.target.checked?'text':'password'})}});
document.addEventListener('submit',async e=>{
  if(e.target.id!=='gfg')return;e.preventDefault();
  const f=e.target,err=m=>{const x=$('#gerr');if(x)x.textContent=m},btn=f.querySelector('button[type=submit]');
  let a=f.dataset.id?accs().find(x=>x.id===f.dataset.id):null;
  if(!a){const q=(($('#gi')||{}).value||'').trim().toLowerCase();a=accs().find(x=>x.ident===q||String(x.email||'').toLowerCase()===q);
    if(!a){err(cloudOn()?'Compte introuvable. Vérifiez l’identifiant.':'Compte introuvable : cet appareil n’est pas connecté à l’équipe. Ouvrez le lien d’équipe envoyé par votre responsable.');return}}
  btn.disabled=true;err('');btn.textContent='Envoi en cours…';
  try{const r=await rstRequest(a);if(r.ok||r.wait)gateReset(a.id,r.to,!!r.wait);else err(r.err)}
  finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Envoyer le code par e-mail'}}
});
document.addEventListener('submit',async e=>{
  if(e.target.id!=='grs')return;e.preventDefault();
  const f=e.target,a=accs().find(x=>x.id===f.dataset.id),err=m=>{const x=$('#gerr');if(x)x.textContent=m},btn=f.querySelector('button[type=submit]');
  if(!a||!a.rst){err('Aucun code actif. Touchez « Renvoyer un code ».');return}
  if(a.rst.exp<Date.now()){delete a.rst;save();err('Ce code a expiré. Touchez « Renvoyer un code ».');return}
  const p1=$('#gp1').value.trim(),p2=$('#gp2').value.trim();
  if(p1.length<6){err('6 caractères minimum pour le mot de passe.');return}
  if(p1!==p2){err('Les deux mots de passe sont différents.');return}
  btn.disabled=true;
  try{
    if(await rstHash($('#gc').value,a)!==a.rst.h){
      a.rst.n=(a.rst.n||0)+1;
      if(a.rst.n>=RST_TRIES){delete a.rst;save();err('Trop d’essais : ce code est annulé. Touchez « Renvoyer un code ».');return}
      save();err('Code incorrect. Il reste '+(RST_TRIES-a.rst.n)+' essai(s).');return}
    a.pwd=await hashPw(p1,a.id);delete a.rst;delete LOCKS[a.id];save();
    login(a,true);toast('Mot de passe modifié');
  }finally{if(btn.isConnected)btn.disabled=false}
});

