/* ---------- l'assistant IA dans l'appli installée : clé API Anthropic ---------- */
/* Ouvert depuis le compte Claude, Lago utilise l'assistant intégré. Dans l'appli installée (écran d'accueil),
   cet assistant n'existe pas : Lago appelle alors directement l'API Anthropic avec la clé enregistrée par l'administrateur.
   L'objet fabriqué ici a la même forme que l'assistant intégré (appel, .json, .limits), donc toutes les fonctions IA de Lago en profitent. */
var AIX=null;
const AIAPI='https://api.anthropic.com/v1/messages';
const AIMODELS={quick:['claude-haiku-5-5','claude-haiku-4-5'],default:['claude-sonnet-5-5','claude-sonnet-4-5'],complex:['claude-opus-5-5','claude-opus-4-5']};
Object.assign(AIERR,{bad_key:'La clé Anthropic est refusée. Vérifiez-la dans Paramètres › Général › Assistant IA.',no_credit:'Le crédit Anthropic est épuisé. Rechargez-le sur console.anthropic.com (Billing).',offline:'Pas de connexion internet. Réessayez.',no_model:'Le modèle demandé n’est pas accessible avec cette clé.'});
const aiKey=()=>String((S&&S.settings&&S.settings.aiKey)||'').trim();
function aiSync(){
  if(!AIX)return;
  if(SAMPLE===AIX){if(!aiKey())SAMPLE=null;return}
  if(!SAMPLE&&aiKey())SAMPLE=AIX;
}
const aiB64=b=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]||'');r.onerror=()=>rej(new Error('img'));r.readAsDataURL(b)});
function aiParseJson(t){
  t=String(t||'').replace(/^\s*```(?:json)?\s*/i,'').replace(/\s*```\s*$/,'').trim();
  const a=t.search(/[\[{]/),z=Math.max(t.lastIndexOf('}'),t.lastIndexOf(']'));
  if(a<0||z<a)throw {code:'invalid_json',message:'Réponse illisible',text:t};
  try{return JSON.parse(t.slice(a,z+1))}catch(e){throw {code:'invalid_json',message:'Réponse illisible',text:t}}
}
async function aiApiErr(res){
  let j=null;try{j=await res.json()}catch(e){}
  const er=(j&&j.error)||{},msg=String(er.message||'');
  const code=res.status===401||res.status===403?'bad_key':res.status===429?'rate_limited':/credit balance|billing/i.test(msg)?'no_credit':res.status===404||/model/i.test(msg)&&res.status===400?'no_model':res.status>=500||res.status===529?'upstream_error':'refused';
  return {code,message:msg||('Erreur '+res.status),status:res.status};
}
async function aiApiCall(input,opts,model,sys){
  const turns=typeof input==='string'?[{role:'user',content:input}]:input.map(x=>({role:x.role,content:x.content}));
  if(opts.images&&opts.images.length){
    const last=turns[turns.length-1],imgs=await Promise.all(opts.images.map(async b=>({type:'image',source:{type:'base64',media_type:'image/jpeg',data:await aiB64(b)}})));
    last.content=[...imgs,{type:'text',text:String(last.content)}];
  }
  const stream=typeof opts.onText==='function',body={model,max_tokens:opts.maxTokens||4096,messages:turns};
  if(sys)body.system=sys;
  if(stream)body.stream=true;
  let res;
  try{res=await fetch(AIAPI,{method:'POST',signal:opts.signal,headers:{'content-type':'application/json','x-api-key':aiKey(),'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'},body:JSON.stringify(body)})}
  catch(e){throw e&&e.name==='AbortError'?{code:'cancelled',message:''}:{code:'offline',message:'réseau'}}
  if(!res.ok)throw await aiApiErr(res);
  if(!stream){const j=await res.json();return {text:(j.content||[]).filter(x=>x.type==='text').map(x=>x.text).join(''),truncated:j.stop_reason==='max_tokens'}}
  const rd=res.body.getReader(),dec=new TextDecoder();let buf='',text='',trunc=false;
  try{for(;;){
    const {done,value}=await rd.read();if(done)break;
    buf+=dec.decode(value,{stream:true});
    const lines=buf.split('\n');buf=lines.pop();
    for(const l of lines){
      if(!l.startsWith('data:'))continue;
      let ev;try{ev=JSON.parse(l.slice(5))}catch(e){continue}
      if(ev.type==='content_block_delta'&&ev.delta&&ev.delta.type==='text_delta'){text+=ev.delta.text;opts.onText({text,delta:ev.delta.text})}
      else if(ev.type==='message_delta'&&ev.delta&&ev.delta.stop_reason==='max_tokens')trunc=true;
      else if(ev.type==='error')throw {code:ev.error&&ev.error.type==='overloaded_error'?'upstream_error':'refused',message:ev.error&&ev.error.message||'',text};
    }
  }}catch(e){if(e&&e.code)throw Object.assign(e,{text:e.text||text});throw e&&e.name==='AbortError'?{code:'cancelled',message:'',text}:{code:'upstream_error',message:'connexion interrompue',text}}
  return {text,truncated:trunc};
}
AIX=Object.assign(async function(input,opts){
  opts=opts||{};
  const chain=opts.model?[opts.model]:(AIMODELS[opts.modelTier]||AIMODELS.default);
  let last=null;
  for(const m of chain){
    try{return await aiApiCall(input,opts,m,opts._sys)}
    catch(e){last=e;if(!(e&&e.code==='no_model'))throw e}
  }
  throw last;
},{
  json:async(input,opts)=>aiParseJson((await AIX(input,Object.assign({},opts,{onText:undefined,_sys:'Tu réponds uniquement par un objet JSON valide, sans aucun texte autour ni balise de code.'}))).text),
  limits:async()=>({images:true})
});
/* carte de réglage (administrateur) */
function aiKeyCard(m){
  if(!m||!isAdmin())return;
  const k=aiKey(),on=!!k,native=!!SAMPLE&&SAMPLE!==AIX;
  m.insertAdjacentHTML('beforeend',`<div class="card" id="aikcard" style="margin-top:14px"><h3>Assistant IA ${on?'<span class="pill ok">Activé</span>':native?'<span class="pill ok">Intégré</span>':'<span class="pill warn">À configurer</span>'}</h3>
   <p class="muted" style="font-size:13px;margin-bottom:8px">Lit un rapport d’incident papier et remplit le formulaire, rédige les descriptions, répond aux questions sur vos chiffres. Dans l’appli installée sur le téléphone, il faut une clé Anthropic ; ouvert depuis votre compte Claude, aucune clé n’est nécessaire. La clé est partagée avec l’équipe par la synchronisation, pour que chaque téléphone puisse numériser.</p>
   ${fld('Clé API Anthropic',`<input id="aikey" type="password" value="" placeholder="${on?'Clé enregistrée : '+esc(k.slice(0,7)+'…'+k.slice(-4)):'sk-ant-…'}" autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off">`)}
   <p id="aikmsg" class="muted" style="min-height:20px;font-size:13px"></p>
   <div class="acts"><button class="btn primary" data-act="aik_save">Enregistrer la clé</button><button class="btn" data-act="aik_test" ${on?'':'disabled'}>Tester</button>${on?'<button class="btn" data-act="aik_rm">Retirer la clé</button>':''}</div>
   <details style="margin-top:12px"><summary><b>Comment obtenir une clé (5 minutes)</b></summary>
   <ol class="muted" style="font-size:13px;line-height:1.6;padding-left:18px;margin:8px 0 0">
    <li>Créez un compte sur <b>console.anthropic.com</b> (c’est différent de l’abonnement Claude).</li>
    <li><b>Billing</b> : ajoutez un crédit de 5 à 10 €. Une numérisation coûte quelques centimes.</li>
    <li><b>Limits</b> : fixez une limite de dépense mensuelle (par exemple 10 €) pour garder la main sur le coût.</li>
    <li><b>API keys</b> › Create key. Copiez la clé (elle commence par <code>sk-ant-</code>) et collez-la ci-dessus.</li>
    <li>Enregistrez, puis touchez « Tester ».</li></ol></details></div>`);
}
{const f=SUBS.pgen;SUBS.pgen=m=>{f(m);aiKeyCard(m)}}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-act="aik_save"],[data-act="aik_test"],[data-act="aik_rm"]');if(!b||!isAdmin())return;
  const a=b.dataset.act,msg=t=>{const x=$('#aikmsg');if(x)x.textContent=t},redo=()=>{const sub=$('#sub');if(sub)SUBS.pgen(sub)};
  if(a==='aik_save'){
    const v=String(($('#aikey')||{}).value||'').trim();
    if(!v){msg('Collez d’abord la clé.');return}
    if(!/^sk-ant-[A-Za-z0-9_\-]{20,}$/.test(v)){msg('Cette clé n’a pas la bonne forme : elle commence par « sk-ant- ».');return}
    S.settings.aiKey=v;save();aiSync();redo();toast('Assistant IA activé');
  }else if(a==='aik_rm'){
    delete S.settings.aiKey;save();aiSync();redo();toast('Clé retirée');
  }else if(a==='aik_test'){
    b.disabled=true;msg('Test en cours…');
    try{const r=await AIX('Réponds par le seul mot : OK',{modelTier:'quick',maxTokens:16});msg('✓ La connexion fonctionne'+(r.text?' (réponse : '+r.text.trim().slice(0,20)+')':'')+'.')}
    catch(x){msg('Échec : '+(AIERR[x&&x.code]||(x&&x.message)||'erreur inconnue')+(x&&x.message&&AIERR[x.code]&&x.code!=='bad_key'?' ('+String(x.message).slice(0,120)+')':''))}
    if(b.isConnected)b.disabled=false;
  }
});
/* ---------- LV. congés : soldes lisibles, demandes à valider en premier (v52) ---------- */
function lvPlural(n,a,b){return n>1?b:a}
function vLeaves(m){
  const st={pending:['warn','En attente'],ok:['ok','Validé'],no:['bad','Refusé']};
  const pend=S.leaves.filter(l=>l.status==='pending').sort((a,b)=>a.from.localeCompare(b.from));
  const rest=S.leaves.filter(l=>l.status!=='pending').sort((a,b)=>b.from.localeCompare(a.from));
  const cards=S.staff.map(s=>{
    const A=cpOn()?cpCalc(s):null,tot=A?A.acq:CP_TOTAL,u=A?A.u:leaveUsed(s.id,['ok']),p=A?A.p:leaveUsed(s.id,['pending']),left=A?A.left:CP_TOTAL-u-p,c=scol(s);
    const wu=tot>0?Math.max(0,Math.min(100,u/tot*100)):0,wp=tot>0?Math.max(0,Math.min(100-wu,p/tot*100)):0;
    return `<div class="lvc" style="--c:${c}"><span class="pav" style="background:${c};color:${inkOn(c)}">${esc(initials(s.name))}</span>
      <div class="lvn"><b>${esc(fname(s))}</b><small>${ROLE[s.role]||''}</small></div>
      <div class="lvbig"><b class="num ${left<0?'neg':left<=3?'low':''}">${cpFmt(left)}</b><span>jour${Math.abs(left)>1?'s':''} restant${Math.abs(left)>1?'s':''}</span></div>
      <div class="lvbar" role="img" aria-label="${cpFmt(u)} jours pris, ${cpFmt(p)} en attente, sur ${cpFmt(tot)}"><i class="u" style="width:${wu}%"></i><i class="p" style="width:${wp}%"></i></div>
      <div class="lvch"><span><i class="sw u"></i>${cpFmt(u)} pris</span>${p?`<span class="w"><i class="sw p"></i>${cpFmt(p)} en attente</span>`:''}<span class="t">sur ${cpFmt(tot)}${A?' acquis':''}</span></div>
      ${A?`<div class="lvnx">+${cpFmt(cpRate())} j le ${cpDay()} du mois · prochain le ${dshort(cpNext(today()))}</div>`:''}</div>`}).join('');
  const row=l=>{const s=staffOf(l.staffId),n=leaveDays(l.from,l.to).length,c=scol(s);
    const act=l.status==='pending'&&isAdmin()?`<div class="lvact"><button class="btn primary" data-act="lvok" data-id="${l.id}">Valider</button><button class="btn danger" data-act="lvno" data-id="${l.id}">Refuser</button></div>`:'';
    return `<div class="lvr"><span class="pav" style="background:${c};color:${inkOn(c)}">${esc(initials(s.name))}</span>
      <div class="lvw"><b>${esc(s.name)}</b><span class="muted">Du ${dshort(l.from)} au ${dshort(l.to)}</span><span class="muted">${n} jour${n>1?'s':''} ouvré${n>1?'s':''}</span></div>
      <span class="pill ${st[l.status][0]}">${st[l.status][1]}</span>${act}</div>`};
  m.innerHTML=bar(`<button class="btn primary" data-act="newleave">${ic('plus')}Poser des congés</button>`)+
   `<div class="lvgrid">${cards}</div>
   ${pend.length?`<div class="card lvcard"><h3>À valider <span class="pill warn">${pend.length}</span></h3>${pend.map(row).join('')}</div>`:''}
   <div class="card lvcard"><h3>${pend.length?'Historique':'Demandes'}</h3>${rest.map(row).join('')||`<p class="muted">${pend.length?'Rien d’autre pour le moment.':'Aucune demande.'}</p>`}
   <p class="muted" style="margin-top:12px;font-size:13px">Décompte en jours ouvrés (du lundi au vendredi), ${cpOn()?'solde de départ + '+cpFmt(cpRate())+' jours ajoutés le '+cpDay()+' de chaque mois':'sur '+CP_TOTAL+' jours par an'}. Les jours en attente sont déjà retirés du solde.</p></div>`;
}
/* ---------- CH. chat d'équipe : réactions, réponses rapides, bouton « aller en bas », noms colorés (v52) ---------- */
IC.down=IC.down||'<path d="M6 9l6 6 6-6"/>';
const CH_EMO=['👍','❤️','😂','🙏','✅'];
const CH_QUICK=['Bien reçu 👍','J’arrive','Besoin d’aide à l’accueil','Je suis en retard'];
let CHP='';
const chCol=id=>{let h=0;for(const c of String(id||''))h=(h*31+c.charCodeAt(0))>>>0;return PCOL[h%PCOL.length]};
const chInk=id=>`color-mix(in srgb,${chCol(id)} 58%,#0A1F4D)`;
function chReact(x){
  const re=x.re||{},by={};
  for(const k in re){const e=re[k];if(typeof e==='string'&&e)(by[e]=by[e]||[]).push(k)}
  const me=ME&&ME.id;
  return Object.keys(by).sort((a,b)=>by[b].length-by[a].length).map(e=>`<button type="button" class="tk-re ${by[e].includes(me)?'mine':''}" data-act="ch_re" data-id="${esc(x.id)}" data-e="${e}" aria-label="${e} ${by[e].length}, ${by[e].includes(me)?'retirer votre réaction':'réagir'}"><span>${e}</span><b>${by[e].length}</b></button>`).join('');
}
function chHtml(){
  const L=chSorted();
  if(!L.length)return `<div class="tk-empty"><span class="tk-eic">${ic('chat')}</span><b>Aucun message pour le moment</b><span>Écrivez le premier : toute l’équipe le verra.</span></div>`;
  const me=ME&&ME.id;let out='',lastDay='',prev=null,divDone=false;
  for(const x of L){
    const dk=dkey(new Date(x.ts));
    if(dk!==lastDay){out+=`<div class="tk-day"><span>${esc(chDay(dk))}</span></div>`;lastDay=dk;prev=null}
    if(CHDIV!=null&&!divDone&&x.ts>CHDIV&&x.accId!==me){out+='<div class="tk-new"><span>Nouveaux messages</span></div>';divDone=true;prev=null}
    const mine=x.accId===me,grp=!!prev&&prev.accId===x.accId&&x.ts-prev.ts<5*60000,a=accs().find(y=>y.id===x.accId),rx=chReact(x);
    const pick=CHP===x.id?`<div class="tk-pick" role="group" aria-label="Réagir">${CH_EMO.map(e=>`<button type="button" data-act="ch_re" data-id="${esc(x.id)}" data-e="${e}" aria-label="Réagir ${e}">${e}</button>`).join('')}</div>`:'';
    out+=`<div class="tk-m ${mine?'me':''} ${grp?'grp':''}">${mine?'':`<span class="tk-av">${grp?'':avA(a||{name:x.name})}</span>`}<div class="tk-b">${!mine&&!grp?`<b class="tk-n" style="color:${chInk(x.accId)}">${esc(a?a.name:x.name)}</b>`:''}<div class="tk-t">${chText(x.text)}</div>${rx?`<div class="tk-rx">${rx}</div>`:''}${pick}<span class="tk-i">${hm(x.ts)}<button type="button" class="tk-rb ${CHP===x.id?'on':''}" data-act="ch_pick" data-id="${esc(x.id)}" aria-label="Réagir à ce message" aria-expanded="${CHP===x.id}">☺</button>${(isAdmin()||mine)?` · <button type="button" class="tk-del" data-act="ch_del" data-id="${esc(x.id)}">Supprimer</button>`:''}</span></div></div>`;
    prev=x;
  }
  return out;
}
function chPost(t){
  if(!ME)return false;t=String(t||'').trim().slice(0,600);if(!t)return false;
  const L=talkL(),ts=Math.max(Date.now(),chMax()+1);
  L.push({id:uid(),accId:ME.id,name:ME.name,text:t,ts});
  L.sort((a,b)=>a.ts-b.ts);while(L.length>TK_MAX)L.shift();
  save();chSetSeen(ts);chatDraw(true);return true;
}
function chQuick(){
  const q=document.getElementById('chquick'),ta=document.getElementById('chtext');if(!q||!ta)return;
  q.hidden=!!ta.value.trim();
}
function chScrollBtn(){
  const el=document.getElementById('chlist'),b=document.getElementById('chdown');if(!el||!b)return;
  b.hidden=el.scrollHeight-el.clientHeight-el.scrollTop<160;
}
function vChat(m){
  if(!ME){m.innerHTML='';return}
  const old=document.getElementById('chlist'),keep=old?{top:old.scrollTop,bot:old.scrollHeight-old.clientHeight-old.scrollTop<90}:null;
  if(!CHA){CHA=true;CHDIV=chSeenRaw()===null?chMax():chSeen()}
  m.innerHTML=head('Chat d’équipe')+`<section class="tkcard card"><div class="tk-wrap"><div class="tk-list" id="chlist" role="log" aria-live="polite" aria-label="Messages de l’équipe"></div><button type="button" class="tk-down" id="chdown" data-act="ch_down" aria-label="Aller au dernier message" hidden>${ic('down')}</button></div>
   <div class="tk-quick" id="chquick" role="group" aria-label="Réponses rapides">${CH_QUICK.map(q=>`<button type="button" class="tk-q" data-act="ch_quick" data-t="${esc(q)}">${esc(q)}</button>`).join('')}</div>
   <form id="chform" class="tk-comp"><textarea id="chtext" rows="1" maxlength="600" placeholder="Écrire à toute l’équipe…" enterkeyhint="send" aria-label="Votre message"></textarea><button class="btn primary tk-send" type="submit" aria-label="Envoyer">${CHSEND}</button></form></section>
   ${isAdmin()?`<p class="muted tk-adm">Administrateur : vous pouvez supprimer n’importe quel message. <button type="button" class="glink" data-act="ch_clear">Vider la conversation</button></p>`:''}`;
  const ta=document.getElementById('chtext');ta.value=CHD;chSize(ta);
  chatDraw(!keep||keep.bot);
  if(keep&&!keep.bot)document.getElementById('chlist').scrollTop=keep.top;
  if(!keep&&matchMedia('(pointer:fine)').matches)ta.focus();
  document.getElementById('chlist').addEventListener('scroll',chScrollBtn,{passive:true});
  chQuick();chScrollBtn();
  chSetSeen(chMax());chBadge();
}
VIEWS.chat=vChat;
{const f=chatDraw;chatDraw=function(force){f(force);chScrollBtn()}}
document.addEventListener('input',e=>{if(e.target.id==='chtext')chQuick()});
document.addEventListener('submit',e=>{if(e.target.id==='chform')setTimeout(chQuick,0)});
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="ch_re"],[data-act="ch_pick"],[data-act="ch_quick"],[data-act="ch_down"]');if(!b||!ME)return;
  const a=b.dataset.act;
  if(a==='ch_down'){const el=document.getElementById('chlist');if(el)el.scrollTo({top:el.scrollHeight,behavior:'smooth'});return}
  if(a==='ch_quick'){chPost(b.dataset.t);return}
  if(a==='ch_pick'){CHP=CHP===b.dataset.id?'':b.dataset.id;chatDraw();return}
  const x=talkL().find(y=>y.id===b.dataset.id);if(!x)return;
  const e1=b.dataset.e;x.re=x.re||{};
  if(x.re[ME.id]===e1)delete x.re[ME.id];else x.re[ME.id]=e1;
  if(!Object.keys(x.re).length)delete x.re;
  CHP='';save();chatDraw();
});
