/* ---------- SN. joindre la photo d'un rapport papier, sans IA (v60) ---------- */
/* Fonctionne partout, sans clé : photo ou scan → réduit → joint au rapport d'incident et à son PDF. */
const SN_MAX=3,SN_PX=1000,SN_Q=.55,SN_CAP=4200000;
function snImg(file){
  return new Promise((res,rej)=>{
    const u=URL.createObjectURL(file),im=new Image();
    im.onload=()=>{URL.revokeObjectURL(u);
      const k=Math.min(1,SN_PX/Math.max(im.width,im.height)),cv=document.createElement('canvas');
      cv.width=Math.max(1,Math.round(im.width*k));cv.height=Math.max(1,Math.round(im.height*k));
      const x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,cv.width,cv.height);x.drawImage(im,0,0,cv.width,cv.height);
      res({u:cv.toDataURL('image/jpeg',SN_Q),w:cv.width,h:cv.height})};
    im.onerror=()=>{URL.revokeObjectURL(u);rej(new Error('img'))};
    im.src=u;
  });
}
async function snAdd(files){
  const d=ctl.inc;if(!d)return;
  files=[...files].filter(f=>f&&/^image\//.test(f.type));
  if(!files.length){toast('Choisissez une photo ou un scan en image (JPG, PNG)');return}
  d.scans=d.scans||[];
  const room=SN_MAX-d.scans.length;
  if(room<=0){toast(SN_MAX+' pages au plus par rapport');return}
  let n=0,full=false;
  for(const f of files.slice(0,room)){
    if(JSON.stringify(S).length>SN_CAP){full=true;break}
    try{d.scans.push(await snImg(f));n++}catch(e){toast('Cette image n’a pas pu être ouverte. Essayez un autre fichier.')}
  }
  if(!d.scans.length)delete d.scans;
  subR();
  if(full)toast('Mémoire de l’appareil presque pleine : supprimez d’anciennes photos jointes avant d’en ajouter');
  else if(n)toast(n+' page'+(n>1?'s':'')+' jointe'+(n>1?'s':'')+' au rapport');
}
const snNb=d=>((d&&d.scans)||[]).length;
{const f0=scanCard;scanCard=function(){
  const d=ctl.inc,sc=(d&&d.scans)||[],full=sc.length>=SN_MAX,off=full?' off':'',dis=full?' disabled':'';
  const th=sc.map((s,i)=>`<figure class="snth"><img src="${s.u}" alt="Page ${i+1} du rapport papier"><button type="button" class="btn danger" data-act="sn_rm" data-i="${i}" aria-label="Retirer la page ${i+1}">Retirer</button></figure>`).join('');
  const btns=`<div class="acts scanacts"><label class="btn scanbtn${off}">${scanCam}<span>Choisir une photo ou un scan</span><input type="file" id="snfile" accept="image/*" multiple hidden${dis}></label>
    <label class="btn scanbtn scancam${off}">${scanCam}<span>Prendre en photo</span><input type="file" id="sncam" accept="image/*" capture="environment" hidden${dis}></label></div>
    ${th?`<div class="snths" id="snths">${th}</div>`:''}`;
  if(!aiOk()){
    return `<div class="card scan"><h3>Numériser un rapport papier</h3>
    <p class="muted">Prenez en photo (ou choisissez un scan) le rapport rempli à la main : la photo est conservée avec ce rapport et ajoutée à son PDF (${SN_MAX} pages au plus).</p>
    ${btns}
    <p class="muted snnote">${isAdmin()?'Lecture automatique par IA non activée. Pour qu’elle remplisse le formulaire à votre place, ajoutez une clé dans Paramètres › Général › Assistant IA (5 minutes, quelques centimes par rapport).':'Demandez à l’administrateur d’activer l’assistant IA (Paramètres › Général › Assistant IA) pour que le formulaire se remplisse tout seul.'}</p>
    ${isAdmin()?'<div class="acts"><button type="button" class="btn ai" data-act="aigo">Activer le remplissage automatique</button></div>':''}
    <input type="file" id="incscan" accept="image/*" multiple hidden disabled></div>`;
  }
  const att=`<div class="snatt"><h4>Joindre la photo du rapport papier</h4>
    <p class="muted">La photo est conservée avec ce rapport et ajoutée à son PDF (${SN_MAX} pages au plus).</p>${btns}</div>`;
  return f0().replace(/<\/div>\s*$/,att+'</div>');
}}
