/* ---------- V61. planning : fin habituelle par personne · image personnalisée · maintenance (v61) ---------- */

/* -- 1. Fin habituelle d'une personne, par jour de la semaine --------------------------------
   s.end = {6:17} : « part à 17 h le dimanche » (0 = lundi … 6 = dimanche).
   Elle s'applique à toutes les semaines du planning ; un horaire réglé à la main pour un jour
   précis (bouton « Horaires ») est prioritaire. Les heures sont recalculées partout. */
const plRule=(id,d)=>{const s=S.staff.find(x=>x.id===id),v=s&&s.end?+s.end[d]:0;return v>0?v:null};
function plRuleCut(p,d,id){
  const r=plRule(id,d);if(r===null)return null;
  const sp=plSpan(p,d,id);if(!sp)return null;
  const y=Math.min(r,sp[1]);
  return (y-sp[0]>=.5&&y<sp[1])?[sp[0],y]:null;
}
function plRuleNote(p,d,id){
  const c=p.cut&&p.cut[d]&&p.cut[d][id];
  if(c!==undefined||!plRuleCut(p,d,id))return '';
  return `<div class="plrule">Fin habituelle : ${plF(plRule(id,d))} (réglage dans Paramètres › Équipe)</div>`;
}
const stEndTxt=s=>{const e=s.end||{};return Object.keys(e).filter(d=>+e[d]>0).sort((a,b)=>a-b).map(d=>DAYN[d].slice(0,3).toLowerCase()+'. '+plF(+e[d])).join(' · ')};
function stEndBtn(s){
  const t=stEndTxt(s);
  return `<button type="button" class="btn plend${t?' on':''}" data-act="stend" data-id="${s.id}" title="Heure de fin habituelle, jour par jour">${ic('clock')}<span>${t?'Fin '+esc(t):'Horaires habituels'}</span></button>`;
}
function stEndModal(id){
  const s=S.staff.find(x=>x.id===id);if(!s)return;
  const opts=sel=>{let o=`<option value="" ${sel?'':'selected'}>Selon le planning</option>`;for(let h=12;h<=23.5+1e-9;h+=.5)o+=`<option value="${h}" ${sel&&Math.abs(h-sel)<1e-9?'selected':''}>${plF(h)}</option>`;return o};
  showModal(`${mh('Horaires habituels · '+esc(fname(s)))}<form id="stendform" data-id="${s.id}">
    <p class="muted" style="margin:0 0 8px">Choisissez l’heure à laquelle ${esc(fname(s))} part, jour par jour. Elle s’applique à toutes les semaines du planning et les heures sont recalculées partout (totaux, Mon planning, PDF, échanges). Pour un seul jour, utilisez « Horaires » dans le planning.</p>
    ${DAYN.map((n,d)=>`<div class="ster"><b>${n}</b><select data-d="${d}" aria-label="Fin habituelle le ${n.toLowerCase()}">${opts(s.end&&+s.end[d]||0)}</select></div>`).join('')}
    <div class="acts" style="margin-top:14px"><button type="button" class="btn" data-act="close">Annuler</button><button class="btn primary" type="submit">Enregistrer</button></div></form>`);
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="stend"]');if(!b)return;
  if(!isAdmin()){toast('Réservé à l’administrateur');return}
  stEndModal(b.dataset.id);
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='stendform')return;e.preventDefault();if(!isAdmin())return;
  const f=e.target,s=S.staff.find(x=>x.id===f.dataset.id);if(!s)return;
  try{autoSnap()}catch(_){}
  const end={};f.querySelectorAll('select[data-d]').forEach(x=>{const v=+x.value;if(v>0)end[x.dataset.d]=v});
  if(Object.keys(end).length)s.end=end;else delete s.end;
  save();closeModal();
  try{redrawStaff()}catch(_){}
  if(view==='params'&&$('#sub')&&typeof vSetTeam==='function')vSetTeam($('#sub'));
  toast('Horaires habituels enregistrés');
});
/* Johan finit à 17 h le dimanche : posé une seule fois, modifiable ensuite dans Paramètres › Équipe */
function plEndInit(){
  try{
    if(!S||!S.settings||S.settings.plEndInit||!Array.isArray(S.staff))return;
    S.settings.plEndInit=1;
    const j=S.staff.filter(x=>/^\s*johan\b/i.test(x.name||''));
    if(j.length===1&&!(j[0].end&&Object.keys(j[0].end).length))j[0].end={6:17};
    save();
  }catch(e){}
}

/* -- 2. Image personnalisée en haut de « Avant l'ouverture » (et des autres rapports) ------------ */
const heroImg=k=>(S.settings&&S.settings.heroImg&&S.settings.heroImg[k])||'';
function heroCtl(k){
  if(!isAdmin())return '';
  const has=!!heroImg(k);
  return `<div class="chctl"><label class="btn chpick">${scanCam}<span>${has?'Changer l’image':'Mon image'}</span><input type="file" id="heroup" data-k="${k}" accept="image/*" hidden></label>${has?`<button type="button" class="btn chrm" data-act="hero_rm" data-k="${k}">Image d’origine</button>`:''}</div>`;
}
function heroPack(file){
  return new Promise((res,rej)=>{
    const u=URL.createObjectURL(file),im=new Image();
    im.onload=()=>{URL.revokeObjectURL(u);
      const steps=[[1100,.74],[900,.62],[720,.5]];
      for(const [px,q] of steps){
        const k=Math.min(1,px/Math.max(im.width,im.height)),cv=document.createElement('canvas');
        cv.width=Math.max(1,Math.round(im.width*k));cv.height=Math.max(1,Math.round(im.height*k));
        const x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,cv.width,cv.height);x.drawImage(im,0,0,cv.width,cv.height);
        const d=cv.toDataURL('image/jpeg',q);
        if(d.length<=300000||q<=.5){res(d);return}
      }
    };
    im.onerror=()=>{URL.revokeObjectURL(u);rej(new Error('img'))};
    im.src=u;
  });
}
document.addEventListener('change',async e=>{
  const t=e.target;if(t.id!=='heroup'||!t.files||!t.files.length)return;
  const f=t.files[0],k=t.dataset.k;t.value='';
  if(!isAdmin())return;
  if(!/^image\//.test(f.type)){toast('Choisissez une image (JPG, PNG)');return}
  try{
    const u=await heroPack(f);
    S.settings.heroImg=S.settings.heroImg||{};S.settings.heroImg[k]=u;save();subR();toast('Image enregistrée');
  }catch(err){toast('Cette image n’a pas pu être ouverte. Essayez un autre fichier.')}
});
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="hero_rm"]');if(!b)return;
  if(!isAdmin())return;
  if(S.settings.heroImg){delete S.settings.heroImg[b.dataset.k];if(!Object.keys(S.settings.heroImg).length)delete S.settings.heroImg}
  save();subR();toast('Illustration d’origine rétablie');
});

/* -- 3. Maintenance : nature de l'intervention en cases à cocher, sans le coût ------------------ */
const MKINDS=['Vérification','Réparation','Création','Suppression','Modification'];
function mntKindsBox(d){
  const k=d.kinds||[];
  return `<fieldset class="mkinds"><legend>Nature de l’intervention</legend><div class="mkrow">${MKINDS.map(x=>`<label class="mk"><input type="checkbox" data-mk="${x}" ${k.includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div>${!k.length&&d.type?`<p class="muted mkold">Ancien type : ${esc(d.type)}</p>`:''}</fieldset>`;
}
document.addEventListener('change',e=>{
  const t=e.target;if(!t.dataset||!t.dataset.mk||!ctl.mnt)return;
  const d=ctl.mnt;let k=d.kinds||[];
  if(t.checked){if(!k.includes(t.dataset.mk))k=k.concat(t.dataset.mk)}else k=k.filter(x=>x!==t.dataset.mk);
  d.kinds=MKINDS.filter(x=>k.includes(x));d.type=d.kinds.join(', ');
  const o=t.closest('.mkinds').querySelector('.mkold');if(o)o.remove();
});
/* équipement : Trampoline, Ninja Warrior, Plaine de jeux, Air bag, Autre (+ texte libre) */
const mntEq=x=>x&&x.equip==='Autre'&&(x.equipAutre||'').trim()?'Autre : '+x.equipAutre.trim():(x&&x.equip)||'';
const mntEqOpts=d=>MEQ.concat(!d.equip||MEQ.includes(d.equip)?[]:[d.equip]).map(x=>`<option ${d.equip===x?'selected':''}>${esc(x)}</option>`).join('');
const mntEqOther=d=>`<div id="mnteqo" ${d.equip==='Autre'?'':'hidden'}>${fl('Précisez l’équipement',`<input data-f="mnt.equipAutre" value="${esc(d.equipAutre||'')}" placeholder="Écrivez l’équipement concerné" maxlength="80" autocomplete="off">`)}</div>`;
document.addEventListener('change',e=>{
  const t=e.target;if(!t.dataset||t.dataset.f!=='mnt.equip')return;
  const o=document.getElementById('mnteqo');if(!o)return;
  o.hidden=t.value!=='Autre';
  if(t.value==='Autre'){const i=o.querySelector('input');if(i)i.focus()}
});
/* la liste d'équipements demandée remplace une ancienne liste personnalisée, une seule fois */
function v61Init(){
  plEndInit();
  if(typeof webInit==='function')webInit();
  try{
    if(S&&S.settings&&!S.settings.meqInit){
      S.settings.meqInit=1;
      if(S.settings.lists&&S.settings.lists.meq){delete S.settings.lists.meq;if(!Object.keys(S.settings.lists).length)delete S.settings.lists}
      save();
    }
  }catch(e){}
}

/* -- 4. Mise en norme de la caisse : assistant pas à pas en tête de Paramètres › Conformité ----- */
/* Chaque étape se coche toute seule d'après les données réelles ; un bouton mène à l'action. */
function cfwSteps(){
  cfEns();
  const lg=S.settings.legal||{},leg=S.sales.filter(s=>cfReal(s)&&!s.h).length,locked=cfLocked(),now=Date.now();
  const lv=S.cf.lastVerify,le=S.cf.lastExport,chk=S.cf.chk||{},yr=new Date().getFullYear();
  const late=locked&&cfDocs().some(s=>ymd(s.ts)<today()&&!cfCovered(s));
  const fd=ts=>new Date(ts).toLocaleDateString('fr-FR');
  const S1=!!(lg.raison&&lg.siret&&(lg.franchise||lg.tva));
  return [
    {id:'id',ok:S1,t:'Identité de l’exploitant',
      d:S1?esc(lg.raison)+' · SIRET '+esc(lg.siret)+' · '+(lg.franchise?'franchise en base de TVA':'TVA '+esc(lg.tva)):'Nom, SIRET et régime de TVA : ils s’impriment sur chaque ticket. À faire avant la première vente.',
      b:S1?'':'<button type="button" class="btn primary" data-act="cfw_legal">Compléter</button>'},
    {id:'test',ok:!(leg>0&&!locked),t:'Tickets d’essai supprimés',
      d:(leg>0&&!locked)?leg+' ticket'+(leg>1?'s':'')+' d’essai en attente. Supprimez-les maintenant : après la première vente, ce ne sera plus possible.':'Aucun ticket d’essai en attente.',
      b:(leg>0&&!locked)?'<button type="button" class="btn primary" data-act="cf_purge">Supprimer les tickets d’essai</button>':''},
    {id:'live',ok:locked,wait:!locked,t:'Mise en service',
      d:locked?'La caisse est en service : chaque ticket est scellé et ne peut plus être modifié (on l’annule par un avoir).':'Rien à faire : la caisse se met en service toute seule à la première vente réelle.',b:''},
    {id:'z',ok:locked&&!late,wait:!locked,t:'Clôtures des journées',
      d:!locked?'Après la première vente : une clôture est faite automatiquement chaque jour (puis chaque mois et chaque année).':late?'Des journées passées ne sont pas encore clôturées.':'À jour : une clôture automatique par jour.',
      b:late?'<button type="button" class="btn primary" data-act="cfw_roll">Clôturer maintenant</button>':''},
    {id:'ver',ok:!!(lv&&lv.ok&&now-lv.ts<32*864e5),wait:!locked,t:'Vérification d’intégrité',
      d:lv&&lv.ok&&now-lv.ts<32*864e5?'Aucune anomalie, vérifiée le '+fd(lv.ts)+'. À refaire une fois par mois.':lv&&!lv.ok?'Des anomalies ont été détectées à la dernière vérification : relancez-la et ouvrez le détail.':'À lancer une fois par mois : elle contrôle que rien n’a été modifié.',
      b:'<button type="button" class="btn'+(locked?' primary':'')+'" data-act="cf_verify">Vérifier maintenant</button>'},
    {id:'arc',ok:!!(le&&now-le.ts<366*864e5),wait:!locked,t:'Archive à conserver',
      d:le&&now-le.ts<366*864e5?'Dernière archive le '+fd(le.ts)+' (année '+le.y+'). À refaire au moins une fois par an ; à garder 6 ans.':'Fichier ZIP de tous les tickets et clôtures : au moins une fois par an, à garder 6 ans.',
      b:'<button type="button" class="btn" data-act="cf_export" data-y="'+yr+'">Archive '+yr+'</button>'},
    {id:'att',ok:!!chk.att,t:'Attestation de l’éditeur',
      d:chk.att?'Signée et classée le '+fd(chk.att)+'.':'C’est le justificatif en cas de contrôle : éditez-la, relisez-la avec votre expert-comptable, signez-la et classez-la avec vos documents comptables.',
      b:'<button type="button" class="btn" data-act="cf_att">Attestation (PDF)</button><button type="button" class="btn'+(chk.att?'':' primary')+'" data-act="cfw_ok" data-k="att">'+(chk.att?'Marquer à refaire':'C’est signé et classé')+'</button>'}
  ];
}
function cfwCard(){
  const st=cfwSteps(),n=st.filter(x=>x.ok).length,all=n===st.length,pc=Math.round(n/st.length*100);
  return `<div class="card cfw" id="cfw"><div class="cfwh"><div><h3>Mise en norme de la caisse</h3><p class="muted">${all?'Tout est en règle : la caisse est prête pour un contrôle.':'Suivez les étapes dans l’ordre : chacune se coche toute seule quand c’est fait.'}</p></div><span class="cfwp ${all?'ok':''}">${n} / ${st.length}</span></div>
    <div class="cfwbar" role="progressbar" aria-valuenow="${pc}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pc}%"></i></div>
    <ol class="cfwl">${st.map((x,i)=>`<li class="${x.ok?'ok':x.wait?'wait':'todo'}"><span class="cfwi" aria-hidden="true">${x.ok?'<svg viewBox="0 0 24 24" class="i"><path d="M5 12.5l4.5 4.5L19 7.5" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>':(i+1)}</span><div class="cfwt"><b>${x.t}${x.ok?'<em class="sr"> : fait</em>':x.wait?'<em class="sr"> : plus tard</em>':'<em class="sr"> : à faire</em>'}</b><span>${x.d}</span></div><div class="cfwa">${x.b}</div></li>`).join('')}</ol></div>`;
}
function cfwRefresh(){const c=document.getElementById('cfw');if(c&&isAdmin())c.outerHTML=cfwCard()}
function vSetCF(m){
  vSetCFBase(m);
  if(isAdmin()&&m.querySelector('.cfcols'))m.insertAdjacentHTML('afterbegin',cfwCard());
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="cfw_legal"],[data-act="cfw_roll"],[data-act="cfw_ok"],[data-act="cf_att"],[data-act="cf_verify"],[data-act="cf_export"]');if(!b||!isAdmin())return;
  const a=b.dataset.act;
  if(a==='cfw_legal'){
    const h=[...document.querySelectorAll('.cfcard h3')].find(x=>x.textContent==='Informations légales'),c=h&&h.closest('.card');
    if(c){c.scrollIntoView({block:'center',behavior:'smooth'});const i=[...c.querySelectorAll('input[data-lg]')].find(x=>x.type!=='checkbox'&&!x.value);if(i)setTimeout(()=>i.focus({preventScroll:true}),350)}
  }else if(a==='cfw_roll'){const k=zRoll();toast(k?k+' clôture'+(k>1?'s':'')+' effectuée'+(k>1?'s':''):'Rien à clôturer');cfwRefresh()}
  else if(a==='cfw_ok'){cfEns();S.cf.chk=S.cf.chk||{};if(S.cf.chk[b.dataset.k])delete S.cf.chk[b.dataset.k];else S.cf.chk[b.dataset.k]=Date.now();save();cfwRefresh()}
  else setTimeout(cfwRefresh,400);
});

/* -- 5. Bracelets en direct : écran plein écran, à afficher sur une tablette ou une télé ---------- */
/* Couleur à remettre maintenant, prochain retrait avec compte à rebours, retraits heure par heure.
   Reprend les ventes de la caisse et les réservations Qweekle du jour ; se met à jour à la seconde. */
function brItems(ds){
  const L=[];
  S.sales.forEach(s=>{
    if(!s.slot||s.ty==='av'||s.qw||!s.slot.startsWith(ds))return;
    L.push({start:+s.slot.split('|')[1],dur:s.dur||60,n:s.jumpers||0,name:s.clientId&&typeof clientName==='function'?clientName(s.clientId):'',src:'caisse'});
  });
  (typeof qwres==='function'?qwres():[]).forEach(x=>{if(x.date===ds)L.push({start:+x.start,dur:x.dur||60,n:x.n||1,name:x.name||'',src:'qweekle'})});
  (Array.isArray(S.web)?S.web:[]).forEach(b=>{if(b.date!==ds||(b.st!=='ok'&&b.st!=='full'))return;(b.items||[]).forEach(it=>{if(it.dur)L.push({start:b.start,dur:it.dur,n:it.q,name:b.name||'',src:'web'})})});
  return L.filter(x=>x.n>0&&isFinite(x.start)).sort((a,b)=>a.start-b.start);
}
const brDurLbl=d=>d<60?d+' min':d%60?Math.floor(d/60)+' h '+String(d%60).padStart(2,'0'):(d/60)+' h';
function brDurs(){
  const s=new Set();(S.products||[]).forEach(p=>{if(p.jumper&&p.dur)s.add(p.dur)});
  const a=[...s].sort((x,y)=>x-y);return a.length?a:[60,90];
}
function brData(now){
  now=now||new Date();
  const ds=today(),sec=now.getHours()*3600+now.getMinutes()*60+now.getSeconds(),nm=sec/60;
  const items=brItems(ds);
  const present=items.filter(x=>x.start<=nm&&nm<x.start+x.dur).reduce((a,x)=>a+x.n,0);
  const q=Math.floor(nm/15)*15;
  const give=brDurs().map(d=>({d,b:bracelet(q,d)}));
  const byH={};items.forEach(x=>{const b=bracelet(x.start,x.dur);(byH[b.until]=byH[b.until]||{b,n:0});byH[b.until].n+=x.n});
  const nh=Math.floor(nm/60)+1;                              // prochaine heure pleine
  const rows=[];const last=Math.max(nh,...Object.keys(byH).map(Number),S.settings.close||19);
  for(let h=Math.max(S.settings.open||10,Math.floor(nm/60));h<=Math.min(last,24);h++){
    const c=BR[h%6];rows.push({h,name:c[0],color:c[1],n:(byH[h]||{n:0}).n,past:h*60<=nm});
  }
  const next=BR[nh%6],left=Math.max(0,nh*3600-sec);
  const soon=items.filter(x=>x.start>nm&&x.start<=nm+60).map(x=>({...x,b:bracelet(x.start,x.dur)}));
  return {ds,present,q,give,rows,nh,next:{name:next[0],color:next[1],n:(byH[nh]||{n:0}).n,left},soon,total:items.reduce((a,x)=>a+x.n,0)};
}
const brClock=d=>String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
function brCount(s){const m=Math.floor(s/60),x=s%60;return (m>=60?Math.floor(m/60)+' h ':'')+String(m%60).padStart(m>=60?2:1,'0')+' min '+String(x).padStart(2,'0')+' s'}
function brHtml(){
  const now=new Date(),D=brData(now),pl=n=>n+' personne'+(n>1?'s':'');
  const sw=(c,big)=>`<i class="brl-sw${big?' big':''}" style="background:${c}"></i>`;
  const give=D.give.map(g=>`<div class="brl-g">${sw(g.b.color,1)}<div><b>${g.b.name}</b><span>${brDurLbl(g.d)} · sortie à ${g.b.exit}</span></div></div>`).join('');
  const rows=D.rows.map(r=>`<div class="brl-r${r.past?' past':''}${r.h===D.nh?' nxt':''}"><b class="num">${r.h}h</b>${sw(r.color)}<span>${r.name}</span><em>${r.n?pl(r.n):'—'}</em></div>`).join('');
  const soon=D.soon.length?D.soon.map(x=>`<div class="brl-a"><b class="num">${fm(x.start)}</b>${sw(x.b.color)}<span>${esc(x.name||(x.src==='qweekle'?'Réservation Qweekle':x.src==='web'?'Réservation en ligne':'Vente caisse'))}</span><em>${pl(x.n)}</em></div>`).join(''):'<p class="brl-none">Personne n’est attendu dans l’heure.</p>';
  return `<div class="brl-top"><div class="brl-clock"><b class="num">${brClock(now)}</b><span class="num">:${String(now.getSeconds()).padStart(2,'0')}</span></div>
      <div class="brl-info"><div class="brl-date">${esc(now.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))}</div><div class="brl-pres"><b class="num">${D.present}</b> présent${D.present>1?'s':''} dans le parc</div></div></div>
    <div class="brl-grid">
      <section class="brl-p brl-now"><h2>À remettre maintenant</h2><p class="brl-sub">Départ de ${fm(D.q)}</p>${give}</section>
      <section class="brl-p brl-next" style="--bc:${D.next.color}"><h2>Prochain retrait</h2><div class="brl-big">${sw(D.next.color,1)}<div><b>${D.next.name}</b><span>à ${D.nh}h00</span></div></div>
        <div class="brl-cd num" aria-live="off">dans ${brCount(D.next.left)}</div><p class="brl-sub">${D.next.n?pl(D.next.n)+' à retirer':'Personne à retirer'}</p></section>
      <section class="brl-p brl-tl"><h2>Retraits heure par heure</h2>${rows}</section>
      <section class="brl-p brl-arr"><h2>Arrivées dans l’heure</h2>${soon}</section>
    </div>`;
}
let BRL={t:0,lock:null};
function brOpen(){
  if(document.getElementById('brlive'))return;
  const e=document.createElement('div');e.id='brlive';e.setAttribute('role','dialog');e.setAttribute('aria-modal','true');e.setAttribute('aria-label','Bracelets en direct');
  e.innerHTML=`<div class="brl-bar"><span class="brl-live"><i></i>En direct</span><div class="brl-acts"><button type="button" class="brl-b" data-act="brlive_fs">Plein écran</button><button type="button" class="brl-b" data-act="brlive_x" aria-label="Fermer l’écran bracelets">Fermer</button></div></div><div id="brlbody"></div>`;
  document.body.appendChild(e);document.body.classList.add('brl-on');
  const draw=()=>{const b=document.getElementById('brlbody');if(b)b.innerHTML=brHtml()};
  draw();BRL.t=setInterval(draw,1000);
  try{if(navigator.wakeLock)navigator.wakeLock.request('screen').then(l=>{BRL.lock=l}).catch(()=>{})}catch(_){}
  const x=e.querySelector('[data-act="brlive_x"]');if(x)x.focus();
}
function brClose(){
  clearInterval(BRL.t);BRL.t=0;
  try{if(BRL.lock){BRL.lock.release();BRL.lock=null}}catch(_){}
  try{if(document.fullscreenElement)document.exitFullscreen()}catch(_){}
  const e=document.getElementById('brlive');if(e)e.remove();document.body.classList.remove('brl-on');
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="brlive"],[data-act="brlive_x"],[data-act="brlive_fs"]');if(!b)return;
  const a=b.dataset.act;
  if(a==='brlive')brOpen();
  else if(a==='brlive_x')brClose();
  else{const el=document.getElementById('brlive');try{if(document.fullscreenElement)document.exitFullscreen();else if(el&&el.requestFullscreen)el.requestFullscreen().catch(()=>toast('Plein écran non disponible ici : utilisez le mode plein écran du navigateur (F11)'));else toast('Plein écran non disponible ici : utilisez le mode plein écran du navigateur (F11)')}catch(_){}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('brlive')&&!document.fullscreenElement)brClose()});
function vBracelets(m){
  vBraceletsBase(m);
  const D=brData(),first=m.firstElementChild;
  const card=`<div class="card brlcard"><div><h3>En direct</h3><p class="muted">Un écran à afficher sur une tablette ou une télé : couleur à remettre maintenant, prochain retrait avec compte à rebours et nombre de personnes, mis à jour à la seconde. ${D.present} présent${D.present>1?'s':''} dans le parc en ce moment.</p></div><button type="button" class="btn primary" data-act="brlive">${ic('wave')}Ouvrir l’écran bracelets</button></div>`;
  if(first)first.insertAdjacentHTML('afterend',card);else m.insertAdjacentHTML('afterbegin',card);
}

/* ===== Réservation en ligne : page publique à intégrer sur le site du parc ===========================
   - La page (reserver.html) lit dans la base Firebase les places libres (nœud pub/<clé>/base + web)
     et y dépose la demande de réservation, CHIFFRÉE avec la clé publique du parc (RSA-OAEP + AES-GCM).
   - Lago lit les demandes, les déchiffre avec la clé privée (gardée dans les réglages synchronisés),
     crée la réservation, la fiche client et bloque les places dans le planning.
   - Paiement : sur place pour l'instant (le paiement Stripe viendra ensuite, il demande un serveur). */
const WEB_PAGE='https://lago-software.github.io/reserver.html';
const WEB_DEF=()=>({on:false,k:'',cap:120,lead:120,days:60,max:12,prods:null,adds:null,desc:{},info:'',cgv:'',pre:'RES',pub:null,priv:null});
const WEBR={t:0,h:'',rec:0,seen:0,busy:false,err:'',ok:0,pend:0};
function webCfg(){const s=S.settings;s.web=Object.assign(WEB_DEF(),s.web||{});return s.web}
const webArr=()=>Array.isArray(S.web)?S.web:(S.web=[]);
const wb64=b=>{const a=new Uint8Array(b);let s='';for(let i=0;i<a.length;i++)s+=String.fromCharCode(a[i]);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
const wunb64=t=>{t=String(t).replace(/-/g,'+').replace(/_/g,'/');while(t.length%4)t+='=';const s=atob(t),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a};
/* produits proposés : par défaut les formules « sauteur » avec une durée, et deux options courantes */
function webDefaults(w){
  const P=S.products||[];
  if(!Array.isArray(w.prods))w.prods=P.filter(p=>p.jumper&&p.dur&&p.active!==false).map(p=>p.id);
  if(!Array.isArray(w.adds))w.adds=P.filter(p=>p.active!==false&&!p.jumper&&!p.event&&p.cat==='park'&&/accompagnateur|chaussette/i.test(p.name)).map(p=>p.id);
  return w;
}
const webProd=id=>(S.products||[]).find(p=>p.id===id);
function webSite(w){return w.k||(w.k=Array.from(crypto.getRandomValues(new Uint8Array(20)),x=>'abcdefghijklmnopqrstuvwxyz0123456789'[x%36]).join(''))}
async function webKeys(w){
  if(w.pub&&w.priv)return;
  const kp=await crypto.subtle.generateKey({name:'RSA-OAEP',modulusLength:2048,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['encrypt','decrypt']);
  const pub=await crypto.subtle.exportKey('jwk',kp.publicKey),priv=await crypto.subtle.exportKey('jwk',kp.privateKey);
  w.pub={n:pub.n,e:pub.e};w.priv=priv;
}
async function webOpen(r){
  const w=webCfg();
  const pk=await crypto.subtle.importKey('jwk',w.priv,{name:'RSA-OAEP',hash:'SHA-256'},false,['decrypt']);
  const raw=await crypto.subtle.decrypt({name:'RSA-OAEP'},pk,wunb64(r.k));
  const key=await crypto.subtle.importKey('raw',raw,'AES-GCM',false,['decrypt']);
  const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:wunb64(r.iv)},key,wunb64(r.ct));
  return JSON.parse(new TextDecoder().decode(pt));
}
const webDb=()=>{const c=cloudCfg();return c&&c.u?c.u.replace(/\/+$/,''):''};
const webDbNow=()=>{const c=cloudCfg();return c&&c.u?cHostFor(c,c.alt):''};
const webU=p=>webDbNow()+'/pub/'+webCfg().k+'/'+p+'.json';
const webReady=()=>{const w=webCfg();return !!(w.on&&w.k&&w.pub&&w.priv&&cloudOn())};
function webEmbedParam(){const w=webCfg();return wb64(new TextEncoder().encode(JSON.stringify({u:webDb(),k:w.k,p:w.pub,...(payCfg().pub?{s:payCfg().pub}:{})})))}
const webLink=()=>WEB_PAGE+'?c='+webEmbedParam();
function webIframe(){
  return `<iframe id="lago-resa" src="${webLink()}" title="Réserver une session" style="width:100%;min-height:760px;border:0" loading="lazy"></iframe>\n<scr`+`ipt>addEventListener('message',function(e){if(e.origin==='https://lago-software.github.io'&&e.data&&e.data.lagoHeight){document.getElementById('lago-resa').style.height=e.data.lagoHeight+'px'}})</scr`+`ipt>`;
}
function webRules(){
  const c=cloudCfg(),w=webCfg();
  return `{\n  "rules": {\n    ".read": false,\n    ".write": false,\n    "${c?c.r:'room'}": { ".read": true, ".write": true },\n    "pub": {\n      "${w.k}": {\n        "cfg":  { ".read": true, ".write": true },\n        "base": { ".read": true, ".write": true },\n        "web": {\n          ".read": true, ".write": true,\n          "$d": { "$i": { ".validate": "newData.isNumber() && newData.val() >= 0 && newData.val() <= 1000" } }\n        },\n        "pay": { ".read": true, ".write": true, ".validate": "newData.hasChildren(['b','s']) && newData.child('b').isString() && newData.child('b').val().length < 120000 && newData.child('s').isString() && newData.child('s').val().length < 200" },\n        "pn": {\n          ".read": true, ".indexOn": ["t"],\n          "$ref": {\n            ".write": "$ref.length >= 9 && $ref.length <= 11 && $ref.contains('-') && (!newData.exists() ? data.child('t').val() < now - 2592000000 : (!data.exists() || newData.child('s').val() >= data.child('s').val()))",\n            ".validate": "newData.hasChildren(['t','s','a']) && newData.child('t').isNumber() && newData.child('s').isNumber() && newData.child('s').val() >= 1 && newData.child('s').val() <= 2 && newData.child('a').isNumber() && newData.child('a').val() >= 0 && newData.child('a').val() <= 10000000"\n          }\n        },\n        "req": {\n          ".read": true, ".indexOn": ["ts"],\n          "$id": {\n            ".write": "!data.exists() || (!newData.exists() && data.child('ts').val() < now - 604800000)",\n            ".validate": "newData.hasChildren(['ts','k','iv','ct']) && newData.child('ts').isNumber() && newData.child('ts').val() > now - 600000 && newData.child('ts').val() < now + 600000 && newData.child('ct').isString() && newData.child('ct').val().length < 8000"\n          }\n        }\n      }\n    }\n  }\n}`;
}
/* ---------- publication des places libres ---------- */
const webSlotCap=()=>S.settings.cap;
function webLoad(ds,t){
  const cap=S.settings.cap;if(S.closed&&S.closed[ds+'|'+t])return cap;
  const h=Math.floor(t/60);let l=(!S.noDemo&&h>=S.settings.open&&h<S.settings.close)?baseBooked(ds,h):0;
  S.sales.forEach(s=>{if(s.wb||!s.slot||!s.slot.startsWith(ds))return;const st=+s.slot.split('|')[1];if(st<=t&&t<st+(s.dur||60))l+=s.jumpers||0});
  return Math.min(cap,l);
}
function webBase(w){
  const out={},t0=today();
  for(let i=0;i<=w.days;i++){
    const ds=addDays(t0,i),h=hoursFor(ds);
    if(h.closed||!(h.c>h.o)){out[ds]={x:1};continue}
    const o=Math.ceil(h.o/15)*15,c=Math.floor(h.c/15)*15,l=[];
    for(let m=o;m+15<=c;m+=15)l.push(webLoad(ds,m));
    out[ds]={o,c,l};
  }
  return out;
}
function webCfgOut(w){
  const P=(ids,adds)=>ids.map(webProd).filter(p=>p&&p.active!==false&&(adds||(p.jumper&&p.dur))).map(p=>{const o={id:p.id,n:p.name,d:(w.desc&&w.desc[p.id])||'',p:p.price};if(!adds)o.dur=p.dur;return o});
  return{v:1,on:true,name:S.settings.name||'',tel:S.settings.phone||'',mail:mlMailStr(),addr:S.settings.addr||'',brand:S.settings.brand||'#1D4FD7',accent:S.settings.accent||'#FF7A1A',
    cap:S.settings.cap,wcap:Math.min(S.settings.cap,w.cap),lead:w.lead,days:w.days,max:w.max,tz:(()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Paris'}catch(e){return 'Europe/Paris'}})(),
    info:w.info||'',cgv:w.cgv||'',...(()=>{const lg=S.settings.legal||{},c=cnf();return{lg:{r:lg.raison||'',f:lg.forme||'',a:lg.adr||'',s:lg.siret||'',t:lg.franchise?'':(lg.tva||''),fr:!!lg.franchise,m:lg.mail||mlMailStr()},med:{n:c.med.n||'',u:c.med.u||''},ret:c.ret.y,cv:'T1-'+cfSha(JSON.stringify([w.cgv||'',lg.raison,lg.siret,lg.adr,c.med.n,c.med.u])).slice(0,8)}})(),pre:(w.pre||'RES').slice(0,4),br:BR.map(b=>[b[0],b[1]]),prods:P(w.prods||[],false),adds:P(w.adds||[],true),upd:Date.now()};
}
async function webPublish(force){
  const w=webCfg();if(!webReady())return false;
  const cfgO=webCfgOut(w),baseO=webBase(w),h=JSON.stringify([{...cfgO,upd:0},baseO]);
  if(!force&&h===WEBR.h&&Date.now()-WEBR.t<600000)return true;
  try{
    const r=await fetch(webU('').replace(/\.json$/,'')+'.json',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({cfg:cfgO,base:baseO})});
    if(!r.ok)throw new Error('http '+r.status);
    WEBR.h=h;WEBR.t=Date.now();WEBR.err='';w.lastPub=WEBR.t;return true;
  }catch(e){WEBR.err=/40[13]/.test(String(e.message))?'Règles Firebase à mettre à jour (voir Paramètres › Réservation en ligne)':'Hors ligne';return false}
}
let webTimer=0;
function webSched(){if(!webCfg().on)return;clearTimeout(webTimer);webTimer=setTimeout(()=>{webPublish().catch(()=>{})},4000)}
{const f0=save;save=function(){f0();webSched()}}
/* ---------- compteurs de places réservées en ligne ---------- */
function webLines(b){return (b.items||[]).filter(it=>it.dur)}
function webSlots(b){
  const o={};
  webLines(b).forEach(it=>{for(let m=b.start;m<b.start+it.dur;m+=15)o[m/15]=(o[m/15]||0)+it.q});
  return Object.entries(o).map(([i,n])=>[+i,n]);
}
async function webCounters(b,sign){
  if(!cloudOn()||!webCfg().k)return false;
  const body={};webSlots(b).forEach(([i,n])=>{body[i]={'.sv':{increment:sign*n}}});
  try{const r=await fetch(webU('web/'+b.date),{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)});return r.ok}catch(e){return false}
}
async function webReconcile(){
  if(!webReady())return;
  const exp={},t0=addDays(today(),-1);
  webArr().filter(b=>(b.st==='ok'||b.st==='full')&&b.date>=t0).forEach(b=>webSlots(b).forEach(([i,n])=>{(exp[b.date]=exp[b.date]||{});exp[b.date][i]=(exp[b.date][i]||0)+n}));
  try{const r=await fetch(webU('web'),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(Object.keys(exp).length?exp:null)});if(r.ok)WEBR.rec=Date.now()}catch(e){}
}
/* ---------- importer les demandes ---------- */
function webRebuild(){
  S.sales=S.sales.filter(s=>!s.wb);
  webArr().forEach(b=>{
    if(b.st!=='ok'&&b.st!=='full')return;
    webLines(b).forEach(it=>S.sales.push({id:'wb'+b.id+'_'+it.pid,no:'WEB-'+b.ref,ts:b.ts||Date.now(),lines:[],sub:0,disc:0,total:0,vat:{},pay:[],clientId:b.clientId||null,slot:b.date+'|'+b.start,dur:it.dur,jumpers:it.q,qw:true,wb:true,wbId:b.id,qwName:b.name,qwRef:b.ref}));
  });
}
function webClient(b,p){
  const em=(p.mail||'').trim().toLowerCase();
  let c=em&&S.clients.find(x=>(x.email||'').trim().toLowerCase()===em);
  if(!c){c={id:'cw'+b.id,name:b.name,phone:b.phone,email:p.mail||'',optin:!!p.optin,pts:0,note:'Réservation en ligne',kid:'',rewards:[]};S.clients.push(c)}
  else if(p.optin&&!c.optin)c.optin=true;
  return c.id;
}
async function webIngest(id,r){
  if(webArr().some(b=>b.id===id))return null;
  let p;try{p=await webOpen(r)}catch(e){return null}
  const w=webCfg(),t0=today();
  if(!p||p.v!==1||!/^\d{4}-\d{2}-\d{2}$/.test(p.date||'')||!Number.isInteger(p.start)||p.start%15||p.start<0||p.start>1440||p.date<addDays(t0,-1)||p.date>addDays(t0,w.days+1))return null;
  const items=[];let people=0;
  for(const it of (Array.isArray(p.items)?p.items.slice(0,12):[])){
    const pr=webProd(it.id),q=Math.floor(+it.q);if(!pr||!(q>=1&&q<=w.max))continue;
    const sess=(w.prods||[]).includes(pr.id)&&pr.jumper&&pr.dur,add=(w.adds||[]).includes(pr.id);
    if(!sess&&!add)continue;
    items.push({pid:pr.id,q,n:pr.name,price:pr.price,...(sess?{dur:pr.dur}:{})});if(sess)people+=q;
  }
  if(!people||people>w.max)return null;
  const clean=(s,n)=>String(s==null?'':s).replace(/[\u0000-\u001f]/g,' ').trim().slice(0,n);
  const b={id,ref:clean(p.ref,14)||('WEB-'+id.slice(0,5).toUpperCase()),ts:+r.ts||Date.now(),date:p.date,start:p.start,items,people,total:items.reduce((a,x)=>a+x.q*x.price,0),
    name:clean(p.name,80),mail:clean(p.mail,120),phone:clean(p.phone,20),note:clean(p.note,300),optin:!!p.optin,cv:clean(p.cv,16),st:'ok'};
  /* places encore libres ? (la page a déjà réservé les places, ce contrôle est un filet de sécurité) */
  const longest=Math.max(...items.filter(x=>x.dur).map(x=>x.dur));
  for(let m=b.start;m<b.start+longest;m+=15){
    const nd=items.reduce((a,x)=>a+(x.dur&&m<b.start+x.dur?x.q:0),0);
    if(!openAt(b.date,m)||S.settings.cap-occ(b.date,m)<nd){b.st='full';break}
  }
  b.clientId=webClient(b,p);
  webArr().push(b);webRebuild();
  return b;
}
async function webPoll(){
  const w=webCfg();if(!webReady()||WEBR.busy)return;
  WEBR.busy=true;
  try{
    let r=await fetch(webU('req')+'?orderBy="ts"&startAt='+Math.max(0,(w.seen||0)-900000),{cache:'no-store'});
    if(r.status===400)r=await fetch(webU('req'),{cache:'no-store'});
    if(!r.ok)throw new Error('http '+r.status);
    const J=await r.json()||{},made=[];let maxTs=w.seen||0;
    for(const id of Object.keys(J)){
      const q=J[id];if(!q||!q.ct)continue;maxTs=Math.max(maxTs,+q.ts||0);
      const b=await webIngest(id,q);if(b)made.push(b);
    }
    WEBR.err='';WEBR.ok=Date.now();
    if(maxTs>(w.seen||0))WEBR.seen=w.seen=maxTs;
    if(made.length){
      save();
      toast(made.length===1?'Nouvelle réservation en ligne : '+made[0].name+' · '+dshort(made[0].date)+' '+fm(made[0].start):made.length+' nouvelles réservations en ligne');
      if(view==='resa'&&(tab.resa==='web'||tab.resa==='apercu'||tab.resa==='bracelets'))render();
    }
    /* nettoyage des demandes de plus de 8 jours, déjà importées */
    const old=Object.keys(J).filter(id=>J[id]&&+J[id].ts<Date.now()-8*86400000&&webArr().some(b=>b.id===id));
    for(const id of old.slice(0,20))fetch(webU('req/'+id),{method:'DELETE'}).catch(()=>{});
    WEBR.pend=0;
    /* remise à jour des compteurs publics : après un moment sans nouvelle demande */
    if(Date.now()-WEBR.rec>300000&&Date.now()-Math.max(maxTs,WEBR.seen||0)>180000)await webReconcile();
  }catch(e){WEBR.err='Hors ligne'}
  finally{WEBR.busy=false}
}
async function webTick(){
  if(typeof ME==='undefined'||!ME||document.visibilityState==='hidden')return;
  const w=webCfg();if(!w.on||!cloudOn())return;
  await webPublish().catch(()=>{});
  await webPoll().catch(()=>{});
}
setInterval(()=>{webTick().catch(()=>{})},20000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')webTick().catch(()=>{})});
