  const lines=b.items.filter(x=>webProd(x.pid)).map(x=>({pid:x.pid,qty:x.q}));
  cart=newCart();cart.lines=lines;cart.slotDate=b.date;cart.slotM=b.start;cart.clientId=b.clientId||null;cart.web=b.id;
  closeModal();
