TABS.params.splice(Math.max(1,TABS.params.findIndex(x=>x[0]==='pweb')+1),0,['ppay','Paiement en ligne']);SUBS.ppay=vSetPay;
let payTm=0;
const payDirty=()=>{clearTimeout(payTm);payTm=setTimeout(()=>{save();payPublish(true).then(()=>{const s=$('#pay_stat');if(s&&payCfg().on&&webReady()&&!PAYS.err)s.textContent='Page de paiement publiée à '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})+'.'})},700)};
let payRB=0;
const payRedo=()=>{if(payRB)return;const sub=$('#sub');if(!sub)return;payRB=1;try{const y=window.scrollY;vSetPay(sub);window.scrollTo(0,y)}finally{payRB=0}};
function payField(t){
  const p=payCfg(),k=t.dataset.payf;let v=t.value;
  if(k==='link'){v=v.trim().split(/[?#]/)[0].replace(/\/+$/,'');
    const s=$('#pay_lnk');if(s){const ok=payLinkOk(v);s.className=ok||!v?'muted':'';s.style.color=!ok&&v?'var(--bad)':'';s.textContent=ok?'Lien valide.':v?'Ce n’est pas un lien de paiement Stripe (il commence par https://buy.stripe.com/).':'À créer dans Stripe (étapes ci-dessous).'}
    if(v&&!payLinkOk(v)){p.link=v;payPrev();return false}p.link=v}
  else if(k==='pct')p.pct=Math.max(1,Math.min(100,Math.floor(+v)||30));
  else if(k==='per'){const c=Math.round(parseFloat(String(v).replace(',','.'))*100);if(c>=100&&c<=100000)p.per=c}
  else if(k==='site'){v=v.trim();p.site=/^https:\/\/[^\s"'<>\\]{3,200}$/.test(v)?v:''}
  else p[k]=v.replace(/[\u0000-\u001f]/g,' ');
  return true;
}
document.addEventListener('input',e=>{
  const t=e.target;if(!t||view!=='params'||tab.params!=='ppay'||!isAdmin())return;
  if(t.dataset.payf){if(payField(t)!==false){payPrev();const ex=$('#pay_ex');if(ex)ex.textContent=eur(PAYR.amount(payOut(),9600,4));payDirty()}else payDirty()}
  else if(t.id==='pay_brand'||t.id==='pay_accent'){payCfg()[t.id==='pay_brand'?'brand':'accent']=t.value;payPrev();payDirty()}
});
document.addEventListener('change',e=>{
  const t=e.target;if(!t||view!=='params'||tab.params!=='ppay'||!isAdmin())return;
  const p=payCfg();
  if(t.id==='pay_on'){
    if(t.checked){
      if(!webReady()){t.checked=false;toast('Activez d’abord la réservation en ligne');return}
      if(!payLinkOk(p.link)){t.checked=false;toast('Collez d’abord votre lien de paiement Stripe');const i=$('#payf_link');if(i)i.focus();return}
      p.on=true;payKeys().then(()=>{save();return payPublish(true)}).then(ok=>{toast(ok?'Paiement en ligne activé':'Activé, mais la publication a échoué : '+(PAYS.err||'réessayez')); payRedo()});
    }else{p.on=false;save();payPublish(true).catch(()=>{});toast('Paiement en ligne désactivé');payRedo()}
    return;
  }
  if(t.dataset.paymode){p.mode=t.dataset.paymode;save();payPublish(true).catch(()=>{});payRedo();return}
  if(t.id==='pay_logo'){
    const f=t.files&&t.files[0];t.value='';if(!f)return;
    fileToData(f,160,r=>{
      const best=[r.png,r.jpg].find(x=>x.length<=60000&&PAYR.LOGO.test(x));
      if(!best){toast('Image trop lourde : choisissez un logo plus simple');return}
      p.logo=best;save();payPublish(true).catch(()=>{});payRedo();toast('Logo enregistré');
    });return;
  }
  if(t.dataset.payf){payField(t);clearTimeout(payTm);save();payPublish(true).catch(()=>{})}
});
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-payset],[data-payprev],[data-act="pay_copy"],[data-act="pay_logo_use"],[data-act="pay_logo_rm"],[data-act="pay_col_reset"],[data-act="pay_prevopen"],[data-payprev2]');
  if(!b||view!=='params'||tab.params!=='ppay'||!isAdmin())return;
  const p=payCfg();
  if(b.dataset.payset){p[b.dataset.payset]=b.dataset.v;save();payPublish(true).catch(()=>{});payRedo();return}
  if(b.dataset.payprev){PAYS.prev=b.dataset.payprev;payRedo();return}
  if(b.dataset.payprev2){PAYS.prev=b.dataset.payprev2;payOpenPrev();return}
  if(b.dataset.act==='pay_prevopen'){payOpenPrev();return}
  const a=b.dataset.act;
  if(a==='pay_copy'){const w=b.dataset.what,txt=w==='rules'?webRules():w==='iframe'?webIframe():payBack();(navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(()=>toast('Copié')).catch(()=>toast('Sélectionnez le texte et copiez-le'))}
  else if(a==='pay_logo_use'){const l=S.settings.logo||'';if(PAYR.LOGO.test(l)&&l.length<=60000){p.logo=l;save();payPublish(true).catch(()=>{});payRedo()}else toast('Ce logo ne convient pas : choisissez-en un ici')}
  else if(a==='pay_logo_rm'){p.logo='';save();payPublish(true).catch(()=>{});payRedo()}
  else if(a==='pay_col_reset'){p.brand='';p.accent='';save();payPublish(true).catch(()=>{});payRedo()}
});
/* ---- v65 : filet de sécurité — incidents techniques, santé du système, sauvegardes automatiques ---- */
const ERRK='lago-errlog';
const errLog=()=>{try{const l=JSON.parse(localStorage.getItem(ERRK)||'[]');return Array.isArray(l)?l:[]}catch(e){return[]}};
let errToastAt=0;
function noteErr(kind,msg,where){
  try{const l=errLog();l.push({t:Date.now(),k:kind,m:String(msg||'').slice(0,300),w:String(where||'').slice(0,160),v:LAGO_V,h:String(location.hash||'').slice(0,40)});while(l.length>40)l.shift();localStorage.setItem(ERRK,JSON.stringify(l))}catch(e){}
  if(Date.now()-errToastAt>300000){errToastAt=Date.now();try{toast('Un incident technique a été enregistré. Vos données sont conservées.')}catch(e){}}
}
addEventListener('error',e=>{if(e&&e.message)noteErr('js',e.message,String(e.filename||'').split('/').pop()+':'+e.lineno)});
addEventListener('unhandledrejection',e=>{const r=e&&e.reason;noteErr('promesse',(r&&r.message)||r,'')});
/* un écran qui plante ne doit jamais bloquer l'appli */
function render(){
  try{renderBase()}
  catch(e){
    noteErr('affichage',e&&e.message,String(e&&e.stack||'').split('\n')[1]||'');
    const m=document.getElementById('main');
    if(m)m.innerHTML='<div class="card" style="margin:16px"><h3>Cet écran n’a pas pu s’afficher</h3><p class="muted">Vos données ne sont pas touchées. Revenez à l’accueil ou rechargez l’appli. Si cela se répète, l’incident est enregistré dans Paramètres › Santé.</p><div class="acts"><a class="btn primary" href="#accueil">Accueil</a><button type="button" class="btn" data-act="sf_reload">Recharger</button></div></div>';
  }
}
/* stockage durable : évite que le navigateur efface les données de l'appareil */
try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(()=>{})}catch(e){}

/* ---- sauvegardes automatiques (IndexedDB, sur l'appareil de l'administrateur) ---- */
const BKDB='lago-bk';
function bkOpen(){return new Promise((res,rej)=>{try{const r=indexedDB.open(BKDB,1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('meta',{keyPath:'ts'});d.createObjectStore('blob',{keyPath:'ts'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error||new Error('IndexedDB indisponible'))}catch(e){rej(e)}})}
const bkReq=r=>new Promise((res,rej)=>{r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
async function bkList(){const db=await bkOpen();try{const l=await bkReq(db.transaction('meta').objectStore('meta').getAll());return l.sort((a,b)=>b.ts-a.ts)}finally{db.close()}}
async function bkSnap(auto,why){
  const json=JSON.stringify({lago:1,ts:Date.now(),data:S}),ts=Date.now(),db=await bkOpen();
  try{
    await new Promise((res,rej)=>{const t=db.transaction(['meta','blob'],'readwrite');t.objectStore('meta').put({ts,kb:Math.round(json.length/1024),auto:!!auto,why:why||'',v:LAGO_V,n:(S.sales||[]).length});t.objectStore('blob').put({ts,json});t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||new Error('écriture annulée'))});
    const all=await bkReq(db.transaction('meta').objectStore('meta').getAll());
    const au=all.filter(x=>x.auto).sort((a,b)=>b.ts-a.ts),ma=all.filter(x=>!x.auto).sort((a,b)=>b.ts-a.ts);
    const drop=[...au.slice(14),...ma.slice(6)];
    if(drop.length)await new Promise(res=>{const t=db.transaction(['meta','blob'],'readwrite');drop.forEach(x=>{t.objectStore('meta').delete(x.ts);t.objectStore('blob').delete(x.ts)});t.oncomplete=res;t.onerror=res;t.onabort=res});
  }finally{db.close()}
  BK.last=ts;return ts;
}
async function bkGet(ts){const db=await bkOpen();try{const b=await bkReq(db.transaction('blob').objectStore('blob').get(ts));return b&&b.json}finally{db.close()}}
const BK={last:0,err:''};
async function bkAuto(force){
  try{
    if(!ME||!ME.admin||!window.indexedDB)return;
    const l=await bkList();BK.last=l.length?Math.max(...l.filter(x=>x.auto).map(x=>x.ts),0):0;
    if(force||!BK.last||Date.now()-BK.last>20*3600e3){await bkSnap(true,'quotidienne');BK.err=''}
  }catch(e){BK.err=String((e&&e.message)||e);noteErr('sauvegarde',BK.err,'')}
}
setTimeout(bkAuto,25000);setInterval(()=>bkAuto(),30*60*1000);

/* ---- contrôles de santé ---- */
const LS_QUOTA=5000000;
const lsChars=()=>{try{let n=0;for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);n+=k.length+(localStorage.getItem(k)||'').length}return n}catch(e){return 0}};
const HL={ok:'ok',warn:'warn',bad:'bad'};
function hStorage(){
  const real=(S.sales||[]).filter(s=>!s.qw),now=Date.now(),recent=real.filter(s=>s.ts>now-30*864e5).length,perDay=recent/30;
  const sample=real.slice(-200),bytes=sample.length?JSON.stringify(sample).length/sample.length:0;
  if(MS.ok){
    const used=MS.size||JSON.stringify(S).length,e=MS.est||{},quota=e.quota||0,tot=e.usage||used,pc=quota?Math.round(tot/quota*100):0;
    const room=quota?Math.max(0,quota*0.8-tot):0,months=quota&&perDay>0&&bytes>0?room/(perDay*bytes*30):null;
    const bad=MS.fails>0||MS.fb;
    let lv=pc>=85?'bad':pc>=60||bad?'warn':'ok';
    const cap=quota?(quota>=1e9?(quota/1e9).toFixed(1)+' Go':Math.round(quota/1e6)+' Mo'):'';
    return{id:'stock',lv,t:'Mémoire de l’appareil',d:`Base de l’appareil : ${(used/1e6).toFixed(1)} Mo pour ${real.length} ticket(s)`+(quota?`, sur ${cap} disponibles (${pc} %)`:'')+'.'
      +(months!==null&&months<24?` Au rythme actuel : environ ${months<1?'moins d’un mois':Math.round(months)+' mois'} avant saturation.`:'')
      +(bad?' L’écriture normale a échoué : une copie de secours est utilisée, rouvrez l’appli pour que tout rentre dans l’ordre.':'')
      +(MS.persist===false?' Le navigateur peut effacer ces données s’il manque de place : installez l’appli sur l’écran d’accueil et exportez régulièrement l’archive des tickets.':'')
      +(pc>=60?' Exportez l’archive des tickets (Paramètres › Conformité).':'')};
  }
  const used=lsChars(),pc=Math.round(used/LS_QUOTA*100);
  const room=Math.max(0,LS_QUOTA*0.9-used),months=perDay>0&&bytes>0?room/(perDay*bytes*30):null;
  const lv=pc>=85?'bad':pc>=60?'warn':'ok';
  return{id:'stock',lv,t:'Mémoire de l’appareil',d:`${(used/1e6).toFixed(1)} Mo utilisés sur environ 5 Mo (${pc} %), ${real.length} ticket(s). Mode de secours : ce navigateur n’a pas ouvert la base de l’appareil.`+(months!==null?` Au rythme actuel : environ ${months>=24?'plus de 2 ans':months<1?'moins d’un mois':Math.round(months)+' mois'} avant saturation.`:'')+(lv!=='ok'?' Exportez l’archive des tickets (Paramètres › Conformité) et ouvrez Lago dans un navigateur récent (Chrome, Edge, Safari, Firefox).':'')}
}
function hSync(){
  if(!cloudOn())return{id:'sync',lv:'warn',t:'Équipe',d:'Cet appareil n’est pas relié à l’équipe : ses données ne sont pas partagées.'};
  const lv=CL.state==='ok'?'ok':CL.state==='sync'?'ok':'bad';
  let box=null;try{box=JSON.parse(localStorage.getItem(CBOX)||'null')}catch(e){}
  const n=box&&box.n?Object.keys(box.n).length:0;
  return{id:'sync',lv,t:'Synchronisation avec l’équipe',d:(CL.state==='ok'?'Connectée'+(CL.last?', dernière synchronisation à '+hm(CL.last):''):CL.state==='sync'?'Synchronisation en cours…':'Hors ligne'+(CL.err?' ('+CL.err+')':''))+(n?` · ${n} modification(s) en attente d’envoi`:'')+'.'}
}
function hBackup(){
  if(!window.indexedDB)return{id:'bk',lv:'warn',t:'Sauvegarde automatique',d:'Non disponible sur ce navigateur. Utilisez l’export manuel (Paramètres › Personnaliser).'};
  const age=BK.last?Date.now()-BK.last:Infinity;
  const lv=BK.err?'bad':age<36*3600e3?'ok':age<4*864e5?'warn':'bad';
  return{id:'bk',lv,t:'Sauvegarde automatique',d:BK.err?'Erreur : '+BK.err:BK.last?'Dernière copie : '+new Date(BK.last).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})+'.':'Aucune copie pour le moment (la première se fait dans la minute qui suit la connexion de l’administrateur).'}
}
function hAccounts(){
  const a=(S.accounts||[]).filter(x=>x.status==='active'),ad=a.filter(x=>x.admin),nopw=a.filter(x=>!x.pwd);
  const out=[];
  if(!ad.length)out.push('aucun administrateur actif');
  else if(ad.length===1)out.push('un seul administrateur : prévoyez-en un second de secours');
  if(nopw.length)out.push(nopw.length+' compte(s) sans mot de passe');
  const pend=(S.accounts||[]).filter(x=>x.status==='pending').length;if(pend)out.push(pend+' demande(s) de compte à valider');
  return{id:'acc',lv:!ad.length||nopw.length?'bad':out.length?'warn':'ok',t:'Comptes et accès',d:out.length?out.join(' · ')+'.':a.length+' compte(s) actifs, '+ad.length+' administrateur(s).'}
}
function hData(){
  const real=(S.sales||[]).filter(s=>!s.qw&&!s.wb),iss=[];
  const seen=new Map(),dup=[];
  for(const s of real){const n=s.no;if(!n)continue;if(seen.has(n))dup.push(n);else seen.set(n,1)}
  if(dup.length)iss.push(dup.length+' numéro(s) de ticket en double ('+dup.slice(0,3).join(', ')+')');
  const gap=real.filter(s=>Array.isArray(s.pay)&&s.pay.length&&Math.abs(s.pay.reduce((a,p)=>a+(+p.amt||0),0)-(+s.total||0))>0.011);
  if(gap.length)iss.push(gap.length+' ticket(s) dont les paiements ne correspondent pas au total ('+gap.slice(0,3).map(s=>s.no).join(', ')+')');
  const ids=new Set((S.products||[]).map(p=>p.id)),orph=real.filter(s=>(s.lines||[]).some(l=>l&&l.pid&&!ids.has(l.pid)&&!l.custom&&!l.name)).length;
  if(orph)iss.push(orph+' ticket(s) citent un produit supprimé');
  const neg=(S.products||[]).filter(p=>typeof p.stock==='number'&&p.stock<0);
  if(neg.length)iss.push(neg.length+' produit(s) en stock négatif ('+neg.slice(0,3).map(p=>p.name).join(', ')+')');
  const fut=real.filter(s=>s.ts>Date.now()+36e5).length;if(fut)iss.push(fut+' ticket(s) datés du futur');
  return{id:'data',lv:iss.length?'bad':'ok',t:'Cohérence des données',d:iss.length?iss.join(' · ')+'.':real.length+' ticket(s) contrôlés : numérotation unique, paiements = totaux, produits connus, aucune date incohérente.'}
}
function hLegal(){
  const lg=S.settings.legal||{},miss=[];
  if(!lg.raison)miss.push('nom de l’exploitant');if(!lg.siret)miss.push('SIRET');if(!(lg.franchise||lg.tva))miss.push('régime de TVA');
  return{id:'legal',lv:miss.length?'warn':'ok',t:'Mentions légales des tickets',d:miss.length?'À compléter dans Paramètres › Conformité : '+miss.join(', ')+'.':'Exploitant, SIRET et TVA renseignés : ils s’impriment sur chaque ticket.'}
}
function hErrors(){
  const l=errLog().filter(x=>x.t>Date.now()-864e5);
  return{id:'err',lv:l.length>=5?'bad':l.length?'warn':'ok',t:'Incidents techniques (24 h)',d:l.length?l.length+' incident(s) enregistré(s). Dernier : '+esc(l[l.length-1].m)+'.':'Aucun incident.'}
}
function hOffline(){
  const sw=!!(navigator.serviceWorker&&navigator.serviceWorker.controller);
  return{id:'sw',lv:sw||location.protocol==='file:'?'ok':'warn',t:'Fonctionnement hors connexion',d:sw?'L’appli est installée sur l’appareil : elle démarre même sans réseau.':'Pas encore installée pour le hors-connexion (ouverte depuis le site, rechargez une fois ou ajoutez-la à l’écran d’accueil).'}
}
function healthQuick(){
  const out=[];for(const f of [hStorage,hSync,hBackup,hAccounts,hLegal,hErrors,hOffline]){try{out.push(f())}catch(e){out.push({id:f.name,lv:'warn',t:f.name,d:'Contrôle impossible : '+e.message})}}
  try{if(typeof hExtra==='function')out.push(...hExtra())}catch(e){out.push({id:'extra',lv:'warn',t:'Conformité',d:'Contrôle impossible : '+e.message})}
  return out;
}
async function hClock(){
  if(!location.protocol.startsWith('http'))return{id:'clock',lv:'ok',t:'Heure de l’appareil',d:'Contrôle indisponible dans cet affichage.'};
  try{
    const t0=Date.now(),r=await fetch('sw.js',{cache:'no-store',mode:'same-origin'});
    const d=r.headers.get('date');if(!d)return{id:'clock',lv:'warn',t:'Heure de l’appareil',d:'Impossible de comparer avec un serveur.'};
    const drift=Math.round((Date.now()-new Date(d).getTime())/1000);
    return{id:'clock',lv:Math.abs(drift)>120?'bad':Math.abs(drift)>30?'warn':'ok',t:'Heure de l’appareil',d:Math.abs(drift)<=30?'Exacte (écart '+drift+' s). Les tickets sont datés à la seconde près.':'Écart de '+drift+' s avec l’heure réelle : corrigez l’heure de l’appareil, elle date les tickets et les clôtures.'}
  }catch(e){return{id:'clock',lv:'warn',t:'Heure de l’appareil',d:'Contrôle impossible hors connexion.'}}
}
function hIntegrity(){
  const lv0=S.cf&&S.cf.lastVerify;if(typeof cfVerify!=='function')return null;
  if(!lv0)return{id:'chain',lv:'warn',t:'Intégrité des tickets (chaîne scellée)',d:'Jamais vérifiée. Lancez « Vérifier l’intégrité » dans Paramètres › Conformité (une fois par mois).'};
  const age=Date.now()-lv0.ts;
  return{id:'chain',lv:!lv0.ok?'bad':age>32*864e5?'warn':'ok',t:'Intégrité des tickets (chaîne scellée)',d:(lv0.ok?'Aucune anomalie':'Anomalies détectées')+' à la dernière vérification, le '+new Date(lv0.ts).toLocaleDateString('fr-FR')+(age>32*864e5?'. À refaire une fois par mois':'')+'.'}
}
const HEALTH={res:null,at:0};
async function healthFull(){
  const q=healthQuick();q.push(hData());
  const c=await hClock();q.push(c);const i=hIntegrity();if(i)q.push(i);
  HEALTH.res=q;HEALTH.at=Date.now();return q;
}
const lvTxt={ok:'En ordre',warn:'À surveiller',bad:'À corriger'};
function healthRows(l){return l.map(x=>`<div class="row hlt" data-lv="${x.lv}"><span class="pill ${x.lv==='ok'?'ok':x.lv==='warn'?'warn':'danger'}">${lvTxt[x.lv]}</span><span class="grow"><b>${esc(x.t)}</b><span class="muted">${x.d}</span></span></div>`).join('')}
async function vSetHealth(m){
  if(!isAdmin()){m.innerHTML='<p class="muted">Réservé à l’administrateur.</p>';return}
  m.innerHTML='<div class="card"><h3>Santé du système</h3><p class="muted">Contrôle en cours…</p></div>';
  const l=await healthFull();let bks=[];try{bks=await bkList()}catch(e){}
  const bad=l.filter(x=>x.lv==='bad').length,warn=l.filter(x=>x.lv==='warn').length;
  const errs=errLog().slice(-8).reverse();
  m.innerHTML=`<div class="card" id="sfcard"><div class="cfwh"><div><h3>Santé du système <span class="pill ${bad?'danger':warn?'warn':'ok'}">${bad?bad+' à corriger':warn?warn+' à surveiller':'Tout est en ordre'}</span></h3><p class="muted">Contrôles automatiques de cet appareil et des données. Dernière vérification à ${hm(Date.now())}.</p></div><button type="button" class="btn primary" data-act="sf_check">Vérifier maintenant</button></div>${healthRows(l)}</div>
   <div class="card"><h3>Sauvegardes automatiques</h3><p class="muted">Une copie complète des données est faite chaque jour sur cet appareil (14 jours conservés), sans quitter l’appareil. Avant toute restauration, une copie de sécurité est ajoutée.</p>
    ${bks.length?bks.map(b=>`<div class="row"><span class="grow"><b>${new Date(b.ts).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'})}</b><span class="muted">${b.kb} Ko · ${b.n??'?'} ticket(s) · ${b.auto?'automatique':esc(b.why||'manuelle')} · ${esc(b.v||'')}</span></span><button type="button" class="btn" data-act="sf_dl" data-ts="${b.ts}">Télécharger</button><button type="button" class="btn" data-act="sf_rs" data-ts="${b.ts}">Restaurer</button></div>`).join(''):'<p class="muted">Aucune copie pour le moment.</p>'}
    <div class="acts" style="margin-top:10px"><button type="button" class="btn" data-act="sf_snap">Sauvegarder maintenant</button></div></div>
   <div class="card"><h3>Incidents techniques</h3>${errs.length?errs.map(e=>`<div class="row"><span class="grow"><b>${esc(e.m)}</b><span class="muted">${new Date(e.t).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'medium'})} · ${esc(e.k)} · ${esc(e.v||'')} ${esc(e.h||'')} ${esc(e.w||'')}</span></span></div>`).join(''):'<p class="muted">Aucun incident enregistré.</p>'}
    <div class="acts" style="margin-top:10px"><button type="button" class="btn" data-act="sf_copy">Copier le rapport</button><button type="button" class="btn" data-act="sf_clear">Effacer</button></div></div>`;
}
TABS.params.splice(Math.max(1,TABS.params.findIndex(x=>x[0]==='pcf')+1),0,['psante','Santé']);SUBS.psante=vSetHealth;
function sfApply(d,why){
  S=d;save();migrateSubs();migrateQ();migrateR();hoursInit();applySettings();applyTheme();applyLook();cart=newCart();
  ME=null;ROLEMODE='operator';PROF='-';try{localStorage.removeItem(SKEY);sessionStorage.removeItem(SKEY)}catch(_){}
  chrome();route();gateStart();toast(why||'Sauvegarde restaurée');
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-act^="sf_"]');if(!b)return;const a=b.dataset.act;
  if(a==='sf_reload'){location.reload();return}
  if(!isAdmin())return;
  if(a==='sf_check'){const m=document.getElementById('sub');if(m)vSetHealth(m)}
  else if(a==='sf_snap'){b.disabled=true;try{await bkSnap(false,'manuelle');toast('Copie enregistrée')}catch(err){toast('Copie impossible : '+((err&&err.message)||err))}const m=document.getElementById('sub');if(m)vSetHealth(m)}
  else if(a==='sf_dl'){try{const j=await bkGet(+b.dataset.ts);if(!j){toast('Copie introuvable');return}saveBytes('lago-sauvegarde-'+ymd(+b.dataset.ts)+'.json',new TextEncoder().encode(j),'application/json')}catch(err){toast('Téléchargement impossible')}}
  else if(a==='sf_rs'){
    const ts=+b.dataset.ts;let o=null;
    try{const j=await bkGet(ts);o=j&&JSON.parse(j)}catch(err){}
    const d=o&&o.data;
    if(!d||!d.settings||!Array.isArray(d.products)){toast('Copie illisible');return}
    askYes('Remplacer toutes les données actuelles par la copie du '+new Date(ts).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'})+' ? Une copie de sécurité de l’état actuel est faite avant.',async()=>{
      try{await bkSnap(false,'avant restauration')}catch(err){toast('Restauration annulée : la copie de sécurité a échoué');return}
      sfApply(d,'Copie restaurée');
    },'Restaurer');
  }
  else if(a==='sf_copy'){
    const rep=['Lago '+LAGO_V+' — rapport du '+new Date().toLocaleString('fr-FR'),navigator.userAgent,'',...errLog().map(x=>new Date(x.t).toISOString()+' ['+x.k+'] '+x.m+' '+x.w+' '+x.h)].join('\n');
    try{await navigator.clipboard.writeText(rep);toast('Rapport copié')}catch(err){toast('Copie refusée par le navigateur')}
  }
  else if(a==='sf_clear'){try{localStorage.removeItem(ERRK)}catch(err){}const m=document.getElementById('sub');if(m)vSetHealth(m)}
});
/* accueil de l'administrateur : un bandeau seulement s'il y a quelque chose à voir */
function vHome(m){
  vHomeY(m);
  try{poHome(m)}catch(e){console.warn(e)}
  if(!isAdmin())return;
  try{
    const l=healthQuick().filter(x=>x.lv!=='ok'&&x.id!=='sw'&&x.id!=='sync'),bad=l.filter(x=>x.lv==='bad');
    if(!l.length||!m.querySelector('.hero'))return;
    m.querySelector('.hero').insertAdjacentHTML('afterend',`<div class="banner sfban" role="status"><span><b>Santé du système :</b> ${l.slice(0,2).map(x=>esc(x.t)).join(', ')}${l.length>2?' et '+(l.length-2)+' autre(s)':''}.</span><button type="button" class="btn ${bad.length?'primary':''}" data-act="goto" data-v="params" data-t="psante">Voir</button></div>`);
  }catch(e){}
}
/* ---- v66 : conformité étendue — données personnelles (RGPD), obligations réglementaires, tableau de conformité ----
   Tout est stocké dans S.settings.conf (synchronisé avec l'équipe). Aucune donnée personnelle n'est écrite dans le journal scellé :
   il ne contient que des identifiants techniques. */
CF_T.rgpd='Données personnelles';
const CN_DAY=864e5;
const cnFr=ds=>ds?new Date(ds+'T12:00:00').toLocaleDateString('fr-FR'):'—';
const cnTs=ts=>ts?new Date(ts).toLocaleDateString('fr-FR'):'jamais';
const cnAddM=(ds,m)=>{const d=new Date(ds+'T12:00:00');const day=d.getDate();d.setMonth(d.getMonth()+m);if(d.getDate()!==day)d.setDate(0);return ymd(d.getTime())};
const cnAns=y=>y+' an'+(y>1?'s':'');
const cnDiff=(a,b)=>Math.round((new Date(a+'T12:00:00')-new Date(b+'T12:00:00'))/CN_DAY);
const cnRe=()=>{const m=document.getElementById('sub');if(m&&view==='params'&&SUBS[tab.params])SUBS[tab.params](m)};

