const tplMin=hm=>{const m=/^(\d{1,2}):(\d{2})$/.exec(hm||'');return m?(+m[1])*60+(+m[2]):null};
const tplEuros=v=>Math.round((+v||0)*100);
const tplHm=m=>{const h=Math.floor(m/60),n=m%60;return h+'h'+(n?String(n).padStart(2,'0'):'')};
const TPL_AB=['dim','lun','mar','mer','jeu','ven','sam'],TPL_DAYS=['dimanche','lundi','mardi','mercredi','jeudi','vendredi','samedi'];
function tplHoursOf(t){
  const h=(t.settings||{}).horaires;if(!h)return null;
  const o0=tplMin(h.ouverture),c0=tplMin(h.fermeture),cl=h.jours_fermes||[],ex=h.jours||{},week={};let mo=1e9,mc=0;
  for(let d=0;d<7;d++){
    if(cl.includes(d)){week[d]={closed:true,o:o0,c:c0};continue}
    let o=o0,c=c0;if(ex[d]){o=tplMin(ex[d][0]);c=tplMin(ex[d][1])}
    week[d]={closed:false,o,c};mo=Math.min(mo,o);mc=Math.max(mc,c);
  }
  if(mo===1e9){mo=o0;mc=c0}
  return{week,open:Math.floor(mo/60),close:Math.ceil(mc/60)};
}
function tplHoursText(t){
  const H=tplHoursOf(t);if(!H)return '';
  const ord=[1,2,3,4,5,6,0],runs=[];
  ord.forEach(d=>{const w=H.week[d],k=w.closed?'x':w.o+'-'+w.c,l=runs[runs.length-1];if(l&&l.k===k)l.d.push(d);else runs.push({k,d:[d],w})});
  const open=runs.filter(r=>r.k!=='x').map(r=>(r.d.length>1?TPL_AB[r.d[0]]+'–'+TPL_AB[r.d[r.d.length-1]]:TPL_AB[r.d[0]])+' '+tplHm(r.w.o)+'–'+tplHm(r.w.c));
  const cl=ord.filter(d=>H.week[d].closed).map(d=>TPL_DAYS[d]);
  return open.join(' ; ')+(cl.length?' ; fermé : '+cl.join(', '):'');
}
const tplNavLabel=id=>{const n=NAV.find(x=>x[0]===id);return n?n[1]:id};
const tplTabLabel=k=>{const [m,t]=k.split(':');const x=(TABS[m]||[]).find(y=>y[0]===t);return (x?x[1]:t)+' ('+tplNavLabel(m)+')'};
/* vocabulaire du métier (aperçus : « Réserver un départ » devient « Nouveau rendez-vous »…) : défauts = parc de trampolines */
const TV0={session:'Session JUMP',lieu:'Trampo Park',reserver:'Réserver un départ',departs:'Prochains départs',plus_de_depart:'Plus de départ aujourd’hui.',personne:'sauteur',clients_de:'Clients du parc',nom_etab:'Nom du parc'};
function tv(k){const t=S&&S.settings&&S.settings.tpl&&tplGet(S.settings.tpl.id),v=t&&t.settings&&t.settings.vocabulaire;return v&&typeof v[k]==='string'&&v[k]?v[k]:TV0[k]}
const NOUN=()=>tv('personne'),PLUR=()=>NOUN()+'s',CAPP=()=>{const p=PLUR();return p.charAt(0).toUpperCase()+p.slice(1)};
const tplFill=(s,name)=>String(s||'').replace(/\{nom\}/g,name||'');
/* ce que le modèle change, en clair (aperçu avant application) */
function tplSummary(t){
  const c=t.settings||{},names=c.catNames||CATDEF,cnt={};CATS.forEach(x=>cnt[x.id]=0);t.products.forEach(p=>cnt[p.cat]++);
  return{
    cats:CATS.map((x,i)=>({n:names[i],k:cnt[x.id]})),
    n:t.products.length,
    ex:t.products.slice(0,4).map(p=>p.name+' '+tplEur(p.price)),
    hours:tplHoursText(t),
    cap:c.capacite,staff:c.equipe_minimum,
    hidden:[...(c.modules_masques||[]).map(tplNavLabel),...(c.onglets_masques||[]).map(tplTabLabel)],
    web:c.reservation_en_ligne||null
  };
}
const tplEur=v=>(+v).toLocaleString('fr-FR',{minimumFractionDigits:(+v)%1?2:0,maximumFractionDigits:2})+' €';

/* ---- application d'un modèle ----
   mode « replace » : repart du modèle (produits, catégories, horaires, menus affichés, textes, fidélité…). Ventes, clients, comptes et planning ne sont pas touchés.
   mode « add »     : ajoute seulement les produits (et sous-catégories) qui manquent ; les réglages ne bougent pas. */
function tplApply(id,o){
  o=o||{};const t=tplGet(id);if(!t)return false;
  const mode=o.mode==='add'?'add':'replace',st=S.settings,c=t.settings||{},nm=String(o.name||'').trim().slice(0,80);
  const keep=(p,list)=>list.find(x=>x.cat===p.cat&&String(x.name).trim().toLowerCase()===p.name.toLowerCase());
  const prods=t.products.map(p=>{
    const old=keep(p,S.products||[]),q={id:old?old.id:uid(),name:p.name,cat:p.cat,price:tplEuros(p.price),tva:p.tva,active:true};
    if(old&&old.img)q.img=old.img;
    if(p.scat)q.scat=p.scat;
    if(p.art)q.art=p.art;
    if(p.jumper){q.jumper=true;q.dur=p.dur}else if(p.dur)q.dur=p.dur;
    if(p.event){q.event=true;q.guests=p.guests||10}
    return q;
  });
  if(mode==='replace')S.products=prods;
  else{const have=new Set(S.products.map(p=>p.cat+'|'+String(p.name).trim().toLowerCase()));prods.forEach(q=>{if(!have.has(q.cat+'|'+q.name.toLowerCase()))S.products.push(q)})}
  /* sous-catégories : en mode « add », on ajoute celles qui manquent */
  const sb=c.subs||{};st.subs=st.subs||{};
  if(mode==='replace')st.subs=JSON.parse(JSON.stringify(sb));
  else Object.keys(sb).forEach(k=>{const cur=st.subs[k]=st.subs[k]||[];sb[k].forEach(x=>{if(!cur.includes(x))cur.push(x)})});
  if(mode==='replace'){
    const d=defaultSettings();
    if(c.catNames)st.catNames=c.catNames.slice();else delete st.catNames;
    CATS.forEach((x,i)=>{x.name=(st.catNames&&String(st.catNames[i]||'').trim())||CATDEF[i]});
    st.cap=c.capacite||d.cap;st.minStaff=c.equipe_minimum||d.minStaff;
    st.fond=c.fond_de_caisse!==undefined?tplEuros(c.fond_de_caisse):d.fond;
    st.brand=(c.couleurs&&c.couleurs.principale)||d.brand;st.accent=(c.couleurs&&c.couleurs.action)||d.accent;
    const f=c.fidelite;
    if(f){st.ppe=f.points_par_euro||1;st.pal=(f.paliers||[]).map(p=>({id:'p'+p.points,pts:p.points,amt:tplEuros(p.remise),name:p.nom}))}else{st.ppe=d.ppe;st.pal=d.pal}
    st.welcome=tplFill(c.message_accueil,nm||st.name);st.ticketMsg=tplFill(c.pied_de_ticket,nm||st.name);
    const H=tplHoursOf(t);
    if(H){S.hours={week:H.week,exc:(S.hours&&S.hours.exc)||[]};syncEnvelope()}
    const r=c.reservation_en_ligne;
    if(r){const w=webCfg();if(r.places_par_creneau)w.cap=r.places_par_creneau;if(r.delai_minimum_minutes!==undefined)w.lead=r.delai_minimum_minutes;if(r.jours_a_l_avance)w.days=r.jours_a_l_avance;if(r.personnes_max)w.max=r.personnes_max;w.info=r.message||'';if(r.conditions!==undefined)w.cgv=r.conditions;w.prods=null;w.adds=null}
    st.off={};(c.modules_masques||[]).forEach(m=>{st.off[m]=true});
    st.offT={};(c.onglets_masques||[]).forEach(k=>{st.offT[k]=true});
    if(st.conf&&Array.isArray(st.conf.ech)){const off=new Set(c.echeances_desactivees||[]);st.conf.ech.forEach(e=>{e.on=!off.has(e.k)})}
    st.lists={};
    if(c.listes_controle_mensuel)st.lists.mpts=c.listes_controle_mensuel.slice();
    if(c.types_incident)st.lists.itypes=c.types_incident.slice();
    if(c.types_equipement)st.lists.meq=c.types_equipement.slice();
    if(c.types_secours)st.lists.isec=c.types_secours.slice();
    if(!Object.keys(st.lists).length)delete st.lists;
    [['mpts',MPTS],['itypes',ITYPES],['meq',MEQ],['isec',ISECOURS]].forEach(([k,a])=>{a.length=0;LISTDEF[k].forEach(x=>a.push(x))});
    st.texts=Object.assign({},c.textes||{});
    if(nm)st.name=nm;
    st.tpl={id:t.id,v:t.version,at:Date.now()};
  }
  try{tplArt()}catch(e){}
  if(o.clearDemo!==false){try{clearDemo()}catch(e){}}
  S.noDemo=true;
  if(typeof cart!=='undefined')cart=newCart();
  (o.quiet?saveBase:save)();
  try{applySettings();applyCustom();renderNav();chrome()}catch(e){}
  return true;
}

/* ---- espace client neuf (lien d'activation de la console) ---- */
const tplBootOn=()=>{const c=cloudCfg();return !!(c&&c.boot&&!accs().length)};
function tplBootstrap(b){
  const t=tplGet(b&&b.t)||tplGet('parc-trampoline');
  try{clearDemo()}catch(e){}
  S.staff=[];S.leaves=[];S.shifts={};S.checks={};S.stock={};S.events=[];S.clients=[];S.sales=[];S.closures=[];S.mails=[];
  S.plans=[buildPlan('p0','Semaine type','','',true)];
  tplApply(t.id,{mode:'replace',name:b&&b.n,quiet:true,clearDemo:false});
  S.noDemo=true;
}
function tplAfterAdmin(a){
  if(!tplBootOn())return;
  if(!S.staff.length){S.staff=[{id:'e1',name:String(a.name||'Responsable').trim(),role:'resp',color:PCOL[0]}];a.staffId='e1'}
  const c=cloudCfg();if(c){delete c.boot;cloudSet(c)}
  save();
}
function gateBoot(){
  const c=cloudCfg()||{},n=(c.boot&&c.boot.n)||S.settings.name;
  gateShell(`<h2>Bienvenue chez ${esc(n)}</h2><p class="muted">Votre espace Lago est prêt. Créez le compte administrateur : c’est vous qui validerez ensuite les comptes de votre équipe.</p>${gform('setup')}`);
}
/* un lien « nouvel espace » ouvert sur un appareil qui contient déjà un Lago ne doit rien écraser */
function tplLinkBusy(x){
  if(!(x&&(x.b||x.g)))return false;
  const c=cloudCfg();
  if(c&&c.u&&c.r&&c.r===x.r)return false;
  return accs().length>0||!!(c&&c.u&&c.r);
}
function tplBlockNote(){
  if(document.getElementById('zblock'))return;
  const d=document.createElement('div');d.id='zblock';d.className='zblock';d.setAttribute('role','alertdialog');d.setAttribute('aria-modal','true');
  d.innerHTML=`<div class="zbc"><h2>Lien ignoré</h2><p>Cet appareil contient déjà un Lago. Pour ne pas mélanger les données, le lien n’a pas été utilisé.</p><p>Ouvrez-le dans une fenêtre de navigation privée, ou sur un autre appareil.</p><button class="btn primary" type="button" data-act="zblock_ok">Compris</button></div>`;
  document.body.appendChild(d);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="zblock_ok"]');if(b){const d=document.getElementById('zblock');if(d)d.remove()}});

/* ---- suspension par le propriétaire ---- */
const SUSP={on:false,msg:''};
function suspDraw(){
  let d=document.getElementById('zsusp');
  if(!SUSP.on){if(d)d.remove();return}
  if(!d){d=document.createElement('div');d.id='zsusp';d.className='zblock zsusp';d.setAttribute('role','alertdialog');d.setAttribute('aria-modal','true');document.body.appendChild(d)}
  d.innerHTML=`<div class="zbc"><h2>Espace suspendu</h2><p>L’accès à ce Lago est suspendu pour le moment.</p>${SUSP.msg?`<p class="zbm">${esc(SUSP.msg)}</p>`:''}<p class="muted">Contactez votre prestataire pour le réactiver. Vos données sont conservées.</p><button class="btn" type="button" data-act="susp_retry">Réessayer</button></div>`;
}
async function suspCheck(){
  const c=cloudCfg();if(!c||!c.u||!/^https?:\/\//.test(c.u))return;
  try{
    const r=await fetch(c.u.replace(/\/+$/,'')+'/_susp.json',{cache:'no-store'});
    if(!r.ok)return;
    const j=await r.json(),on=!!(j&&typeof j==='object'&&j.on===true);
    SUSP.on=on;SUSP.msg=on&&typeof j.msg==='string'?j.msg.slice(0,300):'';suspDraw();
  }catch(e){}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="susp_retry"]');if(b){b.disabled=true;suspCheck().finally(()=>{b.disabled=false})}});
setTimeout(suspCheck,1500);setInterval(()=>{if(!document.hidden)suspCheck()},60000);
addEventListener('focus',()=>suspCheck());addEventListener('online',()=>suspCheck());

/* ---- Paramètres › Mon métier ---- */
const TPLUI={mode:'replace'};
function vSetMetier(m){
  if(!isAdmin()){m.innerHTML='<div class="card"><p class="muted">Réservé à l’administrateur.</p></div>';return}
  const cur=S.settings.tpl,ct=cur&&tplGet(cur.id);
  m.innerHTML=`<div class="card" style="margin-bottom:14px"><h3>Mon métier</h3>
    <p class="muted" style="margin:0 0 10px">Choisissez un modèle prêt à l’emploi : il règle d’un coup les produits, les catégories, les horaires, les menus affichés, la fidélité et les textes. Vous pourrez tout modifier ensuite.</p>
    <p style="margin:0">${ct?`Modèle appliqué : <b>${esc(ct.label)}</b> <span class="pill">version ${cur.v}</span>`:'Aucun modèle appliqué : réglages d’origine (parc de trampolines).'}</p></div>
   <div class="tpg">${TPLS.map(t=>{const s=tplSummary(t),on=cur&&cur.id===t.id;return `<button type="button" class="tpc${on?' on':''}" data-act="tpl_view" data-id="${t.id}"><b class="tpn">${esc(t.label)}</b><span class="tpr">${esc(t.resume)}</span><span class="tpk">${s.n} produits${on?' · modèle actuel':''}</span></button>`}).join('')}</div>`;
}
TABS.params.splice(1,0,['pmetier','Mon métier']);SUBS.pmetier=vSetMetier;
function tplModal(id){
  const t=tplGet(id);if(!t)return;
  const s=tplSummary(t),real=(S.sales||[]).some(x=>!x.demo);
  TPLUI.id=id;TPLUI.mode=real?'add':'replace';
  const lost=Math.max(0,(S.products||[]).filter(p=>!t.products.some(q=>q.cat===p.cat&&q.name.toLowerCase()===String(p.name).trim().toLowerCase())).length);
  showModal(`${mh(esc(t.label))}<p class="muted" style="margin:0 0 10px">${esc(t.resume)}</p>
   <div class="tps">
    <div><b>Catégories</b><span>${s.cats.map(c=>esc(c.n)+' ('+c.k+')').join(', ')}</span></div>
    <div><b>Produits</b><span>${s.n} produits, par exemple ${s.ex.map(esc).join(', ')}</span></div>
    ${s.hours?`<div><b>Horaires</b><span>${esc(s.hours)}</span></div>`:''}
    ${s.cap?`<div><b>Capacité</b><span>${s.cap} personnes en même temps, ${s.staff||1} personne${(s.staff||1)>1?'s':''} minimum en poste</span></div>`:''}
    ${s.hidden.length?`<div><b>Masqué</b><span>${s.hidden.map(esc).join(', ')}</span></div>`:''}
   </div>
   <div class="field" style="margin:0 0 12px"><label for="tpl_name">Nom de votre établissement</label><input id="tpl_name" maxlength="80" autocomplete="off" placeholder="Ex. ${esc(t.label)} Dupont" value="${esc(S.settings.name===defaultSettings().name?'':S.settings.name)}"><span class="muted" style="font-size:13px">Il apparaît sur les tickets, les mails et la page de réservation.</span></div>
   <div class="tpo" role="radiogroup" aria-label="Que faire des modèles ?">
    <label class="tpl-o"><input type="radio" name="tplm" value="replace" ${TPLUI.mode==='replace'?'checked':''}><span><b>Repartir du modèle</b>Remplace vos produits, catégories, horaires, menus affichés et textes par ceux du modèle${lost?` (${lost} produit${lost>1?'s':''} actuel${lost>1?'s':''} ne figure${lost>1?'nt':''} pas dans le modèle)`:''}. Vos ventes, clients, comptes et planning ne bougent pas.</span></label>
    <label class="tpl-o"><input type="radio" name="tplm" value="add" ${TPLUI.mode==='add'?'checked':''}><span><b>Ajouter les produits manquants</b>Ajoute les produits du modèle que vous n’avez pas encore. Vos réglages ne changent pas.</span></label>
   </div>
   <p class="muted" style="font-size:13px;margin:8px 0 12px">Une copie de sécurité est enregistrée avant le changement (Paramètres › Santé).</p>
   <div class="acts"><button class="btn" data-act="close">Annuler</button><button class="btn primary" data-act="tpl_go">Appliquer le modèle</button></div>`);
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-act="tpl_view"],[data-act="tpl_go"]');if(!b||!isAdmin())return;
  if(b.dataset.act==='tpl_view'){tplModal(b.dataset.id);return}
  const r=document.querySelector('#modal input[name="tplm"]:checked');
  const id=TPLUI.id,mode=r?r.value:TPLUI.mode,ni=document.getElementById('tpl_name'),name=ni?ni.value.trim():'';
  if(mode==='replace'&&!name&&S.settings.name===defaultSettings().name){toast('Indiquez le nom de votre établissement');if(ni)ni.focus();return}
  b.disabled=true;
  try{await bkSnap(false,'Avant le modèle « '+((tplGet(id)||{}).label||id)+' »')}catch(x){}
  if(tplApply(id,{mode,name:mode==='replace'?name:''})){closeModal();toast('Modèle appliqué');try{render()}catch(x){}}
  else b.disabled=false;
});


METHODS.pass='Carnet de séances';
function openPay(){
  const T=totals(cart);
  if(T.L.length&&T.total===0&&(T.pInfo||T.pcInfo)&&slotOk(T)){
    const sale=finalize(cart,[{m:'pass',amt:0}],Date.now(),false);sale.change=0;
    S.sales.push(cfSeal(sale));number();afterSale(sale,cart);save();cart=newCart();showReceipt(sale,true);
    if(view==='caisse'){drawCart();drawGrid()}return;
  }
  openPayBase();
}

/* ---------- événements ---------- */
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b)return;
  const a=b.dataset.act,d=b.dataset;
  if(a==='scrim'){if(e.target===b)closeModal();return}
  if(b.disabled)return;
  switch(a){
    case 'close':closeModal();break;
    case 'fcat':fcat=d.id;fsub='';drawChips();drawGrid();break;
    case 'fsub':fsub=fsub===d.v?'':d.v;drawChips();drawGrid();break;
    case 'add':tapProduct(d.id);break;
    case 'qty':{const l=cart.lines.find(l=>l.pid===d.id);if(l){l.qty+=+d.d;if(l.qty<=0)cart.lines=cart.lines.filter(x=>x!==l)}drawCart();drawGrid();break}
    case 'clear':cart.promo=null;cart.pass=null;cart.lines=[];cart.disc={t:'pct',v:0};cart.rewardPal=null;cart.event=null;drawCart();drawGrid();break;
    case 'disc':cart.disc={t:d.t,v:+d.v};drawCart();break;
    case 'cday':{const n=addDays(cart.slotDate,+d.d);if(n>=today()){cart.slotDate=n;drawCart()}break}
    case 'opencart':document.body.classList.add('cart-open');break;
    case 'closecart':document.body.classList.remove('cart-open');break;
    case 'pickclient':pickClient();break;
    case 'noclient':e.stopPropagation();cart.clientId=null;drawCart();break;
    case 'selclient':cart.clientId=d.id;closeModal();if(view==='caisse')drawCart();break;
    case 'pay':openPay();break;
    case 'addpay':{const rem=totals(cart).total-paid();if(rem>0){pay.list.push({m:d.m,amt:rem,given:null});renderPay()}break}
    case 'rmpay':pay.list.splice(+d.i,1);renderPay();break;
    case 'given':{const p=pay.list[+d.i];p.given=d.v===''?null:+d.v*100;renderPay();break}
    case 'confirm':confirmPay();break;
    case 'newclient':pickNew=!!d.pick;clientForm();break;
    case 'client':clientDetail(d.id);break;
    case 'sellclient':cart.clientId=d.id;closeModal();location.hash==='#caisse'?render():location.hash='caisse';break;
    case 'day':slotDay=d.d;({sjour:vStaffDay,apercu:vDay,resas:vResas,events:vEvents,bracelets:vBracelets})[tab[view]]($('#sub'));break;
    case 'slot':slotDetail(+d.m);break;
    case 'sellslot':cart.slotDate=slotDay;cart.slotM=+d.m;closeModal();location.hash==='#caisse'?render():location.hash='caisse';break;
    case 'newprod':prodForm('');break;
    case 'editprod':prodForm(d.id);break;
    case 'delprod':
      if(!b.dataset.sure){b.dataset.sure='1';b.textContent='Confirmer';break}
      S.products=S.products.filter(p=>p.id!==d.id);cart.lines=cart.lines.filter(l=>l.pid!==d.id);save();closeModal();vProducts($('#sub'));toast('Produit supprimé');break;
    case 'ticket':{const s=S.sales.find(x=>x.id===d.id);if(s)showReceipt(s,false);break}
    case 'close-day':{
      const inp=$('#counted');const exp=+inp.dataset.exp;const cnt=inp.value.trim()?parseEur(inp.value):exp;
      cfDayClose(exp,cnt);vReports($('#sub'));toast('Journée clôturée');break}
    case 'reset':
      if(cfLocked()){toast('Réinitialisation impossible : des tickets de caisse sont archivés. Exportez l’archive fiscale (Paramètres › Conformité).');break}
      if(!b.dataset.sure){b.dataset.sure='1';b.textContent='Confirmer la réinitialisation';break}
      msClear();init();cart=newCart();chrome();render();toast('Données de démonstration rechargées');break;
  }
});
document.addEventListener('input',e=>{
  const t=e.target;
  if(t.id==='q'){q=t.value;drawGrid()}
  else if(t.id==='cq')drawClients(t.value);
  else if(t.id==='cpick')drawPick(t.value);
  else if(t.dataset.pay!==undefined){pay.list[+t.dataset.pay].amt=parseEur(t.value);updatePay()}
  else if(t.id==='counted'){const diff=(t.value.trim()?parseEur(t.value):+t.dataset.exp)-+t.dataset.exp;const el=$('#ecart');
    el.textContent=t.value.trim()?(diff===0?'Aucun écart.':'Écart de '+(diff>0?'+':'')+eur(diff)):'Saisissez le montant compté pour voir l’écart.';
    el.style.color=t.value.trim()?(diff===0?'var(--ok)':'var(--bad)'):''}
});
document.addEventListener('change',e=>{
  if(e.target.id==='slotsel'){cart.slotH=e.target.value===''?null:+e.target.value;drawCart()}
});
document.addEventListener('submit',e=>{
  e.preventDefault();
  if(e.target.id==='cform'){
    const c={id:uid(),name:$('#cn').value.trim(),phone:$('#cp').value.trim(),email:$('#ce').value.trim(),optin:$('#co').checked,pts:0,note:'',kid:'',rewards:[]};
    if(!c.name)return;S.clients.push(c);save();
    if(pickNew){cart.clientId=c.id;closeModal();if(view==='caisse')drawCart()}else{closeModal();if(view==='clients')vClients($('#sub'))}
    toast('Client ajouté');
  }else if(e.target.id==='pform'&&!e.target.dataset.plan){
    const id=e.target.dataset.id,o={name:$('#pn').value.trim(),cat:$('#pc').value,price:parseEur($('#pp').value),tva:+$('#pt').value,jumper:$('#pj').checked,active:$('#pa').checked};
    if(!o.name)return;
    if(pimg!==undefined)o.img=pimg||undefined;
    o.scat=$('#psub').value||undefined;
    if(id)Object.assign(prod(id),o);else S.products.push({id:uid(),...o});
    save();closeModal();vProducts($('#sub'));toast('Produit enregistré');
  }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
window.addEventListener('hashchange',route);

/* ---- v73 : sous-menus de la caisse (encaisser, ventes en attente, ventes validées, avoirs, clôture) ---- */
const CX_TABS=[['cx_vente','Encaisser'],['cx_att','Ventes en attente'],['cx_val','Ventes validées'],['cx_av','Avoirs et remboursements'],['cx_clo','Clôture de caisse']];
TABS.caisse=CX_TABS;tab.caisse='cx_vente';
let cxDay=today(),cxQ='',cxPm='all',cxLast='',cxGoto=false;
const cxHeld=()=>S.held||(S.held=[]);
const cxPayTxt=s=>[...new Set((s.pay||[]).map(p=>METHODS[p.m]||p.m))].join(' + ');
const cxItems=s=>(s.lines||[]).reduce((a,l)=>a+Math.abs(l.qty||0),0);
const cxLinesTxt=c=>{const L=c.lines||[];return L.slice(0,3).map(l=>{const n=l.name||((prod(l.pid)||{}).name)||'Article';return (Math.abs(l.qty)>1?Math.abs(l.qty)+' × ':'')+esc(n)}).join(', ')+(L.length>3?' …':'')};
const cxDayOf=s=>dkey(new Date(s.ts));
function cxTabsHtml(){
  const L=tabsFor('caisse'),n=cxHeld().length;
  return `<div class="tabs cxtabs" role="tablist" aria-label="Caisse">${L.map(([id,l])=>`<button role="tab" aria-selected="${tab.caisse===id}" class="${tab.caisse===id?'on':''}" data-act="tab" data-id="${id}">${l}${id==='cx_att'&&n?`<b class="cxn">${n}</b>`:''}</button>`).join('')}</div>`;
}
function vCaisseHub(m){
  const L=tabsFor('caisse');if(L.length&&!L.some(x=>x[0]===tab.caisse))tab.caisse=L[0][0];
  const sell=tab.caisse==='cx_vente',cb=$('#cartbar');
  if(cb)cb.hidden=!sell;if(!sell)document.body.classList.remove('cart-open');
  if(sell){vCaisse(m);const h=m.querySelector('header.top');if(h)h.insertAdjacentHTML('afterend',cxTabsHtml());cxTabScroll(m);return}
  m.innerHTML=head('Caisse',ctrlPill())+cxTabsHtml()+'<div id="sub"></div>';
  cxSub();cxTabScroll(m);
}
function cxTabScroll(m){try{const t=m.querySelector('.cxtabs'),o=t&&t.querySelector('.on');if(o&&t.scrollWidth>t.clientWidth)t.scrollLeft=Math.max(0,o.offsetLeft-t.offsetLeft-16)}catch(e){}}
VIEWS.caisse=vCaisseHub;
function cxSub(){const el=$('#sub'),f={cx_att:cxAtt,cx_val:cxVal,cx_av:cxAv,cx_clo:cxClo}[tab.caisse];if(el&&view==='caisse'&&f)f(el)}
function cxRefresh(){if(view!=='caisse')return;VIEWS.caisse($('#main'));renderNav()}
/* les écrans de vente ne se redessinent que s'ils sont affichés */
drawGrid=(o=>function(){if(!$('#grid'))return;return o.apply(this,arguments)})(drawGrid);
drawCart=(o=>function(){if(!$('#cart'))return;return o.apply(this,arguments)})(drawCart);
/* en arrivant sur la caisse depuis un autre écran, on ouvre l'encaissement (sauf lien direct vers un sous-menu) */
document.addEventListener('click',e=>{if(e.target.closest('[data-act="goto"][data-v="caisse"]'))cxGoto=true},true);
renderBase=(o=>function(){const was=cxLast;cxLast=view;if(view==='caisse'&&was!=='caisse'&&!cxGoto)tab.caisse='cx_vente';cxGoto=false;return o.apply(this,arguments)})(renderBase);
/* nombre de ventes en attente dans le menu */
renderNav=(o=>function(){o.apply(this,arguments);try{const n=cxHeld().length,b=document.querySelector('#nav .subnav [data-v="caisse"][data-t="cx_att"]');if(b&&n)b.insertAdjacentHTML('beforeend',`<b class="cxn">${n}</b>`)}catch(e){}})(renderNav);
/* un avoir établi depuis un sous-menu met la liste à jour */
cfCancel=(o=>function(){const r=o.apply(this,arguments);if(r&&view==='caisse'&&tab.caisse!=='cx_vente')setTimeout(()=>{cxSub();renderNav()},0);return r})(cfCancel);

/* Ventes en attente */
function cxAtt(m){
  const h=cxHeld().slice().sort((a,b)=>b.ts-a.ts);let T0=null;try{if(cart.lines.length)T0=totals(cart)}catch(e){}
  const cur=T0?`<div class="card cxcur"><div class="row cxrow"><span class="cxic on">${ic('caisse')}</span><span class="grow"><b>Ticket en cours · ${T0.items} article${T0.items>1?'s':''} · ${eur(T0.total)}</b><span class="muted">${cxLinesTxt(cart)}</span></span><span class="cxacts"><button class="btn" data-act="cx_park">${ic('clock')}Mettre en attente</button><button class="btn primary" data-act="cx_go">Continuer</button></span></div></div>`:'';
  m.innerHTML=cur+`<div class="card"><h3>Ventes en attente${h.length?` <span class="pill warn">${h.length}</span>`:''}</h3>
   <p class="muted cxhelp">Tickets mis de côté pendant l’encaissement (client qui revient, addition à finir). Ils ne sont pas encore encaissés : reprenez-les pour les payer.</p>
   ${h.length?h.map(x=>{let T;try{T=totals(x.cart)}catch(e){T={items:(x.cart.lines||[]).length,total:0}}const old=cxDayOf(x)!==today();
     return `<div class="row cxrow"><span class="cxic">${ic('clock')}</span><span class="grow"><b>${T.items} article${T.items>1?'s':''} · ${eur(T.total)}${x.cart.clientId?' · '+esc(clientName(x.cart.clientId)):''}</b><span class="muted">Mis en attente ${old?'le '+new Date(x.ts).toLocaleDateString('fr-FR')+' ':''}à ${hm(x.ts)} · ${cxLinesTxt(x.cart)}</span></span><span class="cxacts"><button class="btn primary" data-act="cx_resume" data-id="${x.id}">Reprendre</button><button class="ix" data-act="cx_hdel" data-id="${x.id}" aria-label="Supprimer ce ticket en attente">${ic('trash')}</button></span></div>`}).join(''):`<div class="empty">${ic('check')}<p>Aucune vente en attente.</p></div>`}</div>`;
}

/* Ventes validées */
function cxVal(m){
  const day=cxDay,all=S.sales.filter(s=>s.ty!=='av'&&cxDayOf(s)===day).sort((a,b)=>b.ts-a.ts);
  const ok=all.filter(s=>!s.cx),ca=ok.reduce((a,s)=>a+s.total,0),pms=[...new Set(all.flatMap(s=>(s.pay||[]).map(p=>p.m)))];
  if(cxPm!=='all'&&!pms.includes(cxPm))cxPm='all';
  m.innerHTML=`<div class="cxday"><button class="ix" data-act="cx_day" data-d="-1" aria-label="Jour précédent">${ic('left')}</button><b>${day===today()?'Aujourd’hui':dlong(day)}</b><button class="ix" data-act="cx_day" data-d="1" aria-label="Jour suivant" ${day>=today()?'disabled':''}>${ic('right')}</button>${day!==today()?'<button class="btn" data-act="cx_today">Aujourd’hui</button>':''}<input type="date" id="cxdate" value="${day}" max="${today()}" aria-label="Choisir une date"></div>
  <div class="kpis cxk"><div class="kpi"><div class="l">Ventes validées</div><div class="v num">${ok.length}</div></div><div class="kpi"><div class="l">Chiffre d’affaires</div><div class="v num">${eur(ca)}</div></div><div class="kpi"><div class="l">Panier moyen</div><div class="v num">${eur(ok.length?Math.round(ca/ok.length):0)}</div></div><div class="kpi"><div class="l">Annulées par avoir</div><div class="v num">${all.length-ok.length}</div></div></div>
  <div class="card"><div class="cxfilters"><div class="search cxsearch">${ic('search')}<input id="cxq" type="search" placeholder="N° de ticket, client ou article" autocomplete="off" value="${esc(cxQ)}"></div>
   ${pms.length>1?`<div class="chips cxchips"><button class="chip ${cxPm==='all'?'on':''}" data-act="cx_pm" data-id="all">Tous</button>${pms.map(k=>`<button class="chip ${cxPm===k?'on':''}" data-act="cx_pm" data-id="${esc(k)}">${esc(METHODS[k]||k)}</button>`).join('')}</div>`:''}</div>
   <div id="cxlist"></div></div>`;
  cxValList(all);
}
function cxValList(all){
  const el=$('#cxlist');if(!el)return;all=all||S.sales.filter(s=>s.ty!=='av'&&cxDayOf(s)===cxDay).sort((a,b)=>b.ts-a.ts);
  const nq=norm(cxQ.trim()),L=all.filter(s=>(cxPm==='all'||(s.pay||[]).some(p=>p.m===cxPm))&&(!nq||norm(String(s.no||'')+' '+clientName(s.clientId)+' '+(s.lines||[]).map(l=>l.name).join(' ')).includes(nq)));
  const adm=isAdmin();
  el.innerHTML=L.length?L.map(s=>`<div class="row cxrow cxsale${s.cx?' cxoff':''}"><button class="rowbtn cxopen" data-act="ticket" data-id="${s.id}"><span class="cxt num">${hm(s.ts)}</span><span class="grow"><b>${esc(s.no||'Ticket')}${s.clientId?' · '+esc(clientName(s.clientId)):''}</b><span class="muted">${cxItems(s)} article${cxItems(s)>1?'s':''} · ${esc(cxPayTxt(s))}</span></span>${s.cx?`<span class="pill bad">Annulée · ${esc(s.cx.no)}</span>`:''}<b class="num cxamt">${eur(s.total)}</b></button>${adm&&cfSealed(s)&&!s.cx?`<button class="btn cxrf" data-act="cf_cancel" data-id="${s.id}" title="Établir un avoir pour cette vente">Rembourser</button>`:''}</div>`).join('')
    :`<div class="empty">${all.length?'Aucune vente ne correspond à cette recherche.':'Aucune vente validée ce jour-là.'}</div>`;
}

/* Avoirs et remboursements */
function cxAv(m){
  const av=S.sales.filter(s=>s.ty==='av').sort((a,b)=>b.ts-a.ts),mon=today().slice(0,7),am=av.filter(s=>cxDayOf(s).slice(0,7)===mon);
  m.innerHTML=`<div class="kpis cxk"><div class="kpi"><div class="l">Avoirs ce mois-ci</div><div class="v num">${am.length}</div></div><div class="kpi"><div class="l">Remboursé ce mois-ci</div><div class="v num">${eur(am.reduce((a,s)=>a-s.total,0))}</div></div><div class="kpi"><div class="l">Avoirs au total</div><div class="v num">${av.length}</div></div></div>
  <div class="cols"><div class="card"><h3>Rembourser une vente</h3><p class="muted cxhelp">Saisissez le numéro inscrit sur le ticket du client, ou retrouvez la vente dans « Ventes validées ».${isAdmin()?'':' Le remboursement est réservé à l’administrateur.'}</p>
    <form id="cxrf" class="cxfind"><input id="cxrn" placeholder="N° du ticket, ex. C1-0042" autocomplete="off" autocapitalize="characters"><button class="btn primary" type="submit">Rechercher</button></form><p class="muted cxhelp" id="cxrmsg" role="status" style="margin-top:8px"></p></div>
   <div class="card"><h3>Comment fonctionne un avoir</h3><ul class="cxul"><li>La vente d’origine est conservée et marquée « annulée » : une vente encaissée ne se supprime jamais.</li><li>Un avoir numéroté et daté est établi pour le même montant, avec le motif.</li><li>Cartes cadeaux, carnets de séances, points de fidélité et stock sont remis à jour automatiquement.</li><li>Un acompte payé en ligne se rembourse en plus depuis votre compte Stripe.</li></ul></div></div>
  <div class="card"><h3>Historique des avoirs</h3>${av.length?av.slice(0,200).map(s=>`<button class="row rowbtn cxrow" data-act="ticket" data-id="${s.id}"><span class="cxic bad">${ic('ticket')}</span><span class="grow"><b>Avoir ${esc(s.no||'')}${s.rf?' · sur '+esc(s.rf):''}</b><span class="muted">${new Date(s.ts).toLocaleDateString('fr-FR')} à ${hm(s.ts)}${s.mt?' · '+esc(s.mt):''}</span></span><b class="num cxamt">${eur(s.total)}</b></button>`).join(''):'<div class="empty">Aucun avoir pour le moment.</div>'}</div>`;
}

/* Clôture de caisse */
function cxClo(m){
  const c=cashInfo(),td=today(),clo=(S.closures||[]).filter(x=>dkey(new Date(x.ts))===td).pop(),ds=c.ds;
  const tk=ds.filter(s=>s.ty!=='av'&&!s.cx).length,na=ds.filter(s=>s.ty==='av').length,net=c.mv.reduce((a,x)=>a+(x.t==='dep'?x.amt:-x.amt),0);
  const pm={};ds.forEach(s=>(s.pay||[]).forEach(p=>pm[p.m]=(pm[p.m]||0)+p.amt));
  const vat={};ds.forEach(s=>Object.entries(s.vat||{}).forEach(([r,v])=>{(vat[r]=vat[r]||{ttc:0,tva:0});vat[r].ttc+=v.ttc;vat[r].tva+=v.tva}));
  const gCash=!opHidden('gestion')&&tabsFor('gestion').some(x=>x[0]==='caisse');
  const zs=(typeof cfLive==='function'&&cfLive())?(S.zs||[]).filter(z=>z.ty==='J').slice().sort((a,b)=>b.sq-a.sq).slice(0,6):[];
  m.innerHTML=`<div class="kpis cxk"><div class="kpi"><div class="l">Encaissé aujourd’hui</div><div class="v num">${eur(c.enc)}</div></div><div class="kpi"><div class="l">Ventes</div><div class="v num">${tk}</div></div><div class="kpi"><div class="l">Avoirs</div><div class="v num">${na}</div></div><div class="kpi"><div class="l">Espèces attendues</div><div class="v num">${eur(c.exp)}</div></div></div>
  <div class="cols"><div class="card"><h3>Clôturer la journée</h3>
    <div class="sum" style="margin-bottom:12px"><div class="r"><span>Fond de caisse</span><span class="num">${eur(S.settings.fond)}</span></div><div class="r"><span>Espèces encaissées</span><span class="num">${eur(c.cash)}</span></div>${c.mv.length?`<div class="r"><span>Retraits et dépôts</span><span class="num">${net>0?'+':''}${eur(net)}</span></div>`:''}<div class="r k"><span>Espèces attendues dans le tiroir</span><span class="num">${eur(c.exp)}</span></div></div>
    ${clo?`<div class="success">${ic('check')}<span>Journée clôturée à ${hm(clo.ts)}, écart ${clo.diff>0?'+':''}${eur(clo.diff)}</span></div>`:
    `<div class="field"><label for="counted">Espèces comptées (€)</label><input id="counted" inputmode="decimal" placeholder="${inEur(c.exp)}" data-exp="${c.exp}" autocomplete="off"></div>
    <p class="muted" id="ecart" style="margin-bottom:12px">Saisissez le montant compté pour voir l’écart.</p><button class="btn primary" data-act="cx_close" style="width:100%">Clôturer la journée</button>`}
    ${gCash?`<button class="btn" data-act="goto" data-v="gestion" data-t="caisse" style="width:100%;margin-top:10px">${ic('cash')}Compter le tiroir billet par billet, retraits et dépôts</button>`:''}</div>
   <div class="card"><h3>Par moyen de paiement</h3>${Object.keys(pm).length?Object.entries(pm).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row"><span class="grow">${esc(METHODS[k]||k)}</span><b class="num">${eur(v)}</b></div>`).join(''):'<p class="muted">Aucun encaissement aujourd’hui.</p>'}
    <h3 style="margin-top:18px">TVA</h3><div class="vrow h"><span>Taux</span><span>TTC</span><span>HT</span><span>TVA</span></div>${Object.entries(vat).map(([r,v])=>`<div class="vrow num"><span>${String(r).replace('.',',')} %</span><span>${eur(v.ttc)}</span><span>${eur(v.ttc-v.tva)}</span><span>${eur(v.tva)}</span></div>`).join('')||'<p class="muted">Aucune vente.</p>'}</div></div>
  ${zs.length?`<div class="card"><h3>Dernières clôtures</h3>${zs.map(z=>`<button class="row rowbtn cxrow" data-act="cf_z" data-id="${esc(z.id)}"><span class="cxic">${ic('shield')}</span><span class="grow"><b>${dfr(z.per)}${z.auto?' · automatique':''}</b><span class="muted">${z.n} ticket${z.n>1?'s':''}${z.na?' · '+z.na+' avoir'+(z.na>1?'s':''):''}</span></span><b class="num">${eur(z.ttc)}</b></button>`).join('')}<p class="muted cxhelp" style="margin:10px 0 0">Chaque clôture est scellée et ne peut plus être modifiée.</p></div>`:''}`;
}

document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act]');if(!b||b.disabled||view!=='caisse')return;const a=b.dataset.act,d=b.dataset;
  if(a==='cx_resume'){const H=cxHeld(),i=H.findIndex(x=>x.id===d.id);if(i<0)return;if(cart.lines.length)H.push({id:uid(),ts:Date.now(),cart:JSON.parse(JSON.stringify(cart))});cart=H.splice(i,1)[0].cart;save();tab.caisse='cx_vente';cxRefresh();toast('Vente reprise')}
  else if(a==='cx_hdel'){askYes('Supprimer ce ticket en attente ? Il n’a pas été encaissé.',()=>{S.held=cxHeld().filter(x=>x.id!==d.id);save();cxSub();renderNav();toast('Ticket supprimé')},'Supprimer')}
  else if(a==='cx_park'){if(!cart.lines.length)return;cxHeld().push({id:uid(),ts:Date.now(),cart:JSON.parse(JSON.stringify(cart))});cart=newCart();save();cxSub();renderNav();toast('Ticket mis en attente')}
  else if(a==='cx_go'){tab.caisse='cx_vente';cxRefresh()}
  else if(a==='cx_day'){const n=addDays(cxDay,+d.d);if(n<=today()){cxDay=n;cxSub()}}
  else if(a==='cx_today'){cxDay=today();cxSub()}
  else if(a==='cx_pm'){cxPm=d.id;b.parentNode.querySelectorAll('.chip').forEach(x=>x.classList.toggle('on',x===b));cxValList()}
  else if(a==='cx_close'){const inp=$('#counted');if(!inp)return;const exp=+inp.dataset.exp,cnt=inp.value.trim()?parseEur(inp.value):exp;
    askYes('Clôturer la journée avec '+eur(cnt)+' en espèces'+(cnt===exp?'':' (écart '+(cnt-exp>0?'+':'')+eur(cnt-exp)+')')+' ? La clôture ne peut plus être modifiée.',()=>{cfDayClose(exp,cnt);cxSub();toast('Journée clôturée')},'Clôturer')}
});
document.addEventListener('input',e=>{if(e.target.id==='cxq'){cxQ=e.target.value;cxValList()}});
document.addEventListener('change',e=>{if(e.target.id==='cxdate'&&e.target.value){cxDay=e.target.value>today()?today():e.target.value;cxSub()}});
document.addEventListener('submit',e=>{
  if(e.target.id!=='cxrf')return;e.preventDefault();
  const v=norm($('#cxrn').value.trim()).replace(/\s+/g,''),msg=$('#cxrmsg');if(!v){msg.textContent='Saisissez un numéro de ticket.';return}
  const s=S.sales.find(x=>x.ty!=='av'&&norm(String(x.no||'')).replace(/\s+/g,'')===v);
  if(!s){msg.textContent='Aucune vente avec ce numéro.';return}
  msg.textContent=s.cx?'Cette vente a déjà été remboursée par l’avoir '+s.cx.no+'.':!cfSealed(s)?'Vente de démonstration : elle ne peut pas être remboursée.':isAdmin()?'Vente trouvée : touchez « Annuler ce ticket » pour établir l’avoir.':'Vente trouvée. Le remboursement est réservé à l’administrateur.';
  showReceipt(s,false);
});

/* ---------- v74 : suivi des appareils (version + dernière synchro) et « Recharger tout » ---------- */
/* Chaque appareil connecté à l'équipe écrit, toutes les 30 minutes au plus, sa version et l'heure de son dernier passage
   dans S.devs[identifiant du compte]. Le responsable voit dans Paramètres › Comptes qui est à jour, qui est sur une
   ancienne version et qui n'a donné aucun signe de vie (appli ancienne qui ne se synchronise plus, ou jamais ouverte). */
function devBeat(){
  try{
    if(!ME||!cloudOn()||!CL.ready||CL.state!=='ok')return;
    const D=isO(S.devs)&&!Array.isArray(S.devs)?S.devs:(S.devs={}),c=D[ME.id],now=Date.now();
    /* un collègue tourne déjà sur une version plus récente : on la cherche tout de suite */
    const nv=Object.values(D).reduce((m,x)=>Math.max(m,x&&x.v?auNum(x.v)||0:0),0);
    if(nv>auNum(LAGO_V)&&!AU.busy&&now-AU.last>60000)auCheck();
    if(c&&c.v===LAGO_V&&now-c.ts<30*60000)return;
    D[ME.id]={v:LAGO_V,ts:now};save();
  }catch(e){}
}
setInterval(devBeat,20000);setTimeout(devBeat,4000);
function devAge(ts){
  const d=Math.max(0,Date.now()-ts);
  if(d<90000)return 'à l’instant';
  if(d<3600000)return 'il y a '+Math.round(d/60000)+' min';
  if(d<86400000)return 'il y a '+Math.round(d/3600000)+' h';
  const j=Math.round(d/86400000);return 'il y a '+j+' jour'+(j>1?'s':'');
}
function devState(id){
  const d=(S.devs||{})[id];
  if(!d||typeof d.ts!=='number'||!d.v)return{c:'warn',t:'Aucun signal : appli ancienne, ou pas ouverte depuis un moment'};
  const old=auNum(d.v)<auNum(LAGO_V);
  return{c:old?'warn':Date.now()-d.ts>7*86400000?'':'ok',t:String(d.v).slice(0,12)+(old?' · ancienne version':'')+' · vu '+devAge(d.ts)};
}
function devRows(m){
  if(!isAdmin()||!m)return;
  m.querySelectorAll('[data-acprof]').forEach(x=>{
    const id=x.dataset.acprof,r=x.closest('.row'),g=r&&r.querySelector('.grow');
    if(!g||g.querySelector('.dv'))return;
    const s=devState(id);
    g.insertAdjacentHTML('beforeend',`<span class="muted dv ${s.c}">${esc(s.t)}</span>`);
  });
}
/* « Mon compte » : état de la synchronisation + réparation d'une appli bloquée sur une ancienne version */
function appSyncRow(m){
  if(!m||m.querySelector('.auv2'))return;
  const on=cloudOn(),ok=CL.state==='ok';
  const t=on?(ok?'● Équipe connectée'+(CL.last?' · dernière synchro à '+hm(CL.last):''):'○ Hors ligne : vos changements partiront au retour du réseau'):'○ Cet appareil n’est pas relié à l’équipe : ses données restent sur ce téléphone';
  const a=m.querySelector('.auv');
  const h=`<div class="auv auv2"><div><b>Synchronisation</b><span class="muted" id="auvy">${esc(t)}</span><span class="muted" style="display:block;font-size:12.5px">Si l’appli reste bloquée sur une ancienne version : « Recharger tout » vide la mémoire de l’appli et la relance. Vos données sont conservées.</span></div><button type="button" class="btn" data-act="au_force">Recharger tout</button></div>`;
  if(a)a.insertAdjacentHTML('afterend',h);else m.insertAdjacentHTML('beforeend',h);
}
async function appForce(btn){
  if(btn){btn.disabled=true;btn.textContent='Rechargement…'}
  const tm=(p,ms)=>Promise.race([p,new Promise(r=>setTimeout(r,ms))]);
  try{save();cloudStash()}catch(_){}
  try{if(cloudOn()&&CL.ready)await tm(cloudSync(),3000)}catch(_){}
  try{if(navigator.serviceWorker){const regs=await tm(navigator.serviceWorker.getRegistrations(),2000);await tm(Promise.all((regs||[]).map(r=>r.unregister())),2000)}}catch(_){}
  try{if(window.caches){const ks=await tm(caches.keys(),2000);await tm(Promise.all((ks||[]).map(k=>caches.delete(k))),3000)}}catch(_){}
  location.replace(location.pathname+'?r='+Date.now()+(/^#cloud=/i.test(location.hash)?'':location.hash||''));
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="au_force"]');if(b)appForce(b)});
if(/[?&]r=\d+/.test(location.search)){try{history.replaceState(null,'',location.pathname+location.hash)}catch(_){}}

/* ---- v74 : état de la synchronisation, partout et en permanence ---- */
/* Pastille dans la barre du haut (toujours visible), bandeau dès qu'un problème dure, fiche de détail et réparation en un geste. */
function syState(){
  if(!cloudOn())return{k:'local'};
  if(CL.offAt&&CL.state!=='ok')return{k:'off',long:Date.now()-CL.offAt>12000,p:CL.sv!==CL.okSv};   // « synchronisation… » pendant les nouveaux essais ne cache pas la coupure
  if(!CL.ready||CL.state==='sync')return{k:'sync'};
  if(CL.state==='off')return{k:'off',long:false,p:CL.sv!==CL.okSv};
  if(CL.ev&&!document.hidden&&Date.now()-CL.ev>150000)return{k:'late',p:CL.sv!==CL.okSv};
  return{k:'ok',p:CL.sv!==CL.okSv};
}
const syTitle=s=>({local:'Appareil non relié à l’équipe',sync:'Synchronisation en cours…',off:'Hors ligne'+(s.p?' · modifications en attente d’envoi':''),late:'Pas de nouvelles de la base depuis un moment',ok:s.p?'Envoi des modifications…':'Synchronisé'}[s.k]);
const syAgo=ts=>{if(!ts)return 'jamais';const s=Math.max(0,Math.round((Date.now()-ts)/1000));return s<5?'à l’instant':s<60?'il y a '+s+' s':s<3600?'il y a '+Math.round(s/60)+' min':'à '+hm(ts)};
function syErrTxt(e){
  const t=String(e||'');
  if(/http 40[13]/.test(t))return 'La base en ligne refuse l’accès : les règles de sécurité de la base ne laissent plus passer cet appareil. Prévenez votre responsable (Paramètres › Studio).';
  if(/http 404|http 405/.test(t))return 'Adresse de la base introuvable : le lien d’équipe est peut-être périmé.';
  if(/http 5\d\d/.test(t))return 'Le serveur de la base répond par une erreur : nouvel essai automatique.';
  if(/abort|délai|Failed to fetch|NetworkError|Load failed/i.test(t))return 'Connexion lente ou bloquée : nouvel essai automatique.';
  return t?'Erreur : '+t.slice(0,80):'';
}
function syPending(){try{if(!cloudOn()||!CL.ready)return 0;const p={};diffT(CL.B,projS(),'',p);return Object.keys(p).length}catch(e){return 0}}
function syDraw(){
  const s=syState(),k=s.k;
  document.querySelectorAll('.gb-sy').forEach(b=>{b.dataset.s=k==='late'?'off':k;b.dataset.p=s.p&&k!=='local'?'1':'';b.title=syTitle(s)});
  let lateShow=false;
  if(k==='late'){   // d'abord une réparation silencieuse (on rouvre le flux) ; le bandeau n'apparaît que si le silence persiste
    const n=syDraw.nudge||0;
    if(Date.now()-n>60000){syDraw.nudge=Date.now();try{cloudWake(true)}catch(e){}}
    else if(Date.now()-n>20000)lateShow=true;
  }
  const bar=document.getElementById('sybar');if(!bar)return;
  let hide=false;try{hide=sessionStorage.getItem('lago-sy-x')==='1'}catch(e){}
  let m=null;
  if(k==='local'){
    if(!isAdmin())m=['local','<span><b>Cet appareil n’est pas relié à l’équipe.</b> Ce que vous saisissez ici (messages, congés, contrôles) n’est vu que sur ce téléphone, et vous ne voyez pas ce que les autres saisissent.</span><button class="btn primary" data-act="pl_join">Rejoindre l’équipe</button>'];
    else if(accs().length>1&&!hide)m=['local','<span><b>Cet appareil n’est pas relié à l’équipe.</b> Les autres téléphones ne voient pas vos modifications.</span><button class="btn" data-act="sy_open">Détails</button><button class="btn" data-act="sy_hide">Masquer</button>'];
  }else if(k==='off'&&s.long){
    const auth=/http 40[13]/.test(String(CL.err||''));
    m=['off',auth?'<span><b>Synchronisation refusée.</b> '+esc(syErrTxt(CL.err))+(s.p?' Vos modifications restent sur ce téléphone en attendant.':'')+'</span><button class="btn" data-act="sy_now">Réessayer</button><button class="btn" data-act="sy_open">Détails</button>'
      :'<span><b>Hors ligne.</b> '+(s.p?'Vos dernières modifications partiront dès le retour de la connexion.':'Vous ne voyez plus les changements des autres pour le moment.')+'</span><button class="btn" data-act="sy_now">Réessayer</button>'];
  }
  else if(k==='late'&&lateShow)m=['off','<span><b>Pas de nouvelles de la base</b> depuis '+syAgo(CL.ev).replace('il y a ','')+'. Vérification en cours…</span><button class="btn" data-act="sy_now">Actualiser</button>'];
  const key=m?m.join('|'):'';
  if(bar.dataset.key===key)return;
  bar.dataset.key=key;
  if(!m){bar.hidden=true;bar.innerHTML=''}else{bar.hidden=false;bar.dataset.k=m[0];bar.innerHTML=m[1]}
  requestAnimationFrame(gbH);
}
setInterval(()=>{try{syDraw()}catch(e){}},1500);
function syOpen(again){
  const s=syState(),on=cloudOn(),adm=isAdmin();
  const lab={local:'Non relié à l’équipe',sync:'Synchronisation en cours…',off:'Hors ligne',late:'Sans nouvelles de la base',ok:'Synchronisé'}[s.k];
  const devs=adm?accs().filter(a=>a.status!=='pending').map(a=>{const d=devState(a.id);return `<div class="row"><span class="grow"><b>${esc(a.name)}</b><span class="muted dv ${d.c}">${esc(d.t)}</span></span></div>`}).join(''):'';
  if(!again||document.getElementById('sypanel')){
    showModal(`<div id="sypanel">${mh('Synchronisation')}
     <div class="sum"><div class="r"><span>État</span><b>${esc(lab)}</b></div>
      <div class="r"><span>Version de Lago</span><b>${esc(LAGO_V)}</b></div>
      ${on?`<div class="r"><span>${s.k==='off'?'Dernière synchronisation réussie':'Dernier contact avec la base'}</span><b>${esc(syAgo(s.k==='off'?CL.last:CL.ev))}</b></div><div class="r"><span>Modifications à envoyer</span><b id="sypend">…</b></div><div class="r"><span>Taille des données de l’équipe</span><b id="sysize">…</b></div>`:''}
      ${on&&CL.err&&CL.state==='off'?`<div class="r"><span>Problème</span><b style="text-align:right;max-width:60%">${esc(syErrTxt(CL.err))}</b></div>`:''}</div>
     <p class="muted" style="font-size:13px;margin:10px 0">${on?'Chaque modification part vers la base de l’équipe dans la seconde. Sans réseau, elle est gardée sur ce téléphone puis envoyée au retour de la connexion.':'Les données de cet appareil restent ici. Pour partager le planning, les messages, les congés et la caisse avec l’équipe, collez le lien d’équipe de votre responsable.'}</p>
     <div class="acts">${on?'<button class="btn primary" data-act="sy_now">Synchroniser maintenant</button>':'<button class="btn primary" data-act="pl_join">Rejoindre l’équipe</button>'}<button class="btn" data-act="au_force">Recharger tout</button><button class="btn" data-act="close">Fermer</button></div>
     ${devs?`<h3 class="mah" style="margin-top:16px">Appareils de l’équipe</h3><div class="card" style="margin:6px 0 0">${devs}</div>`:''}</div>`);
  }
  if(on)setTimeout(()=>{
    const e=document.getElementById('sypend');if(e){const n=syPending();e.textContent=n?n+' en attente':'aucune'}
    const z=document.getElementById('sysize');
    if(z){try{const mo=JSON.stringify(CL.R||{}).length/1048576;z.textContent=(mo<0.1?'moins de 0,1':mo.toFixed(1).replace('.',','))+' Mo'+(mo>8?' · lourde : le démarrage peut ralentir':'')}catch(x){z.textContent='—'}}
  },60);
}
async function syNow(btn){
  if(!cloudOn())return;
  if(btn)btn.disabled=true;
  CL.fetched=false;try{cloudWake(true);cloudKick(0)}catch(e){}
  await new Promise(r=>setTimeout(r,1800));
  if(btn&&btn.isConnected)btn.disabled=false;
  try{syDraw()}catch(e){}
  if(document.getElementById('sypanel'))syOpen(true);
  toast(CL.state==='ok'?'Synchronisé':'Toujours hors ligne : nouvel essai automatique');
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="sy_open"],[data-act="sy_now"],[data-act="sy_hide"]');if(!b)return;const a=b.dataset.act;
  if(a==='sy_open')syOpen();else if(a==='sy_now')syNow(b);
  else{try{sessionStorage.setItem('lago-sy-x','1')}catch(x){}syDraw()}
});
/* ======== v75 : e-mails aux clients (ticket, avoir, carte cadeau, réservation) ======== */
IC.mail='<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/>';
const MJ_QUOTA=200;
/* Réglage EmailJS : dans S.settings.mailjs (l’ancien emplacement S.settings.mail est l’adresse de contact du parc) */
function mjCfg(){const st=S.settings||{};return st.mailjs&&typeof st.mailjs==='object'?st.mailjs:(st.mail&&typeof st.mail==='object'?st.mail:{})}
function mjSet(o){S.settings.mailjs=Object.assign({},mjCfg(),o)}
function mlMailStr(){const m=S.settings&&S.settings.mail;return typeof m==='string'?m.trim():''}
function mlContact(){const m=mlMailStr();return m==='contact@exemple.fr'?'':m}
function migrateM(){
  let ch=false;
  try{
    const st=S.settings;if(!st)return false;
    if(st.mail&&typeof st.mail==='object'){
      const o=st.mail,j=(st.mailjs&&typeof st.mailjs==='object')?Object.assign({},st.mailjs):{};
      ['sid','tid','key'].forEach(k=>{if(o[k]&&!j[k])j[k]=String(o[k]).trim()});
      st.mailjs=j;
      const lm=String((st.legal&&st.legal.mail)||'').trim();
      st.mail=MAILRE.test(lm)?lm:'';ch=true;
    }
    if(!Array.isArray(S.mlog)){S.mlog=[]}
  }catch(e){}
  return ch;
}
const mlE=c=>{const e=new Error(c);e.mlc=c;return e};
const mlFrom=()=>String(mjCfg().name||'').trim()||S.settings.name||'Lago';
const mlReply=()=>{const a=String(mjCfg().addr||'').trim();return MAILRE.test(a)?a:(MAILRE.test(mlContact())?mlContact():'')};
function mlMonthUse(){const d=new Date(),y=d.getFullYear(),mo=d.getMonth();return (S.mlog||[]).filter(x=>{if(!x.ok)return false;const a=new Date(x.ts);return a.getFullYear()===y&&a.getMonth()===mo}).length}
function mlQuota(){const q=Math.max(1,parseInt(mjCfg().quota)||MJ_QUOTA),u=mlMonthUse();return{q,u,left:q-u}}
function mlErrTxt(e){
  const c=e&&e.mlc;
  if(c==='config')return 'l’envoi d’e-mails n’est pas activé (Paramètres › E-mails)';
  if(c==='addr')return 'adresse e-mail invalide';
  if(c==='size')return 'message trop volumineux pour le service d’e-mails';
  if(c==='quota'){const q=mlQuota();return 'quota du mois atteint ('+q.u+' sur '+q.q+' e-mails)'}
  return mailErr(e);
}
const ML_KIND={ticket:'Ticket',avoir:'Avoir',gift:'Carte cadeau',resa:'Réservation',mdp:'Mot de passe',test:'Test'};
/* envoi + journal (le journal est partagé avec l’équipe : on voit qui a envoyé quoi, et on évite les doublons) */
async function mlSend(o){
  if(!mailCfg())throw mlE('config');
  const to=String(o.to||'').trim().toLowerCase();
  if(!MAILRE.test(to)||to.length>254)throw mlE('addr');
  const subject=String(o.subject||'').replace(/[\r\n\t]+/g,' ').trim().slice(0,150),html=String(o.html||'');
  if(html.length>40000)throw mlE('size');
  if(o.kind!=='mdp'&&mlQuota().left<=0)throw mlE('quota');
  const en={id:uid(),ts:Date.now(),k:o.kind||'doc',ref:String(o.ref||'').slice(0,40),to,ok:false,by:(typeof ME!=='undefined'&&ME)?String(ME.name||'').slice(0,60):''};
  const log=()=>{
    if(!Array.isArray(S.mlog))S.mlog=[];
    S.mlog.push(en);
    const lim=Date.now()-366*86400000;S.mlog=S.mlog.filter(x=>x.ts>=lim);
    if(S.mlog.length>300)S.mlog=S.mlog.slice(-300);
    save();
  };
  try{
    await mailSend(to,Object.assign({to_name:String(o.toName||'').slice(0,80),subject,message_html:html},o.extra||{}));
    en.ok=true;log();return en;
  }catch(x){en.err=String(mlErrTxt(x)).slice(0,120);log();throw x}
}
/* ---------- documents ---------- */
const mlCap=s=>s?s.charAt(0).toUpperCase()+s.slice(1):s;
const mlFmtD=ts=>new Date(ts).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
const mlHello=n=>{n=String(n||'').trim();return n?'Bonjour '+firstName(n)+',':'Bonjour,'};
const mlRate=r=>String(r).replace('.',',');
function mlRender(d){
  const brand=/^#[0-9a-fA-F]{6}$/.test(String(S.settings.brand||''))?S.settings.brand:'#1D4FD7';
  const nm=S.settings.name||'Lago',F='font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;';
  const nl=x=>esc(String(x).slice(0,2000)).replace(/\n/g,'<br>');
  let h='',t=[];
  (d.parts||[]).slice(0,60).forEach(p=>{
    if(p.t==='p'){h+=`<p style="${F}margin:0 0 12px;font-size:15px;line-height:1.55;color:#1f2430">${nl(p.x)}</p>`;t.push(String(p.x))}
    else if(p.t==='h'){h+=`<h2 style="${F}margin:16px 0 6px;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:#6b7280">${esc(p.x)}</h2>`;t.push('— '+p.x+' —')}
    else if(p.t==='box'){h+=`<div style="${F}margin:0 0 14px;padding:10px 12px;background:#f3f5f9;border-left:4px solid ${brand};border-radius:6px;font-size:14px;line-height:1.5;color:#1f2430">${nl(p.x)}</div>`;t.push(String(p.x))}
    else if(p.t==='small'){h+=`<p style="${F}margin:0 0 12px;font-size:12.5px;line-height:1.5;color:#6b7280">${nl(p.x)}</p>`;t.push(String(p.x))}
    else if(p.t==='big'){h+=`<div style="margin:6px 0 16px;padding:16px;border:2px dashed ${brand};border-radius:10px;text-align:center"><div style="font-family:Menlo,Consolas,monospace;font-size:26px;letter-spacing:2px;font-weight:700;color:#111;word-break:break-all">${esc(p.x)}</div>${p.s?`<div style="${F}font-size:13px;color:#6b7280;margin-top:4px">${esc(p.s)}</div>`:''}</div>`;t.push(String(p.x)+(p.s?' ('+p.s+')':''))}
    else if(p.t==='rows'){
      h+=`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 14px;border-collapse:collapse">`+p.r.slice(0,80).map(r=>`<tr><td style="${F}padding:6px 0;border-bottom:1px solid #e6e9ef;font-size:14px;color:${r[2]?'#111':'#374151'};${r[2]?'font-weight:700;':''}">${esc(r[0])}</td><td align="right" style="${F}padding:6px 0 6px 12px;border-bottom:1px solid #e6e9ef;font-size:14px;white-space:nowrap;color:#111;${r[2]?'font-weight:700;':''}">${esc(r[1])}</td></tr>`).join('')+`</table>`;
      t.push(p.r.map(r=>r[0]+' : '+r[1]).join('\n'));
    }
  });
  const foot=[];
  try{if(typeof cfLegalLines==='function')cfLegalLines().forEach(x=>foot.push(x))}catch(e){}
  if(S.settings.addr&&!foot.includes(S.settings.addr))foot.push(S.settings.addr);
  const ct=[mlContact(),S.settings.phone].filter(Boolean).join(' · ');if(ct)foot.push(ct);
  const fx=String(mjCfg().foot||'').trim().slice(0,400);if(fx)foot.push(fx);
  h=`<div style="background:#eef0f4;padding:20px 10px"><div style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(d.pre||d.title||'')}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">`+
    `<tr><td style="background:${brand};padding:18px 22px"><div style="${F}font-size:20px;font-weight:700;color:#ffffff">${esc(nm)}</div></td></tr>`+
    `<tr><td style="padding:22px 22px 8px">${d.title?`<h1 style="${F}margin:0 0 14px;font-size:20px;line-height:1.25;color:#111">${esc(d.title)}</h1>`:''}${h}</td></tr>`+
    (foot.length?`<tr><td style="background:#f8f9fb;padding:14px 22px;border-top:1px solid #e6e9ef;${F}font-size:12px;line-height:1.55;color:#6b7280">${foot.map(x=>esc(x)).join('<br>')}</td></tr>`:'')+
    `</table></td></tr></table></div>`;
  const text=[nm.toUpperCase(),d.title||''].concat(t,foot.length?['','--'].concat(foot):[]).join('\n').replace(/\n{3,}/g,'\n\n').trim();
  return{subject:String(d.subject||nm).replace(/[\r\n\t]+/g,' ').trim().slice(0,150),html:h,text};
}
function mlTicketDoc(s){
  const av=s.ty==='av',cl=s.clientId?clientById(s.clientId):null,nm=S.settings.name||'Lago',P=[];
  P.push({t:'p',x:mlHello(cl&&!cl.anon?cl.name:'')});
  P.push({t:'p',x:av?'Voici l’avoir établi le '+mlFmtD(s.ts)+' sur le ticket '+s.rf+'.':'Merci de votre visite ! Voici le ticket de votre achat du '+mlFmtD(s.ts)+' à '+hm(s.ts)+'.'});
  if(av&&s.mt)P.push({t:'box',x:'Motif : '+s.mt});
  if(s.slot){const sp=String(s.slot).split('|'),st=+sp[1],dur=s.dur||60,b=bracelet(st,dur);P.push({t:'box',x:'Créneau : '+fm(st)+' à '+fm(st+dur)+' le '+new Date(sp[0]+'T12:00').toLocaleDateString('fr-FR')+'\nBracelet '+b.name+', valable jusqu’à '+b.until+'h'})}
  P.push({t:'rows',r:(s.lines||[]).map(l=>[Math.abs(l.qty)+' × '+l.name,eur(Math.abs(l.price*l.qty))])});
  const R=[];
  if(s.disc)R.push(['Remise'+(s.discLabel?' '+s.discLabel:''),'− '+eur(Math.abs(s.disc))]);
  R.push([av?'Montant de l’avoir':'TOTAL TTC',eur(Math.abs(s.total)),true]);
  Object.entries(s.vat||{}).forEach(([r,v])=>R.push(['dont TVA '+mlRate(r)+' %',eur(Math.abs(v.tva))]));
  P.push({t:'rows',r:R});
  if((s.pay||[]).length){P.push({t:'h',x:av?'Règlements concernés':'Règlement'});P.push({t:'rows',r:s.pay.map(p=>[METHODS[p.m]||p.m,eur(Math.abs(p.amt))])})}
  if(!av&&s.change)P.push({t:'small',x:'Monnaie rendue : '+eur(s.change)});
  if(s.passUse)P.push({t:'box',x:'Carnet '+s.passUse.code+' : '+s.passUse.k+' séance'+(s.passUse.k>1?'s':'')+' utilisée'+(s.passUse.k>1?'s':'')});
  (s.newPasses||[]).forEach(cd=>P.push({t:'box',x:'Votre carnet de séances : '+cd+'\nPrésentez ce code à l’accueil à chaque venue.'}));
  if(!av&&s.pts&&cl)P.push({t:'box',x:'Fidélité : +'+s.pts+' point'+(s.pts>1?'s':'')+' sur cet achat · total '+(cl.pts||0)+' point'+((cl.pts||0)>1?'s':'')});
  if(!av&&S.settings.ticketMsg)P.push({t:'p',x:S.settings.ticketMsg});
  if(!av&&s.jumpers>0&&s.no)P.push({t:'small',x:'Gardez ce message : le numéro de ticket '+s.no+' permet de retrouver votre venue.'});
  P.push({t:'small',x:(av?'Avoir':'Ticket')+' n° '+s.no+(s.h?' · Lago '+LAGO_V+' · empreinte '+String(s.h).slice(0,16):'')});
  const title=(av?'Avoir ':'Ticket ')+s.no;
  return{kind:av?'avoir':'ticket',ref:s.no,to:cl&&!cl.anon?String(cl.email||''):'',toName:cl&&!cl.anon?cl.name:'',cid:cl?cl.id:'',title,pre:title+' · '+eur(Math.abs(s.total)),subject:nm+' : votre '+(av?'avoir':'ticket')+' '+s.no,parts:P};
}
function mlGiftDoc(g){
  const nm=S.settings.name||'Lago',st=giftState(g),P=[];
  P.push({t:'p',x:mlHello(g.to)});
  P.push({t:'p',x:g.from?g.from+' vous offre une carte cadeau '+nm+'.':'Voici votre carte cadeau '+nm+'.'});
  P.push({t:'big',x:g.code,s:'Montant : '+eurP(g.amt)+(g.bal!==g.amt?' · solde '+eurP(g.bal):'')});
  const R=[['Montant',eurP(g.amt)]];
  if(g.bal!==g.amt)R.push(['Solde actuel',eurP(g.bal),true]);
  if(g.exp)R.push(['Valable jusqu’au',new Date(g.exp+'T12:00').toLocaleDateString('fr-FR')]);
  if(g.to)R.push(['Pour',g.to]);
  if(g.from)R.push(['De la part de',g.from]);
  P.push({t:'rows',r:R});
  if(g.msg)P.push({t:'box',x:g.msg});
  if(st!=='ok')P.push({t:'box',x:'Attention : cette carte n’est plus utilisable ('+(GSL[st]?GSL[st][0].toLowerCase():st)+').'});
  P.push({t:'p',x:'Présentez ce code en caisse pour régler tout ou partie de votre venue. Le solde restant reste utilisable jusqu’à la date de validité.'});
  return{kind:'gift',ref:g.code,to:'',toName:g.to||'',cid:'',title:'Votre carte cadeau',pre:'Carte cadeau '+eurP(g.amt),subject:nm+' : votre carte cadeau',parts:P};
}
function mlResaDoc(b){
  const nm=S.settings.name||'Lago',P=[],w=S.settings.web||{},left=Math.max(0,(b.total||0)-(b.paid?b.paid.a:0));
  P.push({t:'p',x:mlHello(b.name)});
  P.push({t:'p',x:'Votre réservation est confirmée. À très vite !'});
  P.push({t:'box',x:mlCap(dlong(b.date))+' à '+fm(b.start)+'\n'+b.people+' personne'+(b.people>1?'s':'')+' · référence '+b.ref});
  P.push({t:'rows',r:(b.items||[]).map(x=>[x.q+' × '+x.n,eur(x.q*x.price)])});
  const R=[[b.paid?'Total de la réservation':'Total à régler sur place',eur(b.total||0),true]];
  if(b.paid){R.push(['Payé en ligne','− '+eur(b.paid.a)]);R.push(['Reste à régler sur place',eur(left),true])}
  P.push({t:'rows',r:R});
  if(b.note)P.push({t:'small',x:'Votre message : '+b.note});
  if(w.info)P.push({t:'h',x:'Informations pratiques'},{t:'p',x:w.info});
  if(S.settings.addr)P.push({t:'small',x:'Adresse : '+S.settings.addr});
  return{kind:'resa',ref:b.ref,to:String(b.mail||''),toName:b.name||'',cid:b.clientId||'',title:'Réservation '+b.ref,pre:mlCap(dlong(b.date))+' à '+fm(b.start),subject:'Votre réservation '+b.ref+' – '+nm,parts:P};
}
function mlResetMsg(a,to,code){
  const nm=S.settings.name||'Lago',d={title:'Votre code de connexion',pre:'Code : '+rstShow(code),subject:nm+' : votre code de connexion',parts:[
    {t:'p',x:mlHello(a.name)},{t:'p',x:'Voici le code pour choisir un nouveau mot de passe :'},
    {t:'big',x:rstShow(code),s:'valable '+RST_MIN+' minutes'},
    {t:'small',x:'Identifiant : '+a.ident+'\nSi vous n’êtes pas à l’origine de cette demande, ignorez ce message.'}]};
  const r=mlRender(d);
  return{to,toName:a.name,subject:r.subject,html:r.html,kind:'mdp',ref:'',extra:{code:rstShow(code),minutes:RST_MIN,login:a.ident}};
}
/* ---------- fenêtre « Envoyer par e-mail » ---------- */
let MLD=null;
function mlDlg(doc,back){
  const r=mlRender(doc),ok=!!mailCfg(),cl=doc.cid?clientById(doc.cid):null;
  MLD={doc,r,back:back||null,busy:false};
  const prev=(S.mlog||[]).filter(x=>x.k===doc.kind&&x.ref===doc.ref&&x.ok).slice(-1)[0];
  const q=mlQuota(),admin=isAdmin();
  showModal(`${mh('Envoyer par e-mail')}
   <div class="field"><label for="mld_to">Adresse du destinataire</label><input id="mld_to" type="email" inputmode="email" autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" value="${esc(doc.to||'')}" placeholder="prenom@exemple.fr"></div>
   ${cl&&!cl.anon?`<label class="check mldsv" id="mld_svw" style="margin:0 0 8px"><input type="checkbox" id="mld_sv" ${cl.email?'':'checked'}><span>Enregistrer cette adresse sur la fiche de ${esc(cl.name)}</span></label>`:''}
   ${prev?`<p class="muted mlden" style="margin:0 0 8px;font-size:13px">Déjà envoyé à ${esc(prev.to)} le ${new Date(prev.ts).toLocaleDateString('fr-FR')} à ${hm(prev.ts)}.</p>`:''}
   <div class="mlprev" id="mld_prev" aria-label="Aperçu du message"></div>
   ${ok?'':`<p class="muted" style="margin:0 0 8px;font-size:13px">L’envoi automatique n’est pas encore activé. ${admin?'Vous pouvez l’activer dans <b>Paramètres › E-mails</b> (5 minutes). En attendant, ouvrez le message dans votre messagerie.':'Demandez à l’administrateur de l’activer. En attendant, ouvrez le message dans votre messagerie.'}</p>`}
   ${ok&&q.left<=Math.max(5,Math.round(q.q*.05))?`<p class="muted" style="margin:0 0 8px;font-size:13px">Quota du mois presque atteint : ${q.u} e-mail${q.u>1?'s':''} sur ${q.q}.</p>`:''}
   <p id="mld_msg" class="muted" role="status" style="min-height:20px;margin:0 0 8px;font-size:13.5px"></p>
   <div class="acts">${ok?`<button class="btn primary" id="mld_go" data-act="ml_go">${ic('mail')}Envoyer</button>`:`<button class="btn primary" data-act="ml_mt">${ic('mail')}Ouvrir ma messagerie</button>`}<button class="btn" data-act="ml_copy">Copier le texte</button>${!ok&&admin?'<button class="btn" data-act="goto" data-v="params" data-t="pmail">Activer l’envoi</button>':''}<button class="btn" data-act="ml_back">Retour</button></div>`);
  try{const host=$('#mld_prev'),sr=host.attachShadow?host.attachShadow({mode:'open'}):null;if(sr)sr.innerHTML=r.html;else host.textContent=r.text}catch(e){}
  setTimeout(()=>{const i=$('#mld_to');if(i&&!i.value)i.focus()},60);
}
function mlMsg(t,good){const x=$('#mld_msg');if(x){x.textContent=t;x.style.color=good?'var(--ok)':''}}
function mlBack(){
  const b=MLD&&MLD.back;
  if(b&&b.k==='sale'){const s=S.sales.find(x=>x.id===b.id);if(s){showReceipt(s,!!b.isNew);return}}
  else if(b&&b.k==='gift'){gcOpen(b.id);return}
  else if(b&&b.k==='resa'){webDetail(b.id);return}
  closeModal();
}
async function mlGo(){
  if(!MLD||MLD.busy)return;
  const to=(($('#mld_to')||{}).value||'').trim().toLowerCase();
  if(!MAILRE.test(to)){mlMsg('Adresse e-mail invalide.');return}
  const doc=MLD.doc,r=MLD.r,sv=$('#mld_sv'),cid=doc.cid,btn=$('#mld_go');
  MLD.busy=true;if(btn)btn.disabled=true;mlMsg('Envoi en cours…');
  try{
    await mlSend({to,toName:doc.toName,subject:r.subject,html:r.html,kind:doc.kind,ref:doc.ref});
    if(sv&&sv.checked&&cid){const c=clientById(cid);if(c&&!c.anon){c.email=to;save()}}
    mlMsg('✓ E-mail envoyé à '+to+'.',true);toast('E-mail envoyé');
  }catch(e){console.warn('mail',e);mlMsg('Échec : '+mlErrTxt(e)+'.')}
  if(MLD)MLD.busy=false;const b2=$('#mld_go');if(b2)b2.disabled=false;
}
function mlMailtoHref(){
  const to=(($('#mld_to')||{}).value||'').trim(),t=MLD.r.text.length>1400?MLD.r.text.slice(0,1400)+'…':MLD.r.text;
  return 'mailto:'+encodeURIComponent(to).replace(/%40/g,'@')+'?subject='+encodeURIComponent(MLD.r.subject)+'&body='+encodeURIComponent(t);
}
async function mlCopy(){try{await zCopy(MLD.r.text,'Texte copié')}catch(e){toast('Copie impossible')}}
/* envoi automatique du ticket (réglable) : seulement sur l’appareil qui encaisse, une seule fois par ticket */
const mlAutoBusy={};
function mlNote(id,t,good){
  const x=document.getElementById('mlauto');
  if(x&&x.dataset.id===id){x.textContent=t;x.style.color=good?'var(--ok)':''}else if(good)toast(t);
}
async function mlAuto(s){
  try{
    const j=mjCfg();if(!j.autoTicket||!mailCfg())return;
    if(s.ty==='av'||s.qw||s.demo)return;
    const cl=s.clientId?clientById(s.clientId):null,to=cl&&!cl.anon?String(cl.email||'').trim().toLowerCase():'';
    if(!to||!MAILRE.test(to))return;
    if((S.mlog||[]).some(x=>x.k==='ticket'&&x.ref===s.no&&x.ok)||mlAutoBusy[s.id])return;
    mlAutoBusy[s.id]=1;
    const r=mlRender(mlTicketDoc(s));
    mlNote(s.id,'Envoi du ticket à '+to+'…');
    await mlSend({to,toName:cl.name,subject:r.subject,html:r.html,kind:'ticket',ref:s.no});
    mlNote(s.id,'✓ Ticket envoyé à '+to,true);
  }catch(e){console.warn('mail',e);mlNote(s.id,'Le ticket n’a pas pu être envoyé par e-mail ('+mlErrTxt(e)+').')}
}
function mlReceiptBtn(s,isNew){
  const m=document.querySelector('#modal .modal');if(!m||!s||s.qw)return;
  const prim=m.querySelector('button.primary[data-act="close"]');if(!prim||m.querySelector('[data-act="ml_ticket"]'))return;
  const btn=`<button class="btn" data-act="ml_ticket" data-id="${esc(s.id)}" data-new="${isNew?1:0}">${ic('mail')}E-mail</button>`;
  let box=m.querySelector('.cfacts');
  if(box)box.insertAdjacentHTML('afterbegin',btn);
  else prim.insertAdjacentHTML('beforebegin','<div class="acts cfacts">'+btn+'</div>');
  if(isNew&&s.ty!=='av'&&mjCfg().autoTicket&&mailCfg()){
    const cl=s.clientId?clientById(s.clientId):null;
    if(cl&&!cl.anon&&MAILRE.test(String(cl.email||'').trim())){
      m.querySelector('.cfacts').insertAdjacentHTML('beforebegin','<p class="muted" id="mlauto" data-id="'+esc(s.id)+'" style="margin:8px 0;font-size:13px"></p>');
      mlAuto(s);
    }
  }
}
{const f=showReceipt;showReceipt=function(s,isNew){f(s,isNew);try{mlReceiptBtn(s,isNew)}catch(e){console.warn(e)}}}
{const f=gcOpen;gcOpen=function(id){f(id);try{const g=gifts().find(x=>x.id===id),a=document.querySelectorAll('#modal .modal .acts');if(g&&a.length&&!document.querySelector('#modal [data-act="ml_gift"]'))a[a.length-1].insertAdjacentHTML('beforeend',`<button class="btn" data-act="ml_gift" data-id="${esc(g.id)}">${ic('mail')}E-mail</button>`)}catch(e){console.warn(e)}}}
{const f=webDetail;webDetail=function(id){f(id);try{
  const b=webOf(id),a=document.querySelectorAll('#modal .modal .acts');
  if(b&&(b.st==='ok'||b.st==='done')&&a.length&&!document.querySelector('#modal [data-act="ml_resa"]')){
    const cl=a[a.length-1].querySelector('[data-act="close"]'),h=`<button class="btn" data-act="ml_resa" data-id="${esc(b.id)}">${ic('mail')}Confirmation par e-mail</button>`;
    if(cl)cl.insertAdjacentHTML('beforebegin',h);else a[a.length-1].insertAdjacentHTML('beforeend',h);
  }}catch(e){console.warn(e)}}}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-act^="ml_"]');if(!b||b.disabled)return;const a=b.dataset.act;
  if(a==='ml_ticket'){const s=S.sales.find(x=>x.id===b.dataset.id);if(s)mlDlg(mlTicketDoc(s),{k:'sale',id:s.id,isNew:b.dataset.new==='1'})}
  else if(a==='ml_gift'){const g=gifts().find(x=>x.id===b.dataset.id);if(g)mlDlg(mlGiftDoc(g),{k:'gift',id:g.id})}
  else if(a==='ml_resa'){const w=webOf(b.dataset.id);if(w)mlDlg(mlResaDoc(w),{k:'resa',id:w.id})}
  else if(a==='ml_go')mlGo();
  else if(a==='ml_back')mlBack();
  else if(a==='ml_copy')mlCopy();
  else if(a==='ml_mt'&&MLD){const to=(($('#mld_to')||{}).value||'').trim();if(!MAILRE.test(to)){mlMsg('Indiquez d’abord l’adresse du destinataire.');return}location.href=mlMailtoHref()}
});
/* ---------- Paramètres › E-mails ---------- */
function mlSample(){
  const k=Object.keys(METHODS)[0],lines=[{qty:2,name:'Entrée 1 h',price:1500,rate:10},{qty:1,name:'Chaussettes',price:300,rate:20}],tot=3300;
  return{id:'smp',no:'TEST-0001',ts:Date.now(),lines,total:tot,disc:0,vat:{'10':{ttc:3000,tva:273},'20':{ttc:300,tva:50}},pay:[{m:k,amt:tot}],clientId:null,jumpers:0};
}
const MM_KINDS=ML_KIND;
function vSetMail(m){
  if(!isAdmin()){m.innerHTML='<div class="card"><p class="muted">Réservé à l’administrateur.</p></div>';return}
  const c=mjCfg(),ok=!!mailCfg(),q=mlQuota(),pc=Math.min(100,Math.round(q.u/q.q*100));
  const inp=(id,v,ph,ty)=>`<input id="${id}" ${ty?'type="'+ty+'" ':''}value="${esc(v||'')}" placeholder="${esc(ph||'')}" autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off">`;
  const cp=(t,what)=>`<button type="button" class="btn mmcp" data-act="mm_cp" data-v="${esc(what)}" aria-label="Copier ${esc(t)}">Copier</button>`;
  const lg=(S.mlog||[]).slice().sort((a,b)=>b.ts-a.ts).slice(0,25);
  const row=(l,v,w)=>`<div class="row mmrow"><span class="grow"><b>${l}</b></span><code>${esc(v)}</code>${cp(l,w)}</div>`;
  m.innerHTML=`<div class="card"><h3>E-mails aux clients ${ok?'<span class="pill ok">Activé</span>':'<span class="pill warn">À configurer</span>'}</h3>
   <p class="muted" style="font-size:13.5px;margin:0 0 12px">Envoyez en un geste le ticket, l’avoir, la carte cadeau ou la confirmation de réservation. Les e-mails partent <b>de votre propre adresse</b> (celle de votre nom de domaine) grâce à EmailJS, un service gratuit jusqu’à ${MJ_QUOTA} e-mails par mois, relié à votre messagerie.</p>
   ${fld('Service ID',inp('mm_sid',c.sid,'service_xxxxxxx'))}${fld('Template ID',inp('mm_tid',c.tid,'template_xxxxxxx'))}${fld('Public Key',inp('mm_key',c.key,'xxxxxxxxxxxxxxxx'))}
   ${fld('Nom d’expéditeur affiché',inp('mm_name',c.name,S.settings.name||'Nom de votre parc'),'Ce que le client voit à la place de l’adresse : « '+esc(mlFrom())+' ».')}
   ${fld('Adresse de réponse',inp('mm_addr',c.addr,mlContact()||'contact@votre-parc.fr','email'),'Quand le client répond, sa réponse arrive ici. Laissez vide pour utiliser l’e-mail de contact du parc.')}
   ${fld('Message en bas de chaque e-mail (facultatif)','<textarea id="mm_foot" maxlength="400" rows="3" placeholder="Ex. : Horaires, réseaux sociaux, mention de retour…">'+esc(c.foot||'')+'</textarea>')}
   <label class="check" style="margin:6px 0 10px"><input type="checkbox" id="mm_auto" ${c.autoTicket?'checked':''}><span>Envoyer automatiquement le ticket après chaque vente quand la fiche client a une adresse e-mail</span></label>
   ${fld('Quota mensuel de votre offre EmailJS',inp('mm_quota',String(c.quota||MJ_QUOTA),'200','number'),'À modifier seulement si vous passez à une offre payante.')}
   <div class="mlq"><div class="mlbar"><i style="width:${pc}%"></i></div><span class="muted" style="font-size:13px">${q.u} e-mail${q.u>1?'s':''} envoyé${q.u>1?'s':''} ce mois-ci sur ${q.q}</span></div>
   <p id="mm_msg" class="muted" style="min-height:20px;font-size:13.5px;margin:10px 0 0" role="status"></p>
   <div class="acts"><button class="btn primary" data-act="mm_save">Enregistrer</button></div>
   <div class="field" style="margin-top:14px"><label for="mm_to">E-mail de test</label>${inp('mm_to',mailOf(ME),'votre@adresse.fr','email')}<span class="muted" style="font-size:13px">Envoie un faux ticket à cette adresse pour vérifier le réglage et l’apparence.</span></div>
   <div class="acts"><button class="btn" data-act="mm_test" ${ok?'':'disabled'}>Envoyer un e-mail de test</button></div></div>
  <div class="card"><h3>Mise en place (10 minutes, une seule fois)</h3>
   <ol class="mmsteps">
    <li><b>Créez un compte gratuit</b> sur <b>emailjs.com</b>.</li>
    <li><b>Email Services › Add New Service</b>. Pour envoyer avec l’adresse de votre nom de domaine (par exemple contact@votre-parc.fr), choisissez la messagerie qui l’héberge : <b>Gmail</b> (Google Workspace), <b>Outlook</b> (Microsoft 365) ou <b>SMTP server</b> pour les autres (OVH, IONOS, o2switch…). Les paramètres du serveur sortant (hôte, port, identifiant, mot de passe) sont dans l’espace de votre hébergeur de messagerie. Selon votre offre EmailJS, l’option SMTP peut ne pas être proposée : dans ce cas, utilisez Gmail ou Outlook ou passez à l’offre payante. Copiez le <b>Service ID</b>.</li>
    <li><b>Email Templates › Create New Template</b>, puis remplissez ces champs :
     <div class="mmbox">${row('To Email','{{to_email}}','to')}${row('Subject','{{subject}}','subject')}${row('From Name','{{from_name}}','from')}${row('Reply To','{{reply_to}}','reply')}${row('Contenu (Content)','{{{message_html}}}','body')}</div>
     <span class="muted" style="font-size:13px">Pour le contenu, ouvrez l’éditeur en mode <b>code (Edit Content › Code Editor)</b> et collez uniquement <code>{{{message_html}}}</code> avec <b>trois</b> accolades de chaque côté : c’est ce qui affiche la mise en page. Enregistrez et copiez le <b>Template ID</b>.</span></li>
    <li><b>Account › General</b> : copiez la <b>Public Key</b>.</li>
    <li>Collez les trois codes ci-dessus, enregistrez, puis envoyez-vous un e-mail de test.</li>
   </ol>
   <p class="muted" style="font-size:13px;margin:8px 0 0">Bon à savoir : l’offre gratuite n’envoie pas de pièces jointes (le document est dans le corps du message) et limite chaque e-mail à 50 Ko. Pour que les messages n’arrivent pas en courrier indésirable, envoyez depuis une vraie boîte de votre domaine (réglages SPF/DKIM de votre hébergeur de messagerie).</p></div>
  <div class="card"><h3>Journal des envois</h3>
   ${lg.length?lg.map(x=>`<div class="row"><span class="grow"><b>${esc(MM_KINDS[x.k]||x.k)}${x.ref?' · '+esc(x.ref):''}</b><span class="muted">${new Date(x.ts).toLocaleDateString('fr-FR')} ${hm(x.ts)} · ${x.to?esc(x.to):'adresse effacée'}${x.by?' · par '+esc(x.by):''}${x.ok?'':' · <b style="color:var(--bad)">échec : '+esc(x.err||'')+'</b>'}</span></span><span class="pill ${x.ok?'ok':'bad'}">${x.ok?'Envoyé':'Échec'}</span></div>`).join(''):'<p class="muted">Aucun e-mail envoyé pour le moment.</p>'}
   ${(S.mlog||[]).length?'<div class="acts" style="margin-top:10px"><button class="btn" data-act="mm_purge">Vider le journal</button></div>':''}
   <p class="muted" style="font-size:13px;margin:8px 0 0">Le journal garde 12 mois (date, destinataire, type de document, auteur). Le contenu des messages n’est pas conservé.</p></div>`;
}
TABS.params.splice(Math.max(1,TABS.params.findIndex(x=>x[0]==='pacc')+1),0,['pmail','E-mails']);SUBS.pmail=vSetMail;
function mlAccPointer(m){
  if(!isAdmin()||!m)return;
  m.insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:14px"><h3>E-mails ${mailCfg()?'<span class="pill ok">Activé</span>':'<span class="pill warn">À configurer</span>'}</h3><p class="muted" style="font-size:13.5px;margin:0 0 8px">Mot de passe oublié, tickets, avoirs, cartes cadeaux et confirmations de réservation : tout se règle dans Paramètres › E-mails.</p><div class="acts"><button class="btn" data-act="goto" data-v="params" data-t="pmail">${ic('mail')}Ouvrir les réglages e-mails</button></div></div>`);
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-act^="mm_"]');if(!b||b.disabled||!isAdmin())return;const a=b.dataset.act,msg=t=>{const x=$('#mm_msg');if(x)x.textContent=t};
  const val=id=>String((($('#'+id)||{}).value)||'').trim();
  if(a==='mm_save'){
    const ad=val('mm_addr');if(ad&&!MAILRE.test(ad)){msg('Adresse de réponse invalide.');return}
    const qn=Math.max(1,Math.min(100000,parseInt(val('mm_quota'))||MJ_QUOTA));
    mjSet({sid:val('mm_sid'),tid:val('mm_tid'),key:val('mm_key'),name:val('mm_name').slice(0,60),addr:ad,foot:String((($('#mm_foot')||{}).value)||'').trim().slice(0,400),autoTicket:!!($('#mm_auto')||{}).checked,quota:qn});
    save();vSetMail($('#sub'));const ok=!!mailCfg();toast(ok?'E-mails activés':'Réglage enregistré (incomplet)');
    const x=$('#mm_msg');if(x)x.textContent=ok?'Réglage enregistré. Envoyez-vous un e-mail de test pour vérifier.':'Il manque encore le Service ID, le Template ID ou la Public Key.';
  }else if(a==='mm_test'){
    const to=val('mm_to').toLowerCase();if(!MAILRE.test(to)){msg('Indiquez une adresse e-mail valide pour le test.');return}
    b.disabled=true;msg('Envoi en cours…');
    try{const d=mlTicketDoc(mlSample());d.subject='[Test] '+d.subject;const r=mlRender(d);
      await mlSend({to,toName:ME?ME.name:'',subject:r.subject,html:r.html,kind:'test',ref:'TEST'});
      vSetMail($('#sub'));const x=$('#mm_msg');if(x)x.textContent='✓ E-mail de test envoyé à '+to+'. Ouvrez-le : si vous voyez le ticket mis en page, tout est prêt. Si vous voyez du texte brut ou un message vide, le contenu du modèle n’est pas {{{message_html}}}.';toast('E-mail de test envoyé')}
    catch(x){console.warn('mail',x);msg('Échec : '+mlErrTxt(x)+'.');if(b.isConnected)b.disabled=false}
  }else if(a==='mm_cp'){
    const T={to:'{{to_email}}',subject:'{{subject}}',from:'{{from_name}}',reply:'{{reply_to}}',body:'{{{message_html}}}'};
    try{await zCopy(T[b.dataset.v]||'','Copié')}catch(x){toast('Copie impossible')}
  }else if(a==='mm_purge'){
    askYes('Vider le journal des envois d’e-mails ? Le compteur du mois repart de zéro.',()=>{S.mlog=[];save();closeModal();vSetMail($('#sub'));toast('Journal vidé')},'Vider');
  }
});
/* RGPD : effacer les adresses d’un client dans le journal */
function mlForget(list){
  const set=new Set((list||[]).map(x=>String(x||'').trim().toLowerCase()).filter(Boolean));if(!set.size)return;
  (S.mlog||[]).forEach(x=>{if(x.to&&set.has(String(x.to).toLowerCase()))x.to=''});
}
function mlPersonLog(c){
  const set=new Set([c.email].concat((S.web||[]).filter(b=>b.clientId===c.id).map(b=>b.mail)).map(x=>String(x||'').trim().toLowerCase()).filter(Boolean));
  return (S.mlog||[]).filter(x=>x.to&&set.has(String(x.to).toLowerCase())).map(x=>({date:new Date(x.ts).toISOString(),type:ML_KIND[x.k]||x.k,reference:x.ref||'',destinataire:x.to,envoye:!!x.ok}));
}
/* ======== v75 : les plannings s’ouvrent sur le jour d’aujourd’hui et suivent le changement de jour ======== */
let DAYSEEN=today(),DAYPEND=false;
/* en entrant dans « Planning clients » ou « Planning staff » depuis une autre page : on repart d’aujourd’hui */
function dayReset(v){
  if(v==='staff'||v==='resa'){plSel=null;plSelPlan=null;slotDay=today();weekOff=0}
}
/* l’appli reste ouverte à minuit, ou est rouverte le lendemain : le jour affiché suit la date réelle */
function dayFollow(){
  const t=today();if(t===DAYSEEN)return;
  const old=DAYSEEN;DAYSEEN=t;
  if(slotDay===old||slotDay<t)slotDay=t;
  if(cxDay===old)cxDay=t;
  plSel=null;plSelPlan=null;weekOff=0;DAYPEND=true;
}
function dayDraw(){
  if(!DAYPEND)return;
  if(document.querySelector('#modal .modal'))return;
  const a=document.activeElement;if(a&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)&&a.type!=='button'&&a.type!=='checkbox')return;
  DAYPEND=false;
  if(view==='accueil'||view==='resa'||view==='staff'){try{render()}catch(e){console.warn(e)}}
}
function dayTick(){try{dayFollow();dayDraw();poRefresh()}catch(e){console.warn(e)}}
setInterval(dayTick,30000);
addEventListener('focus',dayTick);addEventListener('pageshow',dayTick);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')dayTick()});
/* ======== v76 : « En poste maintenant » — qui travaille à l’heure qu’il est ========
   Lit le planning du jour réel (échanges de shifts validés et congés compris) et l’heure de l’appareil.
   Affiché sur l’Accueil (carte « Équipe en poste », bandeau et tuile), dans le planning équipe et dans l’onglet « Jour » du jour même.
   Mis à jour sur place toutes les 30 s (sans redessiner la page) : on ne perd ni la saisie en cours, ni le défilement. */
const poH=()=>{const n=new Date();return n.getHours()+n.getMinutes()/60};
/* créneau de 2 h en cours dans la grille du jour (−1 : hors des heures du planning) */
function poSlot(){const ds=today(),i=Math.floor((poH()-10)/2);return i>=0&&i<nrows(planFor(ds),dowOf(ds))?i:-1}
/* all=true : toute l’équipe (pour un simple compteur) ; sinon seulement les personnes que cet appareil a le droit de voir */
function poNow(all){
  const ds=today(),h=poH(),E=1e-9,r={ds,h,on:[],soon:[],done:[],lv:[],planned:0,slot:poSlot()};
  (all?S.staff:visStaff()).forEach(s=>{
    if(onLeave(s.id,ds)){r.lv.push(s);return}
    const c=cellsOf(planFor(ds),ds,s.id).map(([i,v])=>{const g=plSeg(ds,s.id,i,v);return {a:g[0],b:g[1],v}}).filter(x=>x.b>x.a+E).sort((x,y)=>x.a-y.a||x.b-y.b);
    if(!c.length)return;
    r.planned++;
    /* des créneaux qui se suivent forment un seul bloc : « jusqu’à 18h », pas « jusqu’à 14h » puis « jusqu’à 16h » */
    const B=[];c.forEach(x=>{const l=B[B.length-1];if(l&&x.a<=l.b+E)l.b=Math.max(l.b,x.b);else B.push({a:x.a,b:x.b})});
    const cur=B.find(b=>b.a<=h+E&&h<b.b-E),nx=B.find(b=>b.a>h+E);
    if(cur){const cc=c.find(x=>x.a<=h+E&&h<x.b-E);r.on.push({s,until:cur.b,g:!!cc&&cc.v==='g'})}
    else if(nx)r.soon.push({s,from:nx.a,back:B.some(b=>b.b<=h+E)});
    else r.done.push(s);
  });
  const nm=(x,y)=>x.s.name.localeCompare(y.s.name,'fr');
  r.on.sort((x,y)=>x.until-y.until||nm(x,y));
  r.soon.sort((x,y)=>x.from-y.from||nm(x,y));
  return r;
}
const poIdSet=()=>new Set(poNow().on.map(x=>x.s.id));
/* empreinte de l’état : la carte n’est redessinée que si quelqu’un arrive, part ou reprend */
const poSig=r=>[r.on.map(x=>x.s.id+'@'+x.until+(x.g?'g':'')).join(','),r.soon.map(x=>x.s.id+'@'+x.from+(x.back?'b':'')).join(','),r.done.map(s=>s.id).join(','),r.planned].join('|');
const poEnd=h=>h>=24?'minuit':plF(h);
const poHero=r=>r.on.length?r.on.length+' en poste maintenant':r.planned?'personne en poste pour l’instant':'0 en poste';
const poKpi=r=>r.on.length+'<small> / '+r.planned+'</small>';
function poRow(s,pill,cls,sub){
  const c=scol(s);
  return `<div class="row ${cls}"><span class="avatar" style="background:${c};color:${inkOn(c)}">${esc(initials(s.name))}</span><span class="grow"><b>${esc(s.name)}</b><span class="muted">${esc(ROLE[s.role]||'')}${sub?' · <span class="nw">'+esc(sub)+'</span>':''}</span></span><span class="pill ${cls==='po-on'?'ok':''}">${esc(pill)}</span></div>`;
}
function poCard(kind){
  const r=poNow(),sig=esc(poSig(r)),nb=r.on.length;
  if(kind==='plan'){
    const chips=r.on.map(x=>{const c=scol(x.s);return `<span class="poc"><span class="pav" style="background:${c};color:${inkOn(c)}">${esc(initials(x.s.name))}</span><span><b>${esc(fname(x.s))}</b><small>${x.g?'gestion · ':''}jusqu’à ${poEnd(x.until)}</small></span></span>`}).join('');
    const nx=r.soon.slice(0,4).map(x=>esc(fname(x.s))+' à '+plF(x.from)).join(', ');
    return `<div class="card ponow poplan" data-po="plan" data-sig="${sig}" role="status"><div class="poh"><h3>En poste maintenant</h3><span class="pill ${nb?'ok':''}">${nb}</span></div>${nb?`<div class="pochips">${chips}</div>`:`<p class="muted posub">${r.planned?'Personne n’est en poste à cette heure.':'Personne n’est planifié aujourd’hui.'}</p>`}${nx?`<p class="muted posub">Ensuite : ${nx}${r.soon.length>4?'…':''}.</p>`:''}</div>`;
  }
  const lab=s=>shiftLabel(r.ds,s.id);
  const on=r.on.map(x=>poRow(x.s,'jusqu’à '+poEnd(x.until),'po-on',(x.g?'gestion · ':'')+lab(x.s))).join('');
  const soon=r.soon.map(x=>poRow(x.s,(x.back?'reprend à ':'à ')+plF(x.from),'po-soon',lab(x.s))).join('');
  const dn=r.done.length?`<p class="muted podone">Terminé pour aujourd’hui : ${r.done.map(s=>esc(fname(s))).join(', ')}.</p>`:'';
  return `<div class="card ponow" data-po="home" data-sig="${sig}"><h3>Équipe en poste <span class="pill ${nb?'ok':''}">${nb} maintenant</span></h3>${on||`<p class="muted">${r.planned?'Personne n’est en poste à cette heure.':'Personne n’est planifié aujourd’hui.'}</p>`}${soon?`<p class="pogr">Plus tard aujourd’hui</p>${soon}`:''}${dn}</div>`;
}
/* Accueil : la carte « Équipe en poste » devient « En poste maintenant » (elle n’existe pas pour les appareils qui ne voient pas toute l’équipe) */
function poHome(m){
  const c=[...m.querySelectorAll('.home .card')].find(x=>{const h=x.querySelector('h3');return h&&/^Équipe en poste/.test(h.textContent)});
  if(c)c.outerHTML=poCard('home');
}
/* mise à jour sur place */
function poRefresh(){
  const cards=document.querySelectorAll('.ponow[data-po]'),hero=document.querySelector('[data-po="hero"]'),kpi=document.querySelector('[data-po="kpi"]'),pl=document.querySelectorAll('.pln.today');
  if(!cards.length&&!hero&&!kpi&&!pl.length)return;
  if(cards.length||pl.length){
    const r=poNow(),sg=poSig(r);
    cards.forEach(el=>{if(el.dataset.sig!==sg)el.outerHTML=poCard(el.dataset.po)});
    const ids=new Set(r.on.map(x=>x.s.id));
    document.querySelectorAll('.pln.today tr.pr[data-sid]').forEach(tr=>tr.classList.toggle('pon',ids.has(tr.dataset.sid)));
    document.querySelectorAll('.pln.today thead th.slh').forEach((th,i)=>th.classList.toggle('nowc',i===r.slot));
  }
  if(hero||kpi){
    const a=poNow(true);
    if(hero&&hero.textContent!==poHero(a))hero.textContent=poHero(a);
    if(kpi&&kpi.innerHTML!==poKpi(a))kpi.innerHTML=poKpi(a);
  }
}
/* ======== v77 : premier écran — « c’est l’administrateur qui crée les comptes » ======== */
function gateNoAcc(){
  const on=cloudOn();
  gateShell(`<h2>Pas encore de compte ?</h2>
   <p class="muted" style="text-align:center">Dans Lago, <b>c’est l’administrateur qui crée les comptes</b> de l’équipe. Vous n’avez rien à créer vous-même.</p>
   <ol class="gsteps"><li>Demandez à l’administrateur de créer votre compte (Paramètres › Comptes). Il vous donne votre identifiant et un mot de passe provisoire.</li>
   ${on?'':'<li>Cet appareil n’est pas encore relié à l’équipe : ouvrez le lien d’équipe qu’il vous envoie, ou touchez « Rejoindre l’équipe avec un lien » ci-dessous.</li>'}
   <li>Revenez sur cet écran, touchez votre prénom et connectez-vous. Vous pourrez changer le mot de passe dans « Mon compte ».</li></ol>
   ${on&&signupOk()?'<p class="muted" style="text-align:center;font-size:13px;margin:0 0 8px">Vous pouvez aussi lui envoyer une demande : il la validera.</p><button class="btn" data-act="g_new" style="width:100%">Demander mon compte</button>':''}
   <div class="gfoot"><button type="button" class="btn" data-act="g_back">Retour</button></div>`);
}
document.addEventListener('click',e=>{if(e.target.closest('[data-act="g_noacc"]'))gateNoAcc()});
